const FONT_CSS = `
@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap');
.f-display{font-family:'Space Grotesk',sans-serif;}
.f-body{font-family:'IBM Plex Sans',sans-serif;}
.f-mono{font-family:'IBM Plex Mono',monospace;}
.grid-paper{background-image:linear-gradient(${T.line}22 1px, transparent 1px),linear-gradient(90deg, ${T.line}22 1px, transparent 1px);background-size:28px 28px;}
.frame{position:relative;}
.frame .corner{position:absolute;width:14px;height:14px;border-color:${T.cyan};opacity:.55;}
.frame .corner.tl{top:-1px;left:-1px;border-top:2px solid;border-left:2px solid;}
.frame .corner.tr{top:-1px;right:-1px;border-top:2px solid;border-right:2px solid;}
.frame .corner.bl{bottom:-1px;left:-1px;border-bottom:2px solid;border-left:2px solid;}
.frame .corner.br{bottom:-1px;right:-1px;border-bottom:2px solid;border-right:2px solid;}
.stamp{transform:rotate(-6deg);border:2px solid currentColor;border-radius:4px;padding:2px 10px;font-family:'IBM Plex Mono',monospace;letter-spacing:.08em;}
.scrollbar-thin::-webkit-scrollbar{width:6px;height:6px;}
.scrollbar-thin::-webkit-scrollbar-thumb{background:${T.line};border-radius:3px;}
@media print{.no-print{display:none !important;}}
`;

function Frame({ children, className = "", style = {} }) {
  return (
    <div className={`frame ${className}`} style={style}>
      <span className="corner tl" /><span className="corner tr" /><span className="corner bl" /><span className="corner br" />
      {children}
    </div>
  );
}

