const TRAINING_DIUVITAE_HTML = "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1\">\n<title>Diu Vitae \u00b7 Transfer\u00eancias, Posicionamento e Comunica\u00e7\u00e3o</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600;9..144,700&family=Work+Sans:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --cream:#F6F2E7;\n    --paper:#FFFDF8;\n    --ink:#2A2A20;\n    --ink-soft:#5B5B4C;\n    --forest:#3B4A2E;\n    --forest-dark:#28331C;\n    --lime:#D7C93B;\n    --lime-deep:#B7A824;\n    --lime-soft:#F1EAB0;\n    --clay:#C97B5F;\n    --clay-soft:#F1DACD;\n    --sage:#E7EEDC;\n    --good:#3E7A45;\n    --good-soft:#DCEBDD;\n    --bad:#B5493A;\n    --bad-soft:#F4DCD7;\n    --radius: 20px;\n    --radius-sm: 12px;\n    --shadow: 0 10px 30px -14px rgba(42,42,32,0.35);\n  }\n  *{box-sizing:border-box;}\n  html{scroll-behavior:smooth;}\n  body{\n    margin:0;\n    background:var(--cream);\n    background-image:\n      radial-gradient(circle at 8% 4%, rgba(215,201,59,0.16), transparent 40%),\n      radial-gradient(circle at 96% 12%, rgba(201,123,95,0.14), transparent 38%);\n    color:var(--ink);\n    font-family:'Work Sans', sans-serif;\n    line-height:1.5;\n    -webkit-font-smoothing:antialiased;\n  }\n  h1,h2,h3,.display{\n    font-family:'Fraunces', serif;\n    font-weight:600;\n    letter-spacing:-0.01em;\n    color:var(--forest-dark);\n    margin:0;\n  }\n  button{font-family:inherit;}\n  .wrap{max-width:980px;margin:0 auto;padding:0 20px 90px;}\n  a{color:inherit;}\n\n  /* ---------- header ---------- */\n  header.top{\n    position:sticky; top:0; z-index:40;\n    background:rgba(246,242,231,0.92);\n    backdrop-filter:blur(8px);\n    border-bottom:1px solid rgba(59,74,46,0.12);\n  }\n  .top-inner{\n    max-width:980px;margin:0 auto;padding:12px 20px;\n    display:flex;align-items:center;gap:12px;justify-content:space-between;\n  }\n  .brand{display:flex;align-items:center;gap:10px;cursor:pointer;}\n  .brand-mark{\n    width:34px;height:34px;border-radius:50%;\n    background:conic-gradient(from -40deg, var(--lime) 0deg, var(--lime-soft) 120deg, transparent 200deg, var(--lime) 360deg);\n    position:relative;\n    box-shadow:0 3px 8px -2px rgba(183,168,36,0.6);\n  }\n  .brand-mark::after{\n    content:'';position:absolute;inset:7px;border-radius:50%;background:var(--cream);\n  }\n  .brand-name{font-family:'Fraunces',serif;font-weight:600;font-size:16px;color:var(--forest-dark);}\n  .brand-sub{font-size:10.5px;letter-spacing:0.08em;text-transform:uppercase;color:var(--ink-soft);}\n  .top-actions{display:flex;align-items:center;gap:10px;}\n  .toggle-btn{\n    border:1px solid rgba(59,74,46,0.3);\n    background:var(--paper);\n    color:var(--forest-dark);\n    padding:8px 14px;\n    border-radius:999px;\n    font-size:12.5px;font-weight:600;\n    cursor:pointer;\n    display:flex;align-items:center;gap:6px;\n    transition:.15s;\n  }\n  .toggle-btn:hover{border-color:var(--forest);}\n  .toggle-btn.on{background:var(--forest-dark);color:var(--lime-soft);border-color:var(--forest-dark);}\n\n  /* ---------- crach\u00e1 / progress ---------- */\n  .cracha{\n    display:flex;align-items:center;gap:6px;\n  }\n  .stamp{\n    width:26px;height:26px;border-radius:50%;\n    display:flex;align-items:center;justify-content:center;\n    font-size:12px;font-weight:700;\n    border:2px dashed rgba(59,74,46,0.35);\n    color:var(--ink-soft);\n    background:transparent;\n  }\n  .stamp.done{\n    border-style:solid; border-color:var(--forest);\n    background:var(--forest); color:var(--lime-soft);\n  }\n\n  /* ---------- home ---------- */\n  .hero{padding:52px 0 28px;text-align:left;}\n  .eyebrow{\n    display:inline-flex;align-items:center;gap:8px;\n    font-size:12px;letter-spacing:0.14em;text-transform:uppercase;\n    color:var(--forest); font-weight:700;\n    background:var(--sage); padding:6px 12px 6px 8px; border-radius:999px;\n    margin-bottom:18px;\n  }\n  .eyebrow .dot{width:7px;height:7px;border-radius:50%;background:var(--clay);}\n  .hero h1{font-size:clamp(30px,5vw,46px); line-height:1.06; max-width:16ch;}\n  .hero p.lede{\n    margin-top:16px; max-width:56ch; color:var(--ink-soft); font-size:16.5px;\n  }\n  .hero-foot{display:flex;flex-wrap:wrap;gap:14px;align-items:center;margin-top:26px;}\n  .cta{\n    background:var(--forest-dark); color:var(--lime-soft);\n    border:none; padding:14px 24px; border-radius:999px;\n    font-weight:700; font-size:15px; cursor:pointer;\n    box-shadow:var(--shadow);\n    transition:.15s;\n  }\n  .cta:hover{transform:translateY(-1px); background:var(--forest);}\n  .cracha-card{\n    background:var(--paper); border-radius:var(--radius);\n    padding:14px 18px; box-shadow:var(--shadow);\n    display:flex; align-items:center; gap:14px;\n    border:1px solid rgba(59,74,46,0.1);\n  }\n  .cracha-card .label{font-size:12px;color:var(--ink-soft);}\n  .cracha-card .count{font-family:'Fraunces',serif;font-weight:700;font-size:20px;color:var(--forest-dark);}\n\n  /* module grid */\n  .section-label{\n    font-size:12px;letter-spacing:0.12em;text-transform:uppercase;\n    color:var(--ink-soft); font-weight:700; margin:44px 0 16px;\n    display:flex;align-items:center;gap:10px;\n  }\n  .section-label::after{content:'';flex:1;height:1px;background:rgba(59,74,46,0.18);}\n  .grid-modules{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px;}\n  .m-card{\n    background:var(--paper); border-radius:var(--radius);\n    padding:22px; cursor:pointer; text-align:left; border:1px solid rgba(59,74,46,0.1);\n    box-shadow:var(--shadow); transition:.18s; position:relative; overflow:hidden;\n  }\n  .m-card:hover{transform:translateY(-3px);}\n  .m-card .num{\n    font-family:'Fraunces',serif; font-size:13px; color:var(--clay); font-weight:700;\n    letter-spacing:0.04em;\n  }\n  .m-card .icon{font-size:28px;margin:10px 0 8px;}\n  .m-card h3{font-size:19px; margin-bottom:6px;}\n  .m-card .tag{\n    display:inline-block; font-size:11px; font-weight:700; letter-spacing:0.04em;\n    color:var(--forest); background:var(--sage); padding:3px 9px; border-radius:999px; margin-bottom:10px;\n  }\n  .m-card p{font-size:13.5px;color:var(--ink-soft); margin:0;}\n  .m-card .check{\n    position:absolute; top:18px; right:18px; width:26px; height:26px; border-radius:50%;\n    background:var(--good); color:#fff; display:flex; align-items:center; justify-content:center;\n    font-size:13px; font-weight:700;\n  }\n\n  /* ---------- illustrations ---------- */\n  .hero-row{display:grid; grid-template-columns:1.15fr 0.85fr; gap:34px; align-items:center;}\n  @media(max-width:760px){.hero-row{grid-template-columns:1fr;}}\n  .hero-illus{\n    background:linear-gradient(160deg, var(--sage) 0%, #DCE6CC 100%);\n    border-radius:calc(var(--radius) + 6px);\n    padding:18px; box-shadow:var(--shadow); border:1px solid rgba(59,74,46,0.12);\n    position:relative; overflow:hidden;\n  }\n  .hero-illus svg{width:100%;height:auto;display:block;}\n  .corner-leaf{position:absolute; width:70px; opacity:0.9;}\n  .corner-leaf.tl{top:-10px; left:-14px; transform:rotate(-12deg);}\n  .corner-leaf.br{bottom:-14px; right:-16px; transform:rotate(168deg);}\n\n  .module-illus{\n    background:linear-gradient(160deg, var(--sage) 0%, #E4ECD8 100%);\n    border-radius:var(--radius); padding:14px 16px 6px; margin:20px 0 6px;\n    border:1px solid rgba(59,74,46,0.1); position:relative; overflow:hidden;\n  }\n  .module-illus svg{width:100%; height:auto; max-height:210px; display:block; margin:0 auto;}\n  .module-illus .cap{\n    text-align:center; font-size:11.5px; color:var(--ink-soft); padding:8px 0 10px; font-style:italic;\n  }\n\n  .pos-ref-row{display:grid; grid-template-columns:1fr 1fr; gap:14px; margin:18px 0 8px;}\n  @media(max-width:560px){.pos-ref-row{grid-template-columns:1fr;}}\n  .pos-ref{background:var(--paper); border:1px solid rgba(59,74,46,0.12); border-radius:var(--radius-sm); padding:12px;}\n  .pos-ref svg{width:100%;height:auto;display:block;}\n  .pos-ref .cap{font-size:12.5px; font-weight:700; color:var(--forest-dark); text-align:center; margin-top:4px;}\n  .pos-ref .cap span{display:block; font-weight:500; color:var(--ink-soft); font-size:11px;}\n\n  .bed-figure-box{\n    background:linear-gradient(160deg, var(--sage) 0%, #E4ECD8 100%);\n    border-radius:var(--radius-sm); padding:10px; margin-bottom:18px; border:1px solid rgba(59,74,46,0.12);\n  }\n  .bed-figure-box svg{width:100%; height:auto; display:block;}\n\n  .facilitator-box{\n    margin-top:46px; background:var(--forest-dark); color:var(--sage); border-radius:var(--radius);\n    padding:24px 26px; box-shadow:var(--shadow);\n  }\n  .facilitator-box h3{color:var(--lime-soft); font-size:17px; margin-bottom:8px;}\n  .facilitator-box p{margin:0; font-size:13.5px; color:#D9E2CB; max-width:60ch;}\n\n  /* ---------- module view ---------- */\n  .back-btn{\n    display:inline-flex; align-items:center; gap:6px; background:none; border:none;\n    color:var(--forest); font-weight:700; font-size:13.5px; cursor:pointer; padding:22px 0 0;\n  }\n  .m-head{margin:14px 0 30px;}\n  .m-head .num-tag{display:flex;align-items:center;gap:10px;margin-bottom:10px;}\n  .m-head .num-tag .num{font-family:'Fraunces',serif;font-size:14px;color:var(--clay);font-weight:700;}\n  .m-head .num-tag .tag{font-size:11px;font-weight:700;letter-spacing:0.05em;color:var(--forest);background:var(--sage);padding:3px 10px;border-radius:999px;}\n  .m-head h2{font-size:clamp(26px,4vw,36px);}\n  .m-head p{color:var(--ink-soft); max-width:62ch; margin-top:10px; font-size:15.5px;}\n\n  .lesson-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:14px;margin:22px 0 8px;}\n  .l-card{background:var(--paper); border:1px solid rgba(59,74,46,0.1); border-radius:var(--radius-sm); padding:16px 18px;}\n  .l-card .t{font-weight:700;font-size:14.5px;color:var(--forest-dark);margin-bottom:5px;}\n  .l-card .b{font-size:13.5px;color:var(--ink-soft);}\n\n  details.tip{margin:26px 0; background:var(--clay-soft); border-radius:var(--radius-sm); padding:2px 18px; border:1px solid rgba(201,123,95,0.35);}\n  details.tip summary{cursor:pointer; padding:14px 0; font-weight:700; font-size:13.5px; color:#7A3E2A; list-style:none; display:flex; align-items:center; gap:8px;}\n  details.tip summary::-webkit-details-marker{display:none;}\n  details.tip summary::before{content:'\ud83d\udca1';}\n  details.tip p{margin:0 0 16px; font-size:13.5px; color:#6B3323;}\n\n  .panel{\n    background:var(--paper); border-radius:var(--radius); padding:26px; margin:22px 0;\n    border:1px solid rgba(59,74,46,0.1); box-shadow:var(--shadow);\n  }\n  .panel h4{font-size:12px; letter-spacing:0.1em; text-transform:uppercase; color:var(--clay); font-weight:700; margin-bottom:14px;}\n  .panel .prompt{font-family:'Fraunces',serif; font-size:19px; color:var(--forest-dark); margin-bottom:16px; font-weight:600;}\n\n  /* sequence activity */\n  .pool{display:flex; flex-wrap:wrap; gap:8px; margin-bottom:16px;}\n  .chip{\n    background:var(--sage); border:1px solid rgba(59,74,46,0.18); color:var(--forest-dark);\n    padding:10px 14px; border-radius:999px; font-size:13.5px; cursor:pointer; font-weight:600;\n    transition:.12s;\n  }\n  .chip:hover{background:#DCE6CC;}\n  .chip.disabled{opacity:0.35; cursor:default; pointer-events:none;}\n  .order-list{list-style:none; margin:0 0 16px; padding:0; display:flex; flex-direction:column; gap:8px;}\n  .order-list li{\n    display:flex; align-items:center; gap:10px; background:var(--cream); border-radius:var(--radius-sm);\n    padding:10px 14px; font-size:13.5px; border:1px solid rgba(59,74,46,0.12);\n  }\n  .order-list li .badge-n{\n    width:22px;height:22px;border-radius:50%;background:var(--forest-dark);color:var(--lime-soft);\n    display:flex;align-items:center;justify-content:center;font-size:11.5px;font-weight:700;flex:none;\n  }\n  .order-list li.correct{border-color:var(--good); background:var(--good-soft);}\n  .order-list li.wrong{border-color:var(--bad); background:var(--bad-soft);}\n\n  .btn-row{display:flex; gap:10px; flex-wrap:wrap; margin-top:6px;}\n  .btn{\n    border:1px solid rgba(59,74,46,0.3); background:var(--paper); color:var(--forest-dark);\n    padding:10px 18px; border-radius:999px; font-weight:700; font-size:13.5px; cursor:pointer; transition:.13s;\n  }\n  .btn:hover{border-color:var(--forest);}\n  .btn.primary{background:var(--forest-dark); color:var(--lime-soft); border-color:var(--forest-dark);}\n  .btn.primary:hover{background:var(--forest);}\n  .btn.ghost{border-color:transparent; color:var(--ink-soft);}\n  .btn:disabled{opacity:0.4;cursor:default;}\n\n  .feedback{margin-top:14px; padding:12px 16px; border-radius:var(--radius-sm); font-size:13.5px; display:none;}\n  .feedback.show{display:block;}\n  .feedback.good{background:var(--good-soft); color:#295F31; border:1px solid rgba(62,122,69,0.3);}\n  .feedback.bad{background:var(--bad-soft); color:#7A2C20; border:1px solid rgba(181,73,58,0.3);}\n\n  /* MCQ */\n  .mcq .opt{\n    display:block; width:100%; text-align:left; background:var(--cream); border:1px solid rgba(59,74,46,0.15);\n    border-radius:var(--radius-sm); padding:12px 16px; margin-bottom:9px; font-size:14px; cursor:pointer; color:var(--ink);\n    transition:.12s;\n  }\n  .mcq .opt:hover{border-color:var(--forest);}\n  .mcq .opt.correct{background:var(--good-soft); border-color:var(--good); font-weight:700;}\n  .mcq .opt.wrong{background:var(--bad-soft); border-color:var(--bad);}\n  .mcq .opt.disabled{pointer-events:none;}\n  .mcq .opt .mark{float:right;}\n\n  /* slider */\n  .angle-wrap{max-width:460px;}\n  .angle-readout{font-family:'Fraunces',serif; font-size:40px; color:var(--forest-dark); font-weight:700;}\n  input[type=range]{\n    width:100%; -webkit-appearance:none; height:10px; border-radius:6px; margin:18px 0 10px;\n    background:var(--sage);\n  }\n  input[type=range]::-webkit-slider-thumb{\n    -webkit-appearance:none; width:24px; height:24px; border-radius:50%; background:var(--forest-dark);\n    cursor:pointer; border:3px solid var(--lime-soft); box-shadow:0 2px 6px rgba(0,0,0,0.25);\n  }\n  input[type=range]::-moz-range-thumb{\n    width:24px; height:24px; border-radius:50%; background:var(--forest-dark); border:3px solid var(--lime-soft); cursor:pointer;\n  }\n  .zone-legend{display:flex; gap:16px; font-size:11.5px; color:var(--ink-soft); margin-bottom:16px; flex-wrap:wrap;}\n  .zone-legend span{display:flex;align-items:center;gap:6px;}\n  .zone-legend i{width:10px;height:10px;border-radius:3px;display:inline-block;}\n\n  /* match pairs */\n  .match-grid{display:grid; grid-template-columns:1fr 1fr; gap:20px;}\n  @media(max-width:620px){.match-grid{grid-template-columns:1fr;}}\n  .match-col .m-item{\n    background:var(--cream); border:1px solid rgba(59,74,46,0.15); border-radius:var(--radius-sm);\n    padding:11px 14px; margin-bottom:8px; font-size:13.5px; cursor:pointer; transition:.12s;\n  }\n  .match-col .m-item.selected{border-color:var(--forest); background:var(--sage);}\n  .match-col .m-item.matched{background:var(--good-soft); border-color:var(--good); opacity:0.75; cursor:default;}\n  .match-col .m-item.flash-bad{background:var(--bad-soft); border-color:var(--bad);}\n\n  /* hotspots / room */\n  .scene{\n    position:relative; background:var(--sage); border-radius:var(--radius); overflow:hidden;\n    aspect-ratio:16/10; border:1px solid rgba(59,74,46,0.15);\n  }\n  .hotspot{\n    position:absolute; width:38px; height:38px; border-radius:50%;\n    border:2px dashed rgba(42,42,32,0.4); background:rgba(255,253,248,0.55);\n    cursor:pointer; transform:translate(-50%,-50%); display:flex;align-items:center;justify-content:center;\n    font-size:15px; transition:.12s;\n  }\n  .hotspot:hover{background:rgba(255,253,248,0.9);}\n  .hotspot.selected{border-style:solid; border-color:var(--forest-dark); background:var(--lime-soft);}\n  .hotspot.reveal-correct{border-color:var(--good); background:var(--good-soft);}\n  .hotspot.reveal-wrong{border-color:var(--bad); background:var(--bad-soft);}\n  .hotspot.reveal-missed{border-color:var(--bad); background:transparent; animation:pulse 1.4s infinite;}\n  @keyframes pulse{0%,100%{box-shadow:0 0 0 0 rgba(181,73,58,0.5);}50%{box-shadow:0 0 0 8px rgba(181,73,58,0);}}\n\n  /* dialogue */\n  .scene-num{font-size:12px; color:var(--clay); font-weight:700; margin-bottom:6px;}\n\n  /* sort fazer/evitar */\n  .sort-item{\n    display:flex; align-items:center; justify-content:space-between; gap:12px;\n    background:var(--cream); border:1px solid rgba(59,74,46,0.15); border-radius:var(--radius-sm);\n    padding:10px 14px; margin-bottom:8px; font-size:13.5px;\n  }\n  .sort-item.placed-good{background:var(--good-soft); border-color:var(--good);}\n  .sort-item.placed-bad{background:var(--bad-soft); border-color:var(--bad);}\n  .sort-btns{display:flex; gap:6px; flex:none;}\n  .sort-btns button{\n    border:1px solid rgba(59,74,46,0.3); background:var(--paper); border-radius:999px; padding:6px 10px;\n    font-size:11.5px; font-weight:700; cursor:pointer;\n  }\n  .sort-btns button:hover{border-color:var(--forest);}\n  .sort-btns button:disabled{opacity:0.3;}\n\n  .score-pill{\n    display:inline-flex; align-items:center; gap:8px; background:var(--sage); color:var(--forest-dark);\n    padding:8px 16px; border-radius:999px; font-weight:700; font-size:13px; margin-top:6px;\n  }\n\n  .concluir-bar{\n    display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:16px;\n    margin-top:44px; padding-top:26px; border-top:1px solid rgba(59,74,46,0.15);\n  }\n\n  /* completion */\n  .complete-hero{text-align:center; padding:60px 0 20px;}\n  .complete-hero .badge-big{\n    width:96px;height:96px;border-radius:50%;margin:0 auto 22px;\n    background:conic-gradient(from -30deg, var(--lime) 0deg, var(--clay) 180deg, var(--lime) 360deg);\n    display:flex;align-items:center;justify-content:center; box-shadow:var(--shadow);\n  }\n  .complete-hero .badge-big::after{content:'\u2713';font-size:38px;color:var(--forest-dark);font-weight:700;}\n  .complete-hero .badge-big.pending::after{content:'\u27f3';}\n  .complete-hero h1{font-size:clamp(26px,4.5vw,38px);}\n  .complete-hero p{max-width:52ch;margin:14px auto 0;color:var(--ink-soft);}\n  .results-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px;margin:34px 0;}\n  .result-card{background:var(--paper); border:1px solid rgba(59,74,46,0.1); border-radius:var(--radius-sm); padding:16px 18px; box-shadow:var(--shadow);}\n  .result-card .t{font-weight:700; font-size:13.5px; color:var(--forest-dark); margin-bottom:6px;}\n  .result-card .s{font-family:'Fraunces',serif; font-size:22px; color:var(--clay); font-weight:700;}\n  .quote-close{\n    background:var(--forest-dark); color:var(--sage); border-radius:var(--radius); padding:30px 32px; margin-top:30px;\n    font-family:'Fraunces',serif; font-size:19px; line-height:1.5; text-align:center;\n  }\n  .quote-close b{color:var(--lime-soft);}\n  .print-note{text-align:center;margin-top:24px;font-size:12.5px;color:var(--ink-soft);}\n\n  /* certificate */\n  .certificate-frame{\n    position:relative; background:var(--paper); border-radius:10px; margin:30px 0;\n    padding:56px 40px; text-align:center; box-shadow:var(--shadow);\n    border:2px solid var(--forest-dark); outline:6px solid var(--lime-soft); outline-offset:-14px;\n  }\n  .cert-leaf{position:absolute; font-size:34px; opacity:0.7;}\n  .cert-leaf.tl{top:14px; left:16px; transform:rotate(-25deg);}\n  .cert-leaf.br{bottom:14px; right:16px; transform:rotate(155deg);}\n  .cert-eyebrow{font-size:12px; letter-spacing:0.18em; text-transform:uppercase; color:var(--clay); font-weight:700; margin-bottom:18px;}\n  .cert-course{font-family:'Fraunces',serif; font-size:15px; color:var(--ink-soft); max-width:46ch; margin:0 auto 26px;}\n  .cert-name{font-family:'Fraunces',serif; font-size:clamp(28px,5vw,42px); font-weight:700; color:var(--forest-dark); border-bottom:2px solid var(--sage); display:inline-block; padding:0 12px 10px; margin-bottom:10px;}\n  .cert-role{font-size:13px; font-weight:700; letter-spacing:0.05em; text-transform:uppercase; color:var(--clay); margin-bottom:24px;}\n  .cert-body{max-width:52ch; margin:0 auto 30px; font-size:14px; color:var(--ink-soft); line-height:1.6;}\n  .cert-footer{display:flex; justify-content:space-between; align-items:flex-end; max-width:420px; margin:0 auto; padding-top:18px; border-top:1px solid rgba(59,74,46,0.15);}\n  .cert-date{font-size:13px; color:var(--ink-soft);}\n  .cert-sign{font-family:'Fraunces',serif; font-weight:700; color:var(--forest-dark); font-size:16px; text-align:right;}\n  .cert-sign span{display:block; font-family:'Work Sans',sans-serif; font-weight:500; font-size:10.5px; color:var(--ink-soft); text-transform:uppercase; letter-spacing:0.06em;}\n\n  /* name gate */\n  .name-gate{\n    background:var(--paper); border-radius:var(--radius-sm); padding:14px 16px; margin-top:16px;\n    border:1px solid rgba(59,74,46,0.15); max-width:360px;\n  }\n  .name-gate label{font-size:12px; font-weight:700; color:var(--forest-dark); display:block; margin-bottom:6px;}\n  .name-gate input, .name-gate select{\n    width:100%; border:1px solid rgba(59,74,46,0.3); border-radius:999px; padding:10px 16px;\n    font-size:14px; font-family:inherit; background:var(--cream); color:var(--ink); box-sizing:border-box;\n  }\n  .name-gate select{appearance:auto;}\n  .name-gate input:focus, .name-gate select:focus{outline:2px solid var(--forest); outline-offset:1px;}\n  .name-gate .err{color:var(--bad); font-size:12px; margin-top:6px; display:none;}\n  .name-gate.error input, .name-gate.error select{border-color:var(--bad);}\n  .name-gate.error .err{display:block;}\n\n  /* presentation mode */\n  body.presentation{font-size:19px;}\n  body.presentation .m-head h2{font-size:clamp(34px,5vw,50px);}\n  body.presentation .panel .prompt{font-size:24px;}\n  body.presentation .mcq .opt{font-size:17px;padding:16px 18px;}\n  body.presentation .l-card .b{font-size:16px;}\n  body.presentation .l-card .t{font-size:17px;}\n  body.presentation .chip{font-size:16px;padding:12px 16px;}\n  body.presentation .btn{font-size:15px;padding:12px 22px;}\n\n  @media print{\n    @page{ size: landscape; margin: 8mm; }\n    html, body{width:100%; background:#fff !important; margin:0;}\n    header.top{display:none !important;}\n    #app > *:not(.certificate-frame){display:none !important;}\n    .wrap{padding:0; max-width:none; width:100%;}\n    .complete-hero, .results-grid, .quote-close, .btn-row, .print-note{display:none !important;}\n    .certificate-frame{\n      box-shadow:none; margin:0 auto; border-width:4px; outline-width:10px; outline-offset:-20px;\n      width:258mm; height:186mm; box-sizing:border-box;\n      page-break-inside:avoid; break-inside:avoid; overflow:hidden;\n      display:flex; flex-direction:column; align-items:center; justify-content:center;\n      padding:10mm 20mm;\n    }\n    .cert-eyebrow{font-size:15px; margin-bottom:14px;}\n    .cert-course{font-size:19px; max-width:60ch; margin-bottom:22px;}\n    .cert-name{font-size:50px; padding:0 20px 14px; margin-bottom:18px;}\n    .cert-role{font-size:16px; margin-bottom:20px;}\n    .cert-body{font-size:16px; max-width:65ch; margin:0 auto 28px; line-height:1.5;}\n    .cert-footer{max-width:560px; width:100%; padding-top:16px;}\n    .cert-date{font-size:14px;}\n    .cert-sign{font-size:18px;}\n    .cert-leaf{font-size:42px;}\n  }\n</style>\n</head>\n<body>\n\n<svg width=\"0\" height=\"0\" style=\"position:absolute;overflow:hidden;\">\n  <defs>\n    <radialGradient id=\"skinGrad\" cx=\"35%\" cy=\"30%\" r=\"80%\">\n      <stop offset=\"0%\" stop-color=\"#FBE3C9\"/>\n      <stop offset=\"100%\" stop-color=\"#EFC9A3\"/>\n    </radialGradient>\n    <linearGradient id=\"scrubGrad\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#4C5F3A\"/>\n      <stop offset=\"100%\" stop-color=\"#33421F\"/>\n    </linearGradient>\n    <linearGradient id=\"clayGrad\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#D68F73\"/>\n      <stop offset=\"100%\" stop-color=\"#BC6A4C\"/>\n    </linearGradient>\n    <linearGradient id=\"claySoftGrad\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#E6B39D\"/>\n      <stop offset=\"100%\" stop-color=\"#D08F72\"/>\n    </linearGradient>\n    <linearGradient id=\"grayHairGrad\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#F2F1EC\"/>\n      <stop offset=\"100%\" stop-color=\"#D6D4C8\"/>\n    </linearGradient>\n    <linearGradient id=\"darkHairGrad\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#4A3324\"/>\n      <stop offset=\"100%\" stop-color=\"#2E1F16\"/>\n    </linearGradient>\n    <linearGradient id=\"matGrad\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#FFFDF8\"/>\n      <stop offset=\"100%\" stop-color=\"#EDE7D6\"/>\n    </linearGradient>\n    <linearGradient id=\"floorGrad\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#EFE9D6\"/>\n      <stop offset=\"100%\" stop-color=\"#DED5B8\"/>\n    </linearGradient>\n\n    <!-- Caregiver, standing, helping pose -->\n    <g id=\"figCaregiver\">\n      <ellipse cx=\"60\" cy=\"193\" rx=\"30\" ry=\"6\" fill=\"#2A2A20\" opacity=\"0.10\"/>\n      <!-- legs -->\n      <path d=\"M44 128 L41 178 Q41 186 49 186 L52 186 Q56 186 56 178 L58 130 Z\" fill=\"#3E4E30\"/>\n      <path d=\"M76 128 L64 178 Q62 186 70 186 L73 186 Q79 186 80 178 L82 130 Z\" fill=\"#33421F\"/>\n      <ellipse cx=\"47\" cy=\"188\" rx=\"11\" ry=\"6\" fill=\"#A85F42\"/>\n      <ellipse cx=\"73\" cy=\"188\" rx=\"11\" ry=\"6\" fill=\"#A85F42\"/>\n      <!-- torso -->\n      <path d=\"M38 92 Q36 68 60 66 Q86 68 84 92 L88 128 Q60 138 34 128 Z\" fill=\"url(#scrubGrad)\"/>\n      <circle cx=\"66\" cy=\"84\" r=\"3.5\" fill=\"#D7C93B\"/>\n      <!-- arms, symmetric, drawn on top so shoulders always read clean -->\n      <path d=\"M40 92 Q20 100 22 126 Q23 134 31 131 Q28 110 46 98 Z\" fill=\"url(#scrubGrad)\"/>\n      <path d=\"M82 92 Q102 100 100 126 Q99 134 91 131 Q94 110 76 98 Z\" fill=\"url(#scrubGrad)\"/>\n      <circle cx=\"26\" cy=\"130\" r=\"6.5\" fill=\"url(#skinGrad)\"/>\n      <circle cx=\"96\" cy=\"130\" r=\"6.5\" fill=\"url(#skinGrad)\"/>\n      <!-- neck + head -->\n      <rect x=\"52\" y=\"52\" width=\"16\" height=\"14\" rx=\"7\" fill=\"url(#skinGrad)\"/>\n      <circle cx=\"60\" cy=\"38\" r=\"20\" fill=\"url(#skinGrad)\"/>\n      <path d=\"M40 36 Q38 15 60 15 Q82 15 80 38 Q79 24 60 23 Q42 23 41 38 Z\" fill=\"url(#darkHairGrad)\"/>\n      <path d=\"M78 26 Q86 34 80 46 Q77 49 75 45 Q80 36 74 28 Z\" fill=\"url(#darkHairGrad)\"/>\n      <circle cx=\"53\" cy=\"40\" r=\"1.8\" fill=\"#4A3324\"/>\n      <circle cx=\"66\" cy=\"40\" r=\"1.8\" fill=\"#4A3324\"/>\n      <path d=\"M55 47 Q60 50 65 47\" stroke=\"#B5745A\" stroke-width=\"1.6\" fill=\"none\" stroke-linecap=\"round\"/>\n    </g>\n\n    <!-- Elderly, seated (bent knees) -->\n    <g id=\"figElderlySit\">\n      <path d=\"M32 122 Q26 122 26 130 L27 152 Q27 158 34 158 L40 158 Q46 158 45 150 L43 128 Q42 122 36 122 Z\" fill=\"url(#claySoftGrad)\"/>\n      <path d=\"M80 122 Q74 122 74 130 L73 152 Q73 158 80 158 L86 158 Q92 158 91 150 L89 128 Q88 122 82 122 Z\" fill=\"url(#claySoftGrad)\"/>\n      <path d=\"M27 152 L25 180 Q25 187 32 187 L38 187 Q43 187 43 180 L44 154 Z\" fill=\"#3E4E30\" opacity=\"0.85\"/>\n      <path d=\"M73 152 L74 180 Q74 187 81 187 L87 187 Q92 187 91 180 L89 154 Z\" fill=\"#3E4E30\" opacity=\"0.85\"/>\n      <ellipse cx=\"34\" cy=\"189\" rx=\"10\" ry=\"5.5\" fill=\"#8A5A44\"/>\n      <ellipse cx=\"83\" cy=\"189\" rx=\"10\" ry=\"5.5\" fill=\"#8A5A44\"/>\n      <path d=\"M32 68 Q30 60 60 60 Q90 60 88 68 L92 124 Q60 136 28 124 Z\" fill=\"url(#clayGrad)\"/>\n      <path d=\"M34 78 Q22 86 24 108 Q25 114 32 112 Q29 96 42 84 Z\" fill=\"url(#clayGrad)\"/>\n      <path d=\"M86 78 Q98 86 96 108 Q95 114 88 112 Q91 96 78 84 Z\" fill=\"url(#clayGrad)\"/>\n      <circle cx=\"27\" cy=\"112\" r=\"5.5\" fill=\"url(#skinGrad)\"/>\n      <circle cx=\"93\" cy=\"112\" r=\"5.5\" fill=\"url(#skinGrad)\"/>\n      <rect x=\"52\" y=\"52\" width=\"16\" height=\"14\" rx=\"7\" fill=\"url(#skinGrad)\"/>\n      <circle cx=\"60\" cy=\"38\" r=\"19\" fill=\"url(#skinGrad)\"/>\n      <path d=\"M42 36 Q40 16 60 16 Q82 17 78 38 Q77 21 60 22 Q44 22 43 37 Z\" fill=\"url(#grayHairGrad)\"/>\n      <path d=\"M44 30 Q40 44 46 52\" stroke=\"url(#grayHairGrad)\" stroke-width=\"7\" fill=\"none\" stroke-linecap=\"round\"/>\n      <path d=\"M76 30 Q80 44 74 52\" stroke=\"url(#grayHairGrad)\" stroke-width=\"7\" fill=\"none\" stroke-linecap=\"round\"/>\n      <circle cx=\"51\" cy=\"40\" r=\"5.5\" fill=\"none\" stroke=\"#6B6B5C\" stroke-width=\"2\"/>\n      <circle cx=\"67\" cy=\"40\" r=\"5.5\" fill=\"none\" stroke=\"#6B6B5C\" stroke-width=\"2\"/>\n      <line x1=\"56.5\" y1=\"40\" x2=\"61.5\" y2=\"40\" stroke=\"#6B6B5C\" stroke-width=\"2\"/>\n      <path d=\"M53 49 Q60 52 65 49\" stroke=\"#9C5C42\" stroke-width=\"1.6\" fill=\"none\" stroke-linecap=\"round\"/>\n    </g>\n\n    <!-- Elderly, standing with cane -->\n    <g id=\"figElderlyStand\">\n      <ellipse cx=\"60\" cy=\"193\" rx=\"30\" ry=\"6\" fill=\"#2A2A20\" opacity=\"0.10\"/>\n      <path d=\"M44 128 L41 178 Q41 186 49 186 L52 186 Q56 186 56 178 L58 130 Z\" fill=\"#8FA07A\"/>\n      <path d=\"M76 128 L64 178 Q62 186 70 186 L73 186 Q79 186 80 178 L82 130 Z\" fill=\"#7E9068\"/>\n      <ellipse cx=\"47\" cy=\"188\" rx=\"11\" ry=\"6\" fill=\"#8A5A44\"/>\n      <ellipse cx=\"73\" cy=\"188\" rx=\"11\" ry=\"6\" fill=\"#8A5A44\"/>\n      <path d=\"M36 92 Q34 66 60 64 Q88 66 86 92 L90 128 Q60 139 32 128 Z\" fill=\"url(#clayGrad)\"/>\n      <!-- cane arm -->\n      <path d=\"M38 90 Q20 100 22 126 Q23 134 31 131 Q28 110 44 98 Z\" fill=\"url(#clayGrad)\"/>\n      <line x1=\"24\" y1=\"122\" x2=\"15\" y2=\"184\" stroke=\"#8A6A4A\" stroke-width=\"4.5\" stroke-linecap=\"round\"/>\n      <circle cx=\"14\" cy=\"187\" r=\"4.5\" fill=\"#5B4630\"/>\n      <!-- other arm relaxed -->\n      <path d=\"M86 90 Q102 100 98 122 Q96 130 89 126 Q92 110 80 98 Z\" fill=\"url(#clayGrad)\"/>\n      <ellipse cx=\"97\" cy=\"126\" rx=\"6\" ry=\"6.5\" fill=\"url(#skinGrad)\"/>\n      <rect x=\"52\" y=\"52\" width=\"16\" height=\"14\" rx=\"7\" fill=\"url(#skinGrad)\"/>\n      <circle cx=\"60\" cy=\"38\" r=\"19\" fill=\"url(#skinGrad)\"/>\n      <path d=\"M42 36 Q40 16 60 16 Q82 17 78 38 Q77 21 60 22 Q44 22 43 37 Z\" fill=\"url(#grayHairGrad)\"/>\n      <path d=\"M44 30 Q40 44 46 52\" stroke=\"url(#grayHairGrad)\" stroke-width=\"7\" fill=\"none\" stroke-linecap=\"round\"/>\n      <path d=\"M76 30 Q80 44 74 52\" stroke=\"url(#grayHairGrad)\" stroke-width=\"7\" fill=\"none\" stroke-linecap=\"round\"/>\n      <circle cx=\"53\" cy=\"40\" r=\"1.8\" fill=\"#6B6B5C\"/>\n      <circle cx=\"66\" cy=\"40\" r=\"1.8\" fill=\"#6B6B5C\"/>\n      <path d=\"M55 48 Q60 50 65 48\" stroke=\"#9C5C42\" stroke-width=\"1.6\" fill=\"none\" stroke-linecap=\"round\"/>\n    </g>\n  </defs>\n</svg>\n\n<header class=\"top\">\n  <div class=\"top-inner\">\n    <div class=\"brand\" onclick=\"goHome()\">\n      <div class=\"brand-mark\"></div>\n      <div>\n        <div class=\"brand-name\">Diu Vitae</div>\n        <div class=\"brand-sub\" id=\"brandSub\">Treinamento do Cuidador</div>\n      </div>\n    </div>\n    <div class=\"top-actions\">\n      <div class=\"cracha\" id=\"crachaMini\"></div>\n      <button class=\"toggle-btn\" id=\"presToggle\" onclick=\"togglePresentation()\">\ud83d\udda5\ufe0f Modo palestra</button>\n    </div>\n  </div>\n</header>\n\n<div class=\"wrap\" id=\"app\"></div>\n\n<script>\n/* ======================= DADOS ======================= */\nconst ROLE_OPTIONS = [\n  'Cuidador(a) de Idosos',\n  'T\u00e9cnico(a) de Enfermagem',\n  'Enfermeiro(a)',\n  'Fisioterapeuta',\n  'Terapeuta Ocupacional',\n  'Auxiliar de Servi\u00e7os Gerais',\n  'Outra fun\u00e7\u00e3o',\n];\n\nconst MODULES = [\n  {\n    id:'transferencias', num:'01', title:'Transfer\u00eancias Seguras', tag:'Corpo a corpo', icon:'\ud83e\udd1d',\n    summary:'Cama, cadeira e banheiro sem dor nem risco \u2014 para voc\u00ea e para quem voc\u00ea cuida.',\n    lessons:[\n      {t:'Cama \u2192 Cadeira', b:'Cadeira ao lado da cama, freios travados. Sente o idoso com os p\u00e9s no ch\u00e3o. Bra\u00e7os dele ao seu redor, se precisar. Gire e sente com cuidado.'},\n      {t:'Cadeira \u2192 Banheiro', b:'Cadeira de banho ao lado, freios travados. Ajude a levantar e sentar. Confirme que est\u00e1 firme e est\u00e1vel antes de soltar.'},\n      {t:'Banheiro \u2192 Cama', b:'Cama ao lado da cadeira de banho, freios travados. Ajude a sentar na cama. Confira conforto e seguran\u00e7a antes de se afastar.'},\n      {t:'Equipamentos', b:'Cadeira de rodas ou de banho sempre em boas condi\u00e7\u00f5es, com freios funcionando. Certifique-se de que o idoso est\u00e1 bem sentado e seguro.'},\n      {t:'Aten\u00e7\u00e3o \u00e0 pele', b:'Atrito e fric\u00e7\u00e3o durante a transfer\u00eancia podem lesionar a pele. Movimentos suaves \u2014 nunca arrastar.'},\n    ],\n    facilitatorTip:'Pe\u00e7a para duas cuidadoras encenarem a transfer\u00eancia cama\u2192cadeira, uma no papel do idoso. Pare em cada passo e pergunte ao grupo: \"o que travamos primeiro?\"',\n    activity:{\n      type:'sequence',\n      title:'Monte a sequ\u00eancia correta: Cama \u2192 Cadeira',\n      items:[\n        'Posicionar a cadeira ao lado da cama e travar os freios',\n        'Ajudar o idoso a sentar-se na cama, com os p\u00e9s no ch\u00e3o',\n        'Idoso coloca os bra\u00e7os ao redor do cuidador, se necess\u00e1rio',\n        'Levantar o idoso e girar para sent\u00e1-lo na cadeira',\n      ]\n    },\n    quiz:[\n      {q:'No meio de uma transfer\u00eancia sozinha, voc\u00ea sente que o idoso est\u00e1 mais pesado do que imaginava e perde um pouco o equil\u00edbrio. A atitude mais segura \u00e9:', options:['Continuar o movimento rapidamente para terminar logo','Apoiar o idoso com seguran\u00e7a no ponto mais pr\u00f3ximo (cama ou cadeira) e pedir ajuda antes de prosseguir','Soltar suavemente para n\u00e3o se machucar'], correct:1, explain:'Interromper com seguran\u00e7a e pedir refor\u00e7o evita queda e les\u00e3o \u2014 tanto do idoso quanto da cuidadora. Terminar r\u00e1pido ou soltar s\u00e3o as duas formas mais comuns de um desequil\u00edbrio virar acidente.'},\n      {q:'Qual dessas transfer\u00eancias N\u00c3O precisa que voc\u00ea trave os freios da cadeira antes de mover o idoso?', options:['Cama para cadeira','Cadeira para cadeira de banho','Nenhuma \u2014 os freios sempre devem estar travados antes de qualquer transfer\u00eancia'], correct:2, explain:'O travamento dos freios \u00e9 uma regra universal, n\u00e3o uma exce\u00e7\u00e3o por tipo de transfer\u00eancia \u2014 vale para todas, sempre.'},\n      {q:'Durante a transfer\u00eancia, o idoso desliza um pouco e voc\u00ea sente que est\u00e1 arrastando a pele dele no len\u00e7ol por um instante breve. A a\u00e7\u00e3o correta \u00e9:', options:['Terminar r\u00e1pido \u2014 o atrito foi curto demais para causar dano','Parar, reposicionar bem e evitar continuar arrastando: mesmo um atrito breve soma risco de les\u00e3o','Aplicar um creme hidratante depois e seguir normalmente'], correct:1, explain:'N\u00e3o existe \"atrito seguro\" s\u00f3 por ser r\u00e1pido \u2014 cisalhamento e atrito se acumulam, mesmo em poucos segundos. Parar e reposicionar \u00e9 sempre a resposta certa.'},\n      {q:'Voc\u00ea vai usar a cadeira de rodas e percebe que os freios travam, mas fazem um barulho estranho e t\u00eam um pouco de folga. O que fazer?', options:['Usar mesmo assim, j\u00e1 que os freios travam','Reportar o problema e evitar usar at\u00e9 a manuten\u00e7\u00e3o confirmar que est\u00e1 segura','Usar s\u00f3 para transfer\u00eancias curtas, dentro do quarto'], correct:1, explain:'Qualquer d\u00favida sobre a condi\u00e7\u00e3o do equipamento deve interromper o uso \u2014 \"travar com folga\" n\u00e3o \u00e9 o mesmo que \"travar com seguran\u00e7a\".'},\n      {q:'Na transfer\u00eancia de cama para cadeira, qual erro \u00e9 mais perigoso?', options:['Girar o idoso para sentar antes de garantir que os p\u00e9s est\u00e3o firmes no ch\u00e3o','Deixar o idoso com os bra\u00e7os ao redor do cuidador','Sentar o idoso primeiro na beira da cama'], correct:0, explain:'Girar sem os p\u00e9s firmes no ch\u00e3o tira a base de apoio no momento exato da virada \u2014 \u00e9 o erro que mais gera queda nessa transfer\u00eancia.'},\n    ]\n  },\n  {\n    id:'sonda', num:'02', title:'Alimenta\u00e7\u00e3o por Sonda', tag:'Postura & vias', icon:'\ud83e\udd63',\n    summary:'O \u00e2ngulo certo evita broncoaspira\u00e7\u00e3o. A via certa evita confus\u00e3o na hora do cuidado.',\n    lessons:[\n      {t:'Posi\u00e7\u00e3o de Fowler', b:'Inclina\u00e7\u00e3o de 30 a 40 graus. Confort\u00e1vel e segura para receber a alimenta\u00e7\u00e3o.'},\n      {t:'Posi\u00e7\u00e3o Semi-Fowler', b:'Inclina\u00e7\u00e3o mais leve, de 15 a 20 graus, quando indicado.'},\n      {t:'Verifique a sonda', b:'Posi\u00e7\u00e3o correta, sem obstru\u00e7\u00e3o, sem deslocamento \u2014 sempre antes de iniciar.'},\n      {t:'Monitore a respira\u00e7\u00e3o', b:'Fique atenta \u00e0 respira\u00e7\u00e3o e \u00e0 satura\u00e7\u00e3o de oxig\u00eanio durante toda a alimenta\u00e7\u00e3o.'},\n      {t:'Higiene \u00e9 preven\u00e7\u00e3o', b:'Limpeza, desinfec\u00e7\u00e3o e uso de EPI evitam infec\u00e7\u00e3o; verifica\u00e7\u00e3o regular evita obstru\u00e7\u00e3o.'},\n    ],\n    facilitatorTip:'Leve um travesseiro (ou cunha) e pe\u00e7a que, em duplas, ajustem fisicamente o \u00e2ngulo de 30\u201340\u00b0 no colega \u2014 s\u00f3 validam quando o outro confirma visualmente.',\n    activity:{type:'slider'},\n    matchPairs:{\n      title:'Ligue a via de alimenta\u00e7\u00e3o \u00e0 sua descri\u00e7\u00e3o',\n      pairs:[\n        {term:'Nasog\u00e1strica / Orog\u00e1strica', def:'Passa pelo nariz ou boca at\u00e9 o est\u00f4mago'},\n        {term:'Nasoent\u00e9rica / Oroent\u00e9rica', def:'Passa pelo nariz ou boca at\u00e9 o intestino delgado'},\n        {term:'Gastrostomia', def:'Implantada cirurgicamente; permanece em estoma direto no est\u00f4mago'},\n        {term:'Jejunostomia', def:'Implantada cirurgicamente; permanece em estoma no intestino delgado (jejuno)'},\n      ]\n    },\n    quiz:[\n      {q:'Durante a alimenta\u00e7\u00e3o por sonda, o idoso come\u00e7a a tossir bastante. A primeira atitude \u00e9:', options:['Continuar a alimenta\u00e7\u00e3o, s\u00f3 mais devagar','Parar imediatamente, avaliar a respira\u00e7\u00e3o e chamar a enfermagem se necess\u00e1rio','Reclinar mais o idoso para facilitar a passagem'], correct:1, explain:'Tosse durante a alimenta\u00e7\u00e3o \u00e9 sinal de alerta para broncoaspira\u00e7\u00e3o \u2014 parar e avaliar vem antes de qualquer ajuste de velocidade ou posi\u00e7\u00e3o.'},\n      {q:'Qual afirma\u00e7\u00e3o melhor descreve a escolha entre Fowler e Semi-Fowler?', options:['Fowler \u00e9 sempre a mais segura, ent\u00e3o deve-se usar sempre que poss\u00edvel','A escolha depende da orienta\u00e7\u00e3o da equipe para aquele idoso \u2014 inclina\u00e7\u00e3o maior nem sempre \u00e9 a indicada','Semi-Fowler s\u00f3 \u00e9 usada durante a noite'], correct:1, explain:'A posi\u00e7\u00e3o indicada depende da condi\u00e7\u00e3o de cada idoso e da orienta\u00e7\u00e3o da equipe \u2014 \"mais inclinado \u00e9 sempre melhor\" \u00e9 uma armadilha comum.'},\n      {q:'Uma sonda que passa pelo nariz e vai at\u00e9 o intestino delgado (n\u00e3o o est\u00f4mago) \u00e9 chamada de:', options:['Nasog\u00e1strica','Nasoent\u00e9rica','Gastrostomia'], correct:1, explain:'\"G\u00e1strica\" = est\u00f4mago; \"ent\u00e9rica\" = intestino. Nasoent\u00e9rica \u00e9 a via que passa pelo nariz at\u00e9 o intestino delgado.'},\n      {q:'A sonda parece estar na posi\u00e7\u00e3o correta, mas voc\u00ea n\u00e3o tem certeza. A atitude certa \u00e9:', options:['Iniciar a alimenta\u00e7\u00e3o mesmo assim, j\u00e1 que parece estar bem','N\u00e3o iniciar at\u00e9 confirmar com a equipe respons\u00e1vel','Puxar um pouco a sonda para reposicionar por conta pr\u00f3pria'], correct:1, explain:'Na d\u00favida, n\u00e3o se arrisca nem se reposiciona por conta pr\u00f3pria \u2014 confirma-se com quem pode validar a posi\u00e7\u00e3o corretamente.'},\n      {q:'Gastrostomia e jejunostomia se parecem porque as duas:', options:['Passam pelo nariz ou pela boca','S\u00e3o implantadas cirurgicamente e permanecem em um estoma','Servem apenas para hidrata\u00e7\u00e3o, n\u00e3o para alimenta\u00e7\u00e3o'], correct:1, explain:'Diferente das vias nasog\u00e1strica/nasoent\u00e9rica, gastrostomia e jejunostomia s\u00e3o cir\u00fargicas e ficam em um orif\u00edcio (estoma) \u2014 a diferen\u00e7a entre elas \u00e9 s\u00f3 o destino final, est\u00f4mago ou intestino.'},\n    ]\n  },\n  {\n    id:'pele', num:'03', title:'Preven\u00e7\u00e3o de Les\u00f5es por Press\u00e3o', tag:'Pele em foco', icon:'\ud83d\udee1\ufe0f',\n    summary:'Os pontos do corpo que mais sofrem press\u00e3o \u2014 e como aliviar antes que virem les\u00e3o.',\n    lessons:[\n      {t:'Mude a posi\u00e7\u00e3o', b:'Reposicionar regularmente evita press\u00e3o prolongada no mesmo ponto.'},\n      {t:'Almofadas e colch\u00f5es', b:'Use para reduzir a press\u00e3o nas \u00e1reas de risco e verifique se est\u00e3o em boas condi\u00e7\u00f5es.'},\n      {t:'Verifique a pele', b:'Regularmente, \u00e0 procura de vermelhid\u00e3o ou les\u00e3o. Documente qualquer altera\u00e7\u00e3o.'},\n      {t:'Pele limpa e seca', b:'Use produtos de cuidado adequados \u2014 umidade em excesso tamb\u00e9m machuca.'},\n    ],\n    facilitatorTip:'Projete o mapa de risco e pe\u00e7a que cada cuidadora aponte, no colega sentado ao lado, os pontos de press\u00e3o antes de revelar a resposta certa.',\n    activity:{type:'hotspots'},\n    quiz:[\n      {q:'Dois casos: (1) uma vermelhid\u00e3o que SOME poucos minutos depois de aliviar a press\u00e3o; (2) uma vermelhid\u00e3o que CONTINUA mesmo horas depois do al\u00edvio. Qual afirma\u00e7\u00e3o est\u00e1 correta?', options:['Os dois casos s\u00e3o iguais e n\u00e3o precisam de aten\u00e7\u00e3o especial','O caso 1 \u00e9 uma resposta esperada mas ainda exige observa\u00e7\u00e3o; o caso 2 \u00e9 sinal de alerta que deve ser documentado e comunicado','S\u00f3 o caso 1 deve ser levado a s\u00e9rio \u2014 o caso 2 \u00e9 normal em pele de idoso'], correct:1, explain:'Vermelhid\u00e3o que desaparece com o al\u00edvio costuma ser uma rea\u00e7\u00e3o normal a observar; vermelhid\u00e3o que persiste \u00e9 sinal de alerta que precisa ser documentado e comunicado \u00e0 equipe antes de virar les\u00e3o.'},\n      {q:'Qual dessas \u00e1reas N\u00c3O \u00e9 considerada um ponto cl\u00e1ssico de risco para les\u00e3o por press\u00e3o?', options:['Calcanhares','Panturrilha (meio da perna)','Sacro'], correct:1, explain:'Os pontos de maior risco ficam sobre proemin\u00eancias \u00f3sseas (calcanhar, sacro, cotovelo, omoplata). A panturrilha \u00e9 tecido mole, sem osso logo abaixo da pele, e n\u00e3o \u00e9 um ponto cl\u00e1ssico.'},\n      {q:'A frequ\u00eancia ideal de reposicionamento do idoso deve ser decidida principalmente por:', options:['Um hor\u00e1rio fixo, igual para todos, sem exce\u00e7\u00f5es','A orienta\u00e7\u00e3o da equipe de enfermagem/fisioterapia e as condi\u00e7\u00f5es daquele idoso','A vontade do idoso no momento'], correct:1, explain:'N\u00e3o existe um n\u00famero universal que sirva para todos \u2014 a frequ\u00eancia certa depende da avalia\u00e7\u00e3o de cada caso pela equipe respons\u00e1vel.'},\n      {q:'Colch\u00f5es e almofadas de al\u00edvio de press\u00e3o servem para:', options:['Substituir a necessidade de reposicionar o idoso','Reduzir a press\u00e3o nas \u00e1reas de risco, complementando \u2014 n\u00e3o substituindo \u2014 o reposicionamento','Servir apenas de conforto, sem efeito real na preven\u00e7\u00e3o'], correct:1, explain:'Almofadas e colch\u00f5es reduzem a press\u00e3o, mas n\u00e3o eliminam a necessidade de mudar de posi\u00e7\u00e3o regularmente \u2014 s\u00e3o complemento, n\u00e3o substituto.'},\n      {q:'Ao documentar uma altera\u00e7\u00e3o na pele para a pr\u00f3xima equipe, a informa\u00e7\u00e3o mais importante \u00e9:', options:['Registrar de forma geral que \"a pele est\u00e1 bem\"', 'Descrever localiza\u00e7\u00e3o, aspecto, e se melhora ou n\u00e3o com o al\u00edvio da press\u00e3o', 'S\u00f3 anotar se for algo muito grave'], correct:1, explain:'Um registro gen\u00e9rico n\u00e3o ajuda ningu\u00e9m a agir. Localiza\u00e7\u00e3o, aspecto e resposta ao al\u00edvio de press\u00e3o s\u00e3o o que permite \u00e0 pr\u00f3xima equipe decidir o que fazer.'},\n    ]\n  },\n  {\n    id:'quedas', num:'04', title:'Preven\u00e7\u00e3o de Quedas', tag:'Ambiente seguro', icon:'\ud83d\udeb6',\n    summary:'A maioria das quedas tem uma causa vis\u00edvel no ambiente \u2014 treine o olhar para ach\u00e1-las antes que aconte\u00e7am.',\n    lessons:[\n      {t:'Por que prevenir', b:'Quedas podem causar fraturas e traumatismos cranianos \u2014 e tamb\u00e9m tiram a confian\u00e7a do idoso para se mover.'},\n      {t:'Promova a independ\u00eancia', b:'Seguran\u00e7a e autonomia andam juntas: um ambiente seguro permite mais liberdade, n\u00e3o menos.'},\n      {t:'Acompanhe a marcha', b:'Ofere\u00e7a apoio e assist\u00eancia sempre que necess\u00e1rio, sem pressa.'},\n      {t:'Cal\u00e7ados adequados', b:'Confort\u00e1veis, sem sola escorregadia ou gasta.'},\n    ],\n    facilitatorTip:'Monte um \"quarto armadilha\" real na sala com 2\u20133 riscos (chinelo solto, fio, tapete) e pe\u00e7a para acharem antes de abrir a vers\u00e3o digital.',\n    activity:{type:'room'},\n    quiz:[\n      {q:'Um t\u00eanis levemente apertado, mas com solado emborrachado firme, contra uma sand\u00e1lia larga e confort\u00e1vel, mas de solado liso e macio. Qual \u00e9 mais seguro contra quedas?', options:['A sand\u00e1lia, porque \u00e9 mais confort\u00e1vel','O t\u00eanis, porque o solado antiderrapante pesa mais que o conforto isolado','Os dois s\u00e3o igualmente seguros \u2014 o que importa \u00e9 s\u00f3 o conforto'], correct:1, explain:'Conforto sozinho n\u00e3o previne escorreg\u00f5es. Entre dois cal\u00e7ados, o que tem solado firme e antiderrapante protege mais, mesmo que aperte um pouco.'},\n      {q:'Durante a marcha, o idoso pede para soltar o seu bra\u00e7o e andar \"sozinho, s\u00f3 um pouquinho\" para se sentir mais independente. A melhor resposta \u00e9:', options:['Soltar completamente, para respeitar o pedido','Explicar que pode ficar por perto, pronta para apoiar, sem abandonar a supervis\u00e3o','Negar o pedido e segurar ainda mais firme que antes'], correct:1, explain:'Autonomia e seguran\u00e7a n\u00e3o se excluem: ficar por perto, pronta para agir, respeita o pedido sem abrir m\u00e3o da prote\u00e7\u00e3o.'},\n      {q:'Qual situa\u00e7\u00e3o representa MAIOR risco de queda, mesmo parecendo menos perigosa \u00e0 primeira vista?', options:['Um tapete grande e visivelmente enrugado no meio do quarto','Um piso rec\u00e9m-encerado, seco e brilhando, sem nenhum aviso','As duas representam o mesmo risco, pois s\u00e3o igualmente vis\u00edveis'], correct:1, explain:'O piso encerado engana justamente por parecer limpo e normal \u2014 o risco que n\u00e3o salta aos olhos costuma ser mais perigoso que o \u00f3bvio.'},\n      {q:'Promover preven\u00e7\u00e3o de quedas SEM tirar a autonomia do idoso significa, na pr\u00e1tica:', options:['Impedir que ele caminhe sozinho em qualquer situa\u00e7\u00e3o','Adaptar o ambiente e oferecer apoio quando necess\u00e1rio, sem limitar toda a movimenta\u00e7\u00e3o','Deixar por conta dele decidir sozinho todos os riscos que vai correr'], correct:1, explain:'O equil\u00edbrio certo \u00e9 adaptar o ambiente e apoiar quando preciso \u2014 nem superprote\u00e7\u00e3o, nem deixar todo o risco por conta do idoso.'},\n      {q:'Depois de identificar um risco de queda (por exemplo, um fio solto no caminho), qual \u00e9 a sequ\u00eancia mais correta?', options:['Sinalizar o risco e seguir o plant\u00e3o, resolvendo na pr\u00f3xima oportunidade','Remover ou corrigir o risco imediatamente, e s\u00f3 depois seguir com as outras tarefas','Anotar no caderno de ocorr\u00eancias e deixar para o pr\u00f3ximo turno resolver'], correct:1, explain:'Sinalizar ou anotar para depois ainda deixa o risco ativo. Diante de um risco que d\u00e1 para resolver na hora, a a\u00e7\u00e3o imediata vem antes de qualquer registro.'},\n    ]\n  },\n  {\n    id:'comunicacao', num:'05', title:'Comunica\u00e7\u00e3o Eficaz', tag:'V\u00ednculo & escuta', icon:'\ud83d\udcac',\n    summary:'A t\u00e9cnica certa nas m\u00e3os n\u00e3o substitui a palavra certa na hora certa.',\n    lessons:[\n      {t:'Por que importa', b:'Comunica\u00e7\u00e3o clara previne mal-entendidos, reduz ansiedade e constr\u00f3i confian\u00e7a.'},\n      {t:'Fale devagar e claro', b:'Sem pressa, sem jarg\u00e3o t\u00e9cnico.'},\n      {t:'Linguagem simples', b:'Palavras acess\u00edveis, sem termos complexos.'},\n      {t:'Ou\u00e7a de verdade', b:'Preste aten\u00e7\u00e3o total ao que o idoso est\u00e1 dizendo \u2014 e ao que n\u00e3o est\u00e1 dizendo.'},\n      {t:'Paci\u00eancia e empatia', b:'Respeito no tom, no tempo e na postura.'},\n      {t:'Use recursos visuais', b:'Gestos e imagens ajudam quando as palavras n\u00e3o bastam.'},\n    ],\n    facilitatorTip:'\"O Recado do Plant\u00e3o\": em c\u00edrculo, sussurre uma vez (sem repetir) um recado realista de passagem de plant\u00e3o \u2014 ex: \"Dona Regina recusou o almo\u00e7o, tomou o rem\u00e9dio da press\u00e3o \u00e0s 13h e reclamou de dor no joelho esquerdo depois do banho.\" A \u00faltima pessoa diz em voz alta o que ouviu. Compare com o recado original e pergunte: \"se a pr\u00f3xima cuidadora agisse pela vers\u00e3o distorcida, o que poderia dar errado com Dona Regina?\" Feche ligando a resposta \u00e0s t\u00e9cnicas do m\u00f3dulo (repetir de volta, escrever, confirmar) como o ant\u00eddoto para isso n\u00e3o acontecer de verdade.',\n    activity:{type:'dialogue'},\n    sort:{\n      title:'Arraste (toque) cada atitude para Fazer ou Evitar',\n      items:[\n        {text:'Falar devagar e com clareza', good:true},\n        {text:'Usar jarg\u00f5es t\u00e9cnicos complicados', good:false},\n        {text:'Ouvir atentamente antes de responder', good:true},\n        {text:'Interromper o idoso no meio da fala', good:false},\n        {text:'Usar gestos e imagens de apoio', good:true},\n        {text:'Falar r\u00e1pido, como se estivesse com pressa', good:false},\n        {text:'Manter paci\u00eancia e tom respeitoso', good:true},\n        {text:'Ignorar o que o idoso est\u00e1 tentando dizer', good:false},\n      ]\n    }\n  },\n];\n\nconst DIALOGUE_SCENES = [\n  {situation:'Dona Elza est\u00e1 agitada e diz que precisa \"ir para casa ver os filhos\".', options:[\n    {t:'\"A senhora n\u00e3o tem casa nenhuma pra ir, fica calma.\"', correct:false, fb:'Invalida o sentimento dela e pode aumentar a agita\u00e7\u00e3o.'},\n    {t:'\"Me conta sobre seus filhos? Como eles s\u00e3o?\"', correct:true, fb:'Acolhe a emo\u00e7\u00e3o, valida sem confrontar e abre espa\u00e7o para ela se acalmar falando do que ama.'},\n    {t:'Ignorar e trocar de assunto rapidamente.', correct:false, fb:'Ela pode se sentir n\u00e3o ouvida e insistir ainda mais.'},\n  ]},\n  {situation:'Seu Ant\u00f4nio se recusa a tomar banho e cruza os bra\u00e7os.', options:[\n    {t:'\"O senhor vai tomar banho agora, n\u00e3o tem escolha.\"', correct:false, fb:'Postura de imposi\u00e7\u00e3o tende a gerar mais resist\u00eancia.'},\n    {t:'Insistir repetindo a mesma frase, mais alto.', correct:false, fb:'Falar mais alto n\u00e3o muda a compreens\u00e3o nem reduz a resist\u00eancia.'},\n    {t:'\"Prefere tomar banho agora ou depois do caf\u00e9?\"', correct:true, fb:'Oferecer uma escolha devolve a sensa\u00e7\u00e3o de controle e reduz a resist\u00eancia.'},\n  ]},\n  {situation:'Dona Marta tem dificuldade auditiva e parece n\u00e3o entender sua orienta\u00e7\u00e3o.', options:[\n    {t:'Aproximar-se, olhar no rosto dela e falar mais devagar, com gestos.', correct:true, fb:'Contato visual, ritmo mais lento e apoio visual s\u00e3o as t\u00e9cnicas certas para dificuldade auditiva.'},\n    {t:'Gritar a mesma frase da porta do quarto.', correct:false, fb:'Gritar de longe distorce o som e pode assustar, sem melhorar a compreens\u00e3o.'},\n    {t:'Desistir de explicar e apenas fazer a tarefa por ela.', correct:false, fb:'Tira a autonomia dela e n\u00e3o constr\u00f3i comunica\u00e7\u00e3o.'},\n  ]},\n  {situation:'Seu Jos\u00e9 est\u00e1 confuso e repete a mesma pergunta v\u00e1rias vezes seguidas.', options:[\n    {t:'\"Eu j\u00e1 respondi isso, presta aten\u00e7\u00e3o!\"', correct:false, fb:'Repreender aumenta a ansiedade e n\u00e3o ajuda a mem\u00f3ria dele no momento.'},\n    {t:'Responder com calma, do mesmo jeito, quantas vezes for preciso.', correct:true, fb:'Paci\u00eancia e consist\u00eancia s\u00e3o essenciais diante de confus\u00e3o ou perda de mem\u00f3ria \u2014 sem cobrar que ele \"devia lembrar\".'},\n    {t:'Fingir que n\u00e3o ouviu para n\u00e3o ter que responder de novo.', correct:false, fb:'Ignorar pode aumentar a agita\u00e7\u00e3o e a sensa\u00e7\u00e3o de abandono.'},\n  ]},\n  {situation:'Dona C\u00e9lia est\u00e1 com dor, mas s\u00f3 resmunga baixinho e vira o rosto quando voc\u00ea pergunta o que sente.', options:[\n    {t:'Anotar \"sem queixas\" e seguir para o pr\u00f3ximo idoso.', correct:false, fb:'Um resmungo e o rosto virado j\u00e1 s\u00e3o sinais \u2014 presumir que n\u00e3o h\u00e1 queixa pode deixar uma dor real sem cuidado.'},\n    {t:'Sentar ao lado, no n\u00edvel dos olhos dela, e perguntar de novo com calma, observando o corpo.', correct:true, fb:'Postura aberta, tempo e observa\u00e7\u00e3o do corpo ajudam quem tem dificuldade de verbalizar o que sente.'},\n    {t:'Perguntar rapidamente em p\u00e9, j\u00e1 de sa\u00edda para outra tarefa.', correct:false, fb:'Pressa comunica que voc\u00ea n\u00e3o tem tempo para ouvir \u2014 ela pode desistir de tentar dizer o que sente.'},\n  ]},\n];\n\nconst HOTSPOTS = [\n  {id:'nuca', label:'Nuca / occipital', x:14, y:50, correct:true},\n  {id:'omoU', label:'Omoplata', x:34, y:22.5, correct:true},\n  {id:'omoD', label:'Omoplata', x:34, y:77.5, correct:true},\n  {id:'sacro', label:'Sacro / quadril', x:67.5, y:50, correct:true},\n  {id:'cotU', label:'Cotovelo', x:46, y:19.5, correct:true},\n  {id:'cotD', label:'Cotovelo', x:46, y:80.5, correct:true},\n  {id:'calcU', label:'Calcanhar', x:89.5, y:39.5, correct:true},\n  {id:'calcD', label:'Calcanhar', x:89.5, y:75.5, correct:true},\n  {id:'barriga', label:'Abd\u00f4men', x:45, y:50, correct:false},\n  {id:'coxa', label:'Coxa', x:79, y:39.5, correct:false},\n];\n\nconst ROOM_ITEMS = [\n  {id:'tapete', label:'Tapete solto, sem antiderrapante', x:15, y:82, correct:true},\n  {id:'fio', label:'Fio de aparelho atravessado no ch\u00e3o', x:52, y:95, correct:true},\n  {id:'agua', label:'Piso molhado, sem sinaliza\u00e7\u00e3o', x:52.5, y:90, correct:true},\n  {id:'chinelo', label:'Chinelo tipo dedo, ca\u00eddo de lado', x:82.5, y:86, correct:true},\n  {id:'luz', label:'Ilumina\u00e7\u00e3o fraca / l\u00e2mpada fraquinha', x:82.5, y:13.5, correct:true},\n  {id:'caixa', label:'Caixa no meio do caminho', x:67.5, y:60, correct:true},\n  {id:'roupa', label:'Roupa esquecida jogada no ch\u00e3o', x:10, y:60, correct:true},\n  {id:'degrau', label:'Degrau sem faixa de contraste', x:90, y:92, correct:true},\n  {id:'corrimao', label:'Corrim\u00e3o firme e bem fixado na parede', x:13.5, y:44, correct:false},\n  {id:'antiderrap', label:'Tapete antiderrapante bem colocado', x:67.5, y:90, correct:false},\n];\n\n/* ======================= ESTADO ======================= */\nconst state = {\n  screen:'home',\n  moduleIdx:0,\n  caregiverName:'',\n  caregiverRole:'',\n  completed:new Set(),\n  scoreLog:{},          // moduleId -> { activityKey: {correct,total} }\n  seqOrder:{},          // moduleId -> array chosen\n  matchState:{},         // moduleId -> {matched:[], selTerm, selDef}\n  hotspotSel:{},         // moduleId -> Set of selected ids, revealed:false\n  roomSel:{},\n  dialogueStep:{},        // moduleId -> {step, score}\n  sortState:{},          // moduleId -> {placed:{idx:'good'|'bad'}}\n  angle:{ current:50, target:null, rounds:[], roundAnswered:false, lastOk:null },\n  quizLog:{},            // moduleId -> {qKey: bool}\n  quizOrder:{},          // moduleId -> {qKey: [shuffled original indices]}\n};\n\n/* ======================= HELPERS ======================= */\nfunction crachaHTML(size){\n  return MODULES.map(m=>{\n    const done = state.completed.has(m.id);\n    return `<div class=\"stamp ${done?'done':''}\" title=\"${m.title}\">${done?'\u2713':m.num}</div>`;\n  }).join('');\n}\nfunction renderCrachaMini(){\n  document.getElementById('crachaMini').innerHTML = crachaHTML();\n  const sub = document.getElementById('brandSub');\n  const role = effectiveRole();\n  if(sub) sub.textContent = state.caregiverName ? `Ol\u00e1, ${state.caregiverName.split(' ')[0]}${role? ' \u00b7 '+role : ''}` : 'Treinamento do Cuidador';\n}\nfunction scoreLabel(id){\n  const s = moduleTotals(id);\n  if(!s || s.total===0) return '';\n  return `${s.correct}/${s.total} acertos`;\n}\nfunction setActivityScore(moduleId, activityKey, correct, total){\n  if(!state.scoreLog[moduleId]) state.scoreLog[moduleId] = {};\n  state.scoreLog[moduleId][activityKey] = {correct, total};\n}\nfunction moduleTotals(moduleId){\n  const log = state.scoreLog[moduleId] || {};\n  let correct=0, total=0;\n  Object.values(log).forEach(v=>{ correct+=v.correct; total+=v.total; });\n  return {correct, total};\n}\nfunction modulePassed(moduleId){\n  return moduleTotals(moduleId).correct >= 6;\n}\n\nfunction goHome(){ state.screen='home'; render(); window.scrollTo({top:0,behavior:'smooth'}); }\nfunction onNameInput(v){\n  state.caregiverName = v;\n  const gate = document.getElementById('nameGate');\n  if(gate && v.trim()!=='' && effectiveRole()) gate.classList.remove('error');\n}\nfunction onRoleSelect(v){\n  state.caregiverRole = v;\n  if(v!=='Outra fun\u00e7\u00e3o') state.caregiverRoleOther = '';\n  const gate = document.getElementById('nameGate');\n  if(gate && state.caregiverName.trim()!=='' && effectiveRole()) gate.classList.remove('error');\n  rerenderHomeNameGate();\n}\nfunction onRoleOtherInput(v){\n  state.caregiverRoleOther = v;\n  const gate = document.getElementById('nameGate');\n  if(gate && state.caregiverName.trim()!=='' && effectiveRole()) gate.classList.remove('error');\n}\nfunction effectiveRole(){\n  if(state.caregiverRole==='Outra fun\u00e7\u00e3o') return (state.caregiverRoleOther||'').trim();\n  return (state.caregiverRole||'').trim();\n}\nfunction rerenderHomeNameGate(){\n  if(state.screen!=='home') return;\n  const focusWasOnOther = document.activeElement && document.activeElement.id==='roleOtherInput';\n  document.getElementById('app').innerHTML = renderHome();\n  renderCrachaMini();\n  if(focusWasOnOther){ const el=document.getElementById('roleOtherInput'); if(el) el.focus(); }\n}\nfunction startOrContinue(idx){\n  const nameOk = state.caregiverName && state.caregiverName.trim()!=='';\n  const roleOk = !!effectiveRole();\n  if(!nameOk || !roleOk){\n    const gate = document.getElementById('nameGate');\n    if(gate){\n      gate.classList.add('error');\n      if(!nameOk) document.getElementById('nameInput').focus();\n      else if(document.getElementById('roleOtherInput')) document.getElementById('roleOtherInput').focus();\n    }\n    return;\n  }\n  openModule(idx);\n}\nfunction openModule(idx){ state.screen='module'; state.moduleIdx=idx; render(); window.scrollTo({top:0,behavior:'smooth'}); }\nfunction markComplete(){\n  const m = MODULES[state.moduleIdx];\n  state.completed.add(m.id);\n  const isLast = state.moduleIdx === MODULES.length-1;\n  if(state.completed.size === MODULES.length){ state.screen='complete'; }\n  else if(isLast){ state.screen='home'; }\n  else { state.moduleIdx += 1; }\n  render(); window.scrollTo({top:0,behavior:'smooth'});\n}\nfunction togglePresentation(){\n  document.body.classList.toggle('presentation');\n  document.getElementById('presToggle').classList.toggle('on');\n}\n\n/* ======================= RENDER: HOME ======================= */\nfunction renderHome(){\n  const doneCount = state.completed.size;\n  return `\n  <section class=\"hero\">\n    <div class=\"hero-row\">\n      <div>\n        <div class=\"eyebrow\"><span class=\"dot\"></span>Treinamento interativo \u00b7 Diu Vitae</div>\n        <h1>Transfer\u00eancias, posicionamento e cuidado humanizado para idosos</h1>\n        <p class=\"lede\">Cinco m\u00f3dulos curtos, feitos para voc\u00ea fazer junto com a fisioterapeuta na palestra \u2014 ou sozinha, no seu tempo, aqui pelo celular. Sem decoreba: s\u00e3o cenas, escolhas e simula\u00e7\u00f5es do dia a dia do plant\u00e3o.</p>\n        <div class=\"name-gate\" id=\"nameGate\">\n          <label for=\"nameInput\">Seu nome completo (vai aparecer no certificado)</label>\n          <input id=\"nameInput\" type=\"text\" placeholder=\"Ex: Maria da Silva Santos\" value=\"${state.caregiverName}\" oninput=\"onNameInput(this.value)\">\n          <label for=\"roleSelect\" style=\"margin-top:12px;\">Sua fun\u00e7\u00e3o</label>\n          <select id=\"roleSelect\" onchange=\"onRoleSelect(this.value)\">\n            <option value=\"\" ${!state.caregiverRole?'selected':''} disabled>Selecione...</option>\n            ${ROLE_OPTIONS.map(r=>`<option value=\"${r}\" ${state.caregiverRole===r?'selected':''}>${r}</option>`).join('')}\n          </select>\n          ${state.caregiverRole==='Outra fun\u00e7\u00e3o' ? `<input id=\"roleOtherInput\" type=\"text\" placeholder=\"Digite sua fun\u00e7\u00e3o\" style=\"margin-top:8px;\" value=\"${state.caregiverRoleOther||''}\" oninput=\"onRoleOtherInput(this.value)\">` : ''}\n          <div class=\"err\">Preencha nome e fun\u00e7\u00e3o para come\u00e7ar o treinamento.</div>\n        </div>\n        <div class=\"hero-foot\">\n          <button class=\"cta\" onclick=\"startOrContinue(${firstIncompleteIdx()})\">${doneCount===0?'Come\u00e7ar treinamento':'Continuar de onde parei'} \u2192</button>\n          <div class=\"cracha-card\">\n            <div class=\"cracha\">${crachaHTML()}</div>\n            <div>\n              <div class=\"count\">${doneCount}/5</div>\n              <div class=\"label\">m\u00f3dulos conclu\u00eddos</div>\n            </div>\n          </div>\n        </div>\n      </div>\n      <div class=\"hero-illus\">\n        <svg viewBox=\"0 0 400 260\" xmlns=\"http://www.w3.org/2000/svg\">\n          <ellipse cx=\"200\" cy=\"240\" rx=\"185\" ry=\"12\" fill=\"#2A2A20\" opacity=\"0.06\"/>\n          <line x1=\"340\" y1=\"195\" x2=\"365\" y2=\"212\" stroke=\"#28331C\" stroke-width=\"4\"/>\n          <circle cx=\"358\" cy=\"212\" r=\"28\" fill=\"none\" stroke=\"#28331C\" stroke-width=\"7\"/>\n          <circle cx=\"358\" cy=\"212\" r=\"5\" fill=\"#28331C\"/>\n          <circle cx=\"322\" cy=\"228\" r=\"8\" fill=\"#28331C\"/>\n          <rect x=\"278\" y=\"224\" width=\"46\" height=\"7\" rx=\"3.5\" fill=\"#4A5A38\"/>\n          <rect x=\"270\" y=\"176\" width=\"70\" height=\"14\" rx=\"6\" fill=\"#33421F\"/>\n          <rect x=\"326\" y=\"122\" width=\"11\" height=\"58\" rx=\"5\" fill=\"#33421F\"/>\n          <use href=\"#figElderlySit\" transform=\"translate(249,52)\"/>\n          <use href=\"#figCaregiver\" transform=\"translate(80,45)\"/>\n          ${leafCluster(0,0,50)}\n          ${leafCluster(400,260,230)}\n        </svg>\n      </div>\n    </div>\n  </section>\n\n  <div class=\"section-label\">M\u00f3dulos</div>\n  <div class=\"grid-modules\">\n    ${MODULES.map((m,i)=>`\n      <button class=\"m-card\" onclick=\"startOrContinue(${i})\">\n        ${state.completed.has(m.id)?'<div class=\"check\">\u2713</div>':''}\n        <div class=\"num\">M\u00d3DULO ${m.num}</div>\n        <div class=\"icon\">${m.icon}</div>\n        <span class=\"tag\">${m.tag}</span>\n        <h3>${m.title}</h3>\n        <p>${m.summary}</p>\n      </button>\n    `).join('')}\n  </div>\n\n  <div class=\"facilitator-box\">\n    <h3>Para quem est\u00e1 conduzindo a palestra</h3>\n    <p>Cada m\u00f3dulo tem uma caixa \"\ud83d\udca1 Dica para quem est\u00e1 conduzindo ao vivo\" com uma din\u00e2mica r\u00e1pida para fazer com a turma antes de abrir a atividade digital. Projete a tela, deixe as cuidadoras responderem em voz alta, e s\u00f3 depois liberem o celular para elas repetirem sozinhas em casa.</p>\n  </div>\n  `;\n}\nfunction firstIncompleteIdx(){\n  const i = MODULES.findIndex(m=>!state.completed.has(m.id));\n  return i===-1?0:i;\n}\n\n/* ======================= ILUSTRA\u00c7\u00d5ES ======================= */\nfunction leafCluster(x,y,angle){\n  const blade = (a)=>`<path d=\"M0,0 Q-7,-19 0,-36 Q7,-19 0,0 Z\" fill=\"#4C5F3A\" opacity=\"0.4\" transform=\"rotate(${a})\"/>`;\n  return `<g transform=\"translate(${x},${y})\">${blade(angle-16)}${blade(angle)}${blade(angle+16)}</g>`;\n}\n\nfunction moduleIllustration(m){\n  const svgs = {\n    transferencias: `\n      <svg viewBox=\"0 0 400 260\" xmlns=\"http://www.w3.org/2000/svg\">\n        <ellipse cx=\"200\" cy=\"240\" rx=\"190\" ry=\"10\" fill=\"#2A2A20\" opacity=\"0.06\"/>\n        <rect x=\"14\" y=\"120\" width=\"14\" height=\"112\" rx=\"6\" fill=\"#33421F\"/>\n        <rect x=\"28\" y=\"178\" width=\"120\" height=\"26\" rx=\"8\" fill=\"url(#matGrad)\" stroke=\"#D6CFB8\"/>\n        <path d=\"M34 182 Q88 174 142 182 L142 190 Q88 184 34 190 Z\" fill=\"#8FA07A\"/>\n        <line x1=\"340\" y1=\"195\" x2=\"365\" y2=\"212\" stroke=\"#28331C\" stroke-width=\"4\"/>\n        <circle cx=\"358\" cy=\"212\" r=\"28\" fill=\"none\" stroke=\"#28331C\" stroke-width=\"7\"/>\n        <circle cx=\"358\" cy=\"212\" r=\"5\" fill=\"#28331C\"/>\n        <circle cx=\"322\" cy=\"228\" r=\"8\" fill=\"#28331C\"/>\n        <rect x=\"278\" y=\"224\" width=\"46\" height=\"7\" rx=\"3.5\" fill=\"#4A5A38\"/>\n        <rect x=\"270\" y=\"176\" width=\"70\" height=\"14\" rx=\"6\" fill=\"#33421F\"/>\n        <rect x=\"326\" y=\"122\" width=\"11\" height=\"58\" rx=\"5\" fill=\"#33421F\"/>\n        <use href=\"#figElderlySit\" transform=\"translate(249,52)\"/>\n        <use href=\"#figCaregiver\" transform=\"translate(130,45)\"/>\n      </svg>`,\n    sonda: moduleSondaSVG(),\n    pele: `\n      <svg viewBox=\"0 0 400 260\" xmlns=\"http://www.w3.org/2000/svg\">\n        <ellipse cx=\"200\" cy=\"240\" rx=\"190\" ry=\"10\" fill=\"#2A2A20\" opacity=\"0.06\"/>\n        <rect x=\"289\" y=\"100\" width=\"12\" height=\"70\" rx=\"6\" fill=\"#33421F\"/>\n        <rect x=\"256\" y=\"184\" width=\"8\" height=\"48\" rx=\"3\" fill=\"#33421F\"/>\n        <rect x=\"322\" y=\"184\" width=\"8\" height=\"48\" rx=\"3\" fill=\"#33421F\"/>\n        <rect x=\"250\" y=\"170\" width=\"90\" height=\"14\" rx=\"6\" fill=\"url(#matGrad)\" stroke=\"#D6CFB8\"/>\n        <use href=\"#figElderlySit\" transform=\"translate(239,46)\"/>\n        <use href=\"#figCaregiver\" transform=\"translate(90,45)\"/>\n        <circle cx=\"312\" cy=\"120\" r=\"6\" fill=\"#D7C93B\" opacity=\"0.85\"/>\n        <circle cx=\"330\" cy=\"108\" r=\"3.5\" fill=\"#D7C93B\" opacity=\"0.7\"/>\n        <path d=\"M300 112 q10 -14 26 -10\" stroke=\"#C97B5F\" stroke-width=\"3\" fill=\"none\" stroke-linecap=\"round\" opacity=\"0.65\"/>\n      </svg>`,\n    quedas: `\n      <svg viewBox=\"0 0 400 260\" xmlns=\"http://www.w3.org/2000/svg\">\n        <rect x=\"0\" y=\"196\" width=\"400\" height=\"36\" fill=\"url(#floorGrad)\"/>\n        <ellipse cx=\"140\" cy=\"216\" rx=\"66\" ry=\"12\" fill=\"#C97B5F\" opacity=\"0.5\"/>\n        <rect x=\"20\" y=\"20\" width=\"90\" height=\"70\" rx=\"6\" fill=\"#EFE9D6\" stroke=\"#D6CFB8\" stroke-width=\"3\"/>\n        <line x1=\"65\" y1=\"20\" x2=\"65\" y2=\"90\" stroke=\"#D6CFB8\" stroke-width=\"3\"/>\n        <line x1=\"20\" y1=\"55\" x2=\"110\" y2=\"55\" stroke=\"#D6CFB8\" stroke-width=\"3\"/>\n        <rect x=\"260\" y=\"150\" width=\"120\" height=\"82\" rx=\"8\" fill=\"#EFE9D6\" stroke=\"#D6CFB8\" stroke-width=\"2\"/>\n        <rect x=\"260\" y=\"150\" width=\"120\" height=\"14\" rx=\"6\" fill=\"#DCD5B8\"/>\n        <use href=\"#figElderlyStand\" transform=\"translate(90,45)\"/>\n        <circle cx=\"350\" cy=\"40\" r=\"12\" fill=\"#D7C93B\" opacity=\"0.3\"/>\n        <path d=\"M350 26 L350 16 M336 40 L326 40 M364 40 L374 40\" stroke=\"#D7C93B\" stroke-width=\"3\" opacity=\"0.5\"/>\n      </svg>`,\n    comunicacao: `\n      <svg viewBox=\"0 0 400 260\" xmlns=\"http://www.w3.org/2000/svg\">\n        <ellipse cx=\"200\" cy=\"240\" rx=\"190\" ry=\"10\" fill=\"#2A2A20\" opacity=\"0.06\"/>\n        <rect x=\"289\" y=\"100\" width=\"12\" height=\"70\" rx=\"6\" fill=\"#33421F\"/>\n        <rect x=\"256\" y=\"184\" width=\"8\" height=\"48\" rx=\"3\" fill=\"#33421F\"/>\n        <rect x=\"322\" y=\"184\" width=\"8\" height=\"48\" rx=\"3\" fill=\"#33421F\"/>\n        <rect x=\"250\" y=\"170\" width=\"90\" height=\"14\" rx=\"6\" fill=\"url(#matGrad)\" stroke=\"#D6CFB8\"/>\n        <use href=\"#figCaregiver\" transform=\"translate(50,45)\"/>\n        <use href=\"#figElderlySit\" transform=\"translate(239,46)\"/>\n        <path d=\"M148 42 q30 -26 68 -6 q10 22 -10 32 q0 10 -12 10 q-2 -8 -12 -8 q-26 4 -34 -28Z\" fill=\"#FFFDF8\" stroke=\"#D6CFB8\" stroke-width=\"2\"/>\n        <circle cx=\"176\" cy=\"52\" r=\"4\" fill=\"#C97B5F\"/>\n        <circle cx=\"190\" cy=\"50\" r=\"4\" fill=\"#C97B5F\"/>\n        <circle cx=\"204\" cy=\"52\" r=\"4\" fill=\"#C97B5F\"/>\n      </svg>`,\n  };\n  return `<div class=\"module-illus\">${svgs[m.id]||''}<div class=\"cap\">Ilustra\u00e7\u00e3o de refer\u00eancia \u2014 ${m.title.toLowerCase()}</div></div>`;\n}\n\nfunction moduleSondaSVG(){\n  let svg = bedFigureSVG(32, 'sondaIllus', false);\n  const ivPole = `\n    <rect x=\"374\" y=\"44\" width=\"22\" height=\"24\" rx=\"5\" fill=\"#EFE9D6\" stroke=\"#C9A26B\" stroke-width=\"2\"/>\n    <line x1=\"385\" y1=\"68\" x2=\"385\" y2=\"168\" stroke=\"#C9A26B\" stroke-width=\"3\"/>\n    <line x1=\"372\" y1=\"168\" x2=\"398\" y2=\"168\" stroke=\"#C9A26B\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n  `;\n  return svg.replace('</svg>', ivPole + '</svg>');\n}\n\nfunction bedFigureSVG(angle, id, live){\n  const rot = angle - 90;\n  const zoneOk = (angle>=15 && angle<=40);\n  return `\n  <svg viewBox=\"0 0 400 190\" xmlns=\"http://www.w3.org/2000/svg\" ${live?`id=\"${id}\"`:''}>\n    <rect x=\"20\" y=\"40\" width=\"16\" height=\"120\" rx=\"6\" fill=\"#33421F\"/>\n    <rect x=\"356\" y=\"90\" width=\"14\" height=\"70\" rx=\"5\" fill=\"#33421F\"/>\n    <rect x=\"60\" y=\"150\" width=\"290\" height=\"18\" rx=\"7\" fill=\"url(#matGrad)\" stroke=\"#D6CFB8\"/>\n    <rect x=\"38\" y=\"128\" width=\"44\" height=\"32\" rx=\"15\" fill=\"#F7F3E4\" stroke=\"#DDD4B8\" stroke-width=\"1.5\"/>\n    <path d=\"M46 138 Q60 143 74 138\" stroke=\"#DDD4B8\" stroke-width=\"1.5\" fill=\"none\"/>\n    <!-- blanket over legs, static -->\n    <path d=\"M146 158 L146 144 Q160 130 190 133 Q260 138 336 136 Q347 136 347 147 L347 158 Z\" fill=\"url(#claySoftGrad)\"/>\n    <path d=\"M170 140 Q220 148 300 143\" stroke=\"#B5745A\" stroke-width=\"1.5\" fill=\"none\" opacity=\"0.45\"/>\n    <path d=\"M195 137 Q210 150 205 158\" stroke=\"#B5745A\" stroke-width=\"1.5\" fill=\"none\" opacity=\"0.4\"/>\n    <ellipse cx=\"335\" cy=\"149\" rx=\"11\" ry=\"7\" fill=\"#D6987A\" opacity=\"0.8\"/>\n    <g ${live?`id=\"${id}-torso\"`:''} transform=\"rotate(${rot} 150 150)\">\n      <path d=\"M133 150 Q131 104 150 92 Q169 104 167 150 Z\" fill=\"url(#clayGrad)\"/>\n      <circle cx=\"150\" cy=\"78\" r=\"18\" fill=\"url(#skinGrad)\"/>\n      <path d=\"M132 76 Q130 55 150 55 Q172 56 168 78 Q167 62 150 63 Q134 63 133 76Z\" fill=\"url(#grayHairGrad)\"/>\n      <path d=\"M134 70 Q129 84 135 92\" stroke=\"url(#grayHairGrad)\" stroke-width=\"6\" fill=\"none\" stroke-linecap=\"round\"/>\n      <path d=\"M166 70 Q171 84 165 92\" stroke=\"url(#grayHairGrad)\" stroke-width=\"6\" fill=\"none\" stroke-linecap=\"round\"/>\n      <circle cx=\"144\" cy=\"79\" r=\"1.7\" fill=\"#6B6B5C\"/>\n      <circle cx=\"156\" cy=\"79\" r=\"1.7\" fill=\"#6B6B5C\"/>\n      <path d=\"M145 86 Q150 88.5 155 86\" stroke=\"#9C5C42\" stroke-width=\"1.5\" fill=\"none\" stroke-linecap=\"round\"/>\n    </g>\n    <circle cx=\"150\" cy=\"150\" r=\"16\" fill=\"url(#claySoftGrad)\"/>\n    ${zoneOk ? `<rect x=\"60\" y=\"172\" width=\"290\" height=\"4\" rx=\"2\" fill=\"#3E7A45\" opacity=\"0.6\"/>` : `<rect x=\"60\" y=\"172\" width=\"290\" height=\"4\" rx=\"2\" fill=\"#B5493A\" opacity=\"0.35\"/>`}\n  </svg>`;\n}\n\n/* ======================= RENDER: MODULE ======================= */\nfunction renderModule(idx){\n  const m = MODULES[idx];\n  let html = `\n    <button class=\"back-btn\" onclick=\"goHome()\">\u2190 Todos os m\u00f3dulos</button>\n    <div class=\"m-head\">\n      <div class=\"num-tag\"><span class=\"num\">M\u00d3DULO ${m.num}</span><span class=\"tag\">${m.tag}</span></div>\n      <h2>${m.icon} ${m.title}</h2>\n      <p>${m.summary}</p>\n    </div>\n\n    ${moduleIllustration(m)}\n\n    <div class=\"lesson-grid\">\n      ${m.lessons.map(l=>`<div class=\"l-card\"><div class=\"t\">${l.t}</div><div class=\"b\">${l.b}</div></div>`).join('')}\n    </div>\n\n    ${m.id==='sonda' ? `\n    <div class=\"pos-ref-row\">\n      <div class=\"pos-ref\">\n        ${bedFigureSVG(35, 'posRefA', false)}\n        <div class=\"cap\">Fowler <span>30\u00b0\u201340\u00b0</span></div>\n      </div>\n      <div class=\"pos-ref\">\n        ${bedFigureSVG(17, 'posRefB', false)}\n        <div class=\"cap\">Semi-Fowler <span>15\u00b0\u201320\u00b0</span></div>\n      </div>\n    </div>` : ''}\n\n    <details class=\"tip\">\n      <summary>Dica para quem est\u00e1 conduzindo ao vivo</summary>\n      <p>${m.facilitatorTip}</p>\n    </details>\n  `;\n\n  // Activity block(s) per module type\n  if(m.activity.type === 'sequence') html += renderSequenceActivity(m);\n  if(m.activity.type === 'slider'){\n    html += renderSliderActivity(m);\n    html += renderMatchActivity(m);\n  }\n  if(m.activity.type === 'hotspots') html += renderHotspotActivity(m);\n  if(m.activity.type === 'room') html += renderRoomActivity(m);\n  if(m.activity.type === 'dialogue'){\n    html += renderDialogueActivity(m);\n    html += renderSortActivity(m);\n  }\n\n  if(m.quiz){\n    html += `<div class=\"section-label\">Checagem r\u00e1pida</div>`;\n    html += `<div class=\"panel\"><h4>Quiz \u00b7 ${m.title}</h4>` + m.quiz.map((q,qi)=>renderMCQBlock(m.id, 'quiz'+qi, q)).join('<hr style=\"border:none;border-top:1px solid rgba(59,74,46,0.1);margin:22px 0;\">') + `</div>`;\n  }\n\n  const isLast = idx === MODULES.length-1;\n  html += `\n    <div class=\"concluir-bar\">\n      <div class=\"score-pill\">\ud83d\udccb ${scoreLabel(m.id) || 'Complete as atividades acima'}</div>\n      <button class=\"btn primary\" onclick=\"markComplete()\">${state.completed.has(m.id) ? 'Conclu\u00eddo \u2014 avan\u00e7ar' : (isLast? 'Concluir treinamento' : 'Concluir m\u00f3dulo e avan\u00e7ar')} \u2192</button>\n    </div>\n  `;\n  return html;\n}\n\n/* ---- MCQ generic ---- */\nfunction getQuizOrder(moduleId, key, numOptions){\n  if(!state.quizOrder[moduleId]) state.quizOrder[moduleId] = {};\n  if(!state.quizOrder[moduleId][key]){\n    state.quizOrder[moduleId][key] = shuffle([...Array(numOptions).keys()]);\n  }\n  return state.quizOrder[moduleId][key];\n}\nfunction renderMCQBlock(moduleId, key, q){\n  const order = getQuizOrder(moduleId, key, q.options.length);\n  const answeredEntry = state.quizLog[moduleId] && state.quizLog[moduleId][key];\n  return `\n    <div class=\"mcq\" data-mkey=\"${moduleId}__${key}\">\n      <div class=\"prompt\" style=\"font-size:15.5px;margin-bottom:10px;\">${q.q}</div>\n      ${order.map(originalIdx=>{\n        const isCorrectOpt = originalIdx===q.correct;\n        const isChosen = answeredEntry && answeredEntry.chosen===originalIdx;\n        let cls = '';\n        if(answeredEntry){\n          cls = 'disabled';\n          if(isCorrectOpt) cls += ' correct';\n          if(isChosen && !isCorrectOpt) cls += ' wrong';\n        }\n        return `<button class=\"opt ${cls}\" onclick=\"answerMCQ('${moduleId}','${key}',${originalIdx},${q.correct})\">${q.options[originalIdx]}</button>`;\n      }).join('')}\n      <div class=\"feedback ${answeredEntry?'show '+(answeredEntry.correct?'good':'bad'):''}\">${answeredEntry ? (answeredEntry.correct? '\u2713 Isso mesmo. ' : '\u2717 Quase. ') + q.explain : ''}</div>\n    </div>\n  `;\n}\nfunction answerMCQ(moduleId, key, chosen, correctIdx){\n  if(state.quizLog[moduleId] && state.quizLog[moduleId][key]) return;\n  const isCorrect = chosen===correctIdx;\n  if(!state.quizLog[moduleId]) state.quizLog[moduleId] = {};\n  state.quizLog[moduleId][key] = {chosen, correct:isCorrect};\n  const m = MODULES.find(x=>x.id===moduleId);\n  const correctCount = Object.values(state.quizLog[moduleId]).filter(v=>v.correct).length;\n  setActivityScore(moduleId, 'quiz', correctCount, m.quiz.length);\n  rerenderModule();\n}\nfunction findQuestion(moduleId, key){\n  const m = MODULES.find(x=>x.id===moduleId);\n  if(!m) return null;\n  if(key.startsWith('quiz')) return m.quiz[parseInt(key.replace('quiz',''))];\n  return null;\n}\nfunction refreshScoreBar(moduleId){\n  const bar = document.querySelector('.score-pill');\n  if(bar) bar.textContent = '\ud83d\udccb ' + (scoreLabel(moduleId) || 'Complete as atividades acima');\n}\n\n/* ---- sequence ---- */\nfunction renderSequenceActivity(m){\n  if(!state.seqOrder[m.id]) state.seqOrder[m.id] = { pool: shuffle(m.activity.items.slice()), chosen: [], checked:false };\n  const s = state.seqOrder[m.id];\n  return `\n  <div class=\"panel\">\n    <h4>Atividade \u00b7 Sequ\u00eancia</h4>\n    <div class=\"prompt\">${m.activity.title}</div>\n    <p style=\"font-size:13px;color:var(--ink-soft);margin-top:-8px;\">Toque nas frases na ordem certa.</p>\n    <div class=\"pool\" id=\"seqPool\">\n      ${s.pool.map((item,i)=>`<button class=\"chip ${s.chosen.includes(item)?'disabled':''}\" onclick=\"seqPick('${m.id}', ${i})\">${item}</button>`).join('')}\n    </div>\n    <ol class=\"order-list\" id=\"seqOrderList\" style=\"list-style:none;padding:0;\">\n      ${s.chosen.map((item,i)=>`<li class=\"${s.checked? (item===m.activity.items[i] ? 'correct':'wrong'):''}\"><span class=\"badge-n\">${i+1}</span>${item}</li>`).join('')}\n    </ol>\n    <div class=\"btn-row\">\n      <button class=\"btn\" onclick=\"seqUndo('${m.id}')\">Desfazer \u00faltima</button>\n      <button class=\"btn primary\" onclick=\"seqCheck('${m.id}')\" ${s.chosen.length<m.activity.items.length?'disabled':''}>Conferir sequ\u00eancia</button>\n    </div>\n    <div class=\"feedback ${s.checked?'show '+(seqAllCorrect(m)?'good':'bad'):''}\" id=\"seqFb\">${s.checked? (seqAllCorrect(m)? '\u2713 Sequ\u00eancia correta! \u00c9 assim que se faz uma transfer\u00eancia segura.' : '\u2717 Alguns passos est\u00e3o fora de ordem \u2014 veja o destaque acima e tente de novo.') : ''}</div>\n  </div>`;\n}\nfunction seqAllCorrect(m){\n  const s = state.seqOrder[m.id];\n  return s.chosen.every((it,i)=>it===m.activity.items[i]);\n}\nfunction seqPick(moduleId, poolIdx){\n  const s = state.seqOrder[moduleId];\n  const item = s.pool[poolIdx];\n  if(s.chosen.includes(item)) return;\n  s.chosen.push(item);\n  s.checked = false;\n  rerenderModule();\n}\nfunction seqUndo(moduleId){\n  const s = state.seqOrder[moduleId];\n  s.chosen.pop();\n  s.checked = false;\n  rerenderModule();\n}\nfunction seqCheck(moduleId){\n  const s = state.seqOrder[moduleId];\n  const m = MODULES.find(x=>x.id===moduleId);\n  s.checked = true;\n  const correctCount = s.chosen.filter((it,i)=>it===m.activity.items[i]).length;\n  setActivityScore(moduleId, 'sequence', correctCount, m.activity.items.length);\n  rerenderModule();\n}\n\n/* ---- slider (Fowler / Semi-Fowler) ---- */\nfunction renderSliderActivity(m){\n  if(state.angle.target===null){ state.angle.target = 'fowler'; state.angle.current = 55; state.angle.rounds = []; state.angle.roundAnswered=false; state.angle.lastOk=null; }\n  const s = state.angle;\n  const done = s.rounds.length >= 3;\n  const targetLabel = s.target==='fowler' ? 'Posi\u00e7\u00e3o de Fowler' : 'Posi\u00e7\u00e3o de Semi-Fowler';\n  if(done){\n    const correctCount = s.rounds.filter(Boolean).length;\n    return `\n    <div class=\"panel angle-wrap\">\n      <h4>Atividade \u00b7 Ajuste o \u00e2ngulo</h4>\n      <div class=\"prompt\">Desafio conclu\u00eddo</div>\n      <div class=\"bed-figure-box\">${bedFigureSVG(s.current, 'bedLive', false)}</div>\n      <div class=\"feedback show ${correctCount>=2?'good':'bad'}\">Voc\u00ea acertou ${correctCount} de 3 posi\u00e7\u00f5es. ${correctCount>=2? 'Muito bem \u2014 voc\u00ea lembrou a inclina\u00e7\u00e3o certa na maior parte das rodadas.' : 'Vale revisar as posi\u00e7\u00f5es de Fowler e Semi-Fowler antes de seguir.'}</div>\n    </div>`;\n  }\n  if(s.roundAnswered){\n    return `\n    <div class=\"panel angle-wrap\">\n      <h4>Atividade \u00b7 Ajuste o \u00e2ngulo</h4>\n      <div class=\"prompt\">Desafio ${s.rounds.length+1} de 3: <b>${targetLabel}</b></div>\n      <div class=\"bed-figure-box\">${bedFigureSVG(s.current, 'bedLive', false)}</div>\n      <div class=\"angle-readout\">${s.current}\u00b0</div>\n      <div class=\"feedback show ${s.lastOk?'good':'bad'}\">${s.lastOk ? '\u2713 Perfeito, dentro da faixa segura.' : `\u2717 Fora da faixa para ${targetLabel}. Reveja o material antes da pr\u00f3xima rodada.`}</div>\n      <div class=\"btn-row\">\n        <button class=\"btn primary\" onclick=\"angleNextRound()\">${s.rounds.length===2?'Ver resultado':'Pr\u00f3xima rodada'} \u2192</button>\n      </div>\n    </div>`;\n  }\n  return `\n  <div class=\"panel angle-wrap\">\n    <h4>Atividade \u00b7 Ajuste o \u00e2ngulo</h4>\n    <div class=\"prompt\">Desafio ${s.rounds.length+1} de 3: posicione para <b>${targetLabel}</b></div>\n    <p style=\"font-size:13px;color:var(--ink-soft);margin-top:-8px;\">Use o que foi passado no treinamento \u2014 sem dica de graus na tela.</p>\n    <div class=\"bed-figure-box\">${bedFigureSVG(s.current, 'bedLive', true)}</div>\n    <div class=\"angle-readout\" id=\"angleReadout\">${s.current}\u00b0</div>\n    <input type=\"range\" min=\"0\" max=\"90\" value=\"${s.current}\" oninput=\"angleChange(this.value)\">\n    <div class=\"btn-row\">\n      <button class=\"btn primary\" onclick=\"angleCheck('${m.id}')\">Conferir \u00e2ngulo</button>\n    </div>\n  </div>`;\n}\nfunction angleChange(v){\n  state.angle.current = parseInt(v);\n  document.getElementById('angleReadout').textContent = v + '\u00b0';\n  const torso = document.getElementById('bedLive-torso');\n  if(torso) torso.setAttribute('transform', `rotate(${v-90} 150 150)`);\n}\nfunction angleCheck(moduleId){\n  const v = state.angle.current;\n  const target = state.angle.target;\n  const ok = target==='fowler' ? (v>=30 && v<=40) : (v>=15 && v<=20);\n  state.angle.lastOk = ok;\n  state.angle.roundAnswered = true;\n  setActivityScore(moduleId, 'slider', state.angle.rounds.filter(Boolean).length + (ok?1:0), 3);\n  rerenderModule();\n}\nfunction angleNextRound(){\n  const s = state.angle;\n  s.rounds.push(s.lastOk);\n  s.target = s.target==='fowler' ? 'semi' : 'fowler';\n  s.current = 55;\n  s.roundAnswered = false;\n  s.lastOk = null;\n  rerenderModule();\n}\n\n/* ---- match pairs ---- */\nfunction renderMatchActivity(m){\n  const mp = m.matchPairs;\n  if(!state.matchState[m.id]){\n    state.matchState[m.id] = {\n      terms: shuffle(mp.pairs.map((p,i)=>({...p, idx:i}))),\n      defs: shuffle(mp.pairs.map((p,i)=>({...p, idx:i}))),\n      matched: new Set(), selTerm:null,\n    };\n  }\n  const s = state.matchState[m.id];\n  return `\n  <div class=\"panel\">\n    <h4>Atividade \u00b7 Associa\u00e7\u00e3o</h4>\n    <div class=\"prompt\">${mp.title}</div>\n    <div class=\"match-grid\">\n      <div class=\"match-col\">\n        ${s.terms.map(t=>`<div class=\"m-item ${s.matched.has(t.idx)?'matched':''} ${s.selTerm===t.idx?'selected':''}\" onclick=\"matchPickTerm('${m.id}', ${t.idx})\">${t.term}</div>`).join('')}\n      </div>\n      <div class=\"match-col\">\n        ${s.defs.map(d=>`<div class=\"m-item ${s.matched.has(d.idx)?'matched':''}\" onclick=\"matchPickDef('${m.id}', ${d.idx})\">${d.def}</div>`).join('')}\n      </div>\n    </div>\n    <div class=\"feedback ${s.matched.size===mp.pairs.length?'show good':''}\">${s.matched.size===mp.pairs.length? '\u2713 Todas as vias associadas corretamente!' : ''}</div>\n  </div>`;\n}\nfunction matchPickTerm(moduleId, idx){\n  const s = state.matchState[moduleId];\n  if(s.matched.has(idx)) return;\n  s.selTerm = idx;\n  rerenderModule();\n}\nfunction matchPickDef(moduleId, idx){\n  const s = state.matchState[moduleId];\n  const m = MODULES.find(x=>x.id===moduleId);\n  if(s.matched.has(idx) || s.selTerm===null) return;\n  const isCorrect = s.selTerm === idx;\n  if(isCorrect){\n    s.matched.add(idx);\n    s.selTerm = null;\n  } else {\n    s.selTerm = null;\n  }\n  setActivityScore(moduleId, 'match', s.matched.size, m.matchPairs.pairs.length);\n  refreshScoreBar(moduleId);\n  rerenderModule();\n}\n\n/* ---- hotspots (pressure points) ---- */\nfunction renderHotspotActivity(m){\n  if(!state.hotspotSel[m.id]) state.hotspotSel[m.id] = { sel:new Set(), revealed:false };\n  const s = state.hotspotSel[m.id];\n  return `\n  <div class=\"panel\">\n    <h4>Atividade \u00b7 Mapa de risco</h4>\n    <div class=\"prompt\">Toque nos pontos do corpo mais propensos a les\u00e3o por press\u00e3o</div>\n    <p style=\"font-size:13px;color:var(--ink-soft);margin-top:-8px;\">Idoso deitado de costas, visto de cima \u2014 cabe\u00e7a \u00e0 esquerda, p\u00e9s \u00e0 direita.</p>\n    <div class=\"scene\">\n      ${bodySilhouetteSVG()}\n      ${HOTSPOTS.map(h=>{\n        let cls = s.sel.has(h.id) ? 'selected' : '';\n        if(s.revealed){\n          if(h.correct && s.sel.has(h.id)) cls='reveal-correct';\n          else if(!h.correct && s.sel.has(h.id)) cls='reveal-wrong';\n          else if(h.correct && !s.sel.has(h.id)) cls='reveal-missed';\n        }\n        return `<button class=\"hotspot ${cls}\" style=\"left:${h.x}%;top:${h.y}%;width:46px;height:46px;font-size:18px;\" title=\"${h.label}\" onclick=\"hotspotToggle('${m.id}','${h.id}')\">${s.revealed && h.correct ? '\u26a0\ufe0f':''}</button>`;\n      }).join('')}\n    </div>\n    <div class=\"btn-row\">\n      <button class=\"btn primary\" onclick=\"hotspotCheck('${m.id}')\">Conferir mapa</button>\n      <button class=\"btn\" onclick=\"hotspotReset('${m.id}')\">Recome\u00e7ar</button>\n    </div>\n    <div class=\"feedback ${s.revealed?'show good':''}\">${s.revealed? '\u2713 Pontos de press\u00e3o revelados acima \u2014 vermelho pulsando \u00e9 o que faltou marcar.' : ''}</div>\n  </div>`;\n}\nfunction bodySilhouetteSVG(){\n  return `<svg viewBox=\"0 0 320 200\" style=\"position:absolute;inset:0;width:100%;height:100%;\" preserveAspectRatio=\"xMidYMid meet\">\n    <ellipse cx=\"180\" cy=\"180\" rx=\"130\" ry=\"10\" fill=\"#2A2A20\" opacity=\"0.05\"/>\n    <!-- legs -->\n    <rect x=\"238\" y=\"64\" width=\"52\" height=\"30\" rx=\"15\" fill=\"url(#clayGrad)\" opacity=\"0.6\"/>\n    <rect x=\"238\" y=\"136\" width=\"52\" height=\"30\" rx=\"15\" fill=\"url(#clayGrad)\" opacity=\"0.5\"/>\n    <ellipse cx=\"286\" cy=\"79\" rx=\"11\" ry=\"14\" fill=\"#8FA07A\" opacity=\"0.6\"/>\n    <ellipse cx=\"286\" cy=\"151\" rx=\"11\" ry=\"14\" fill=\"#8FA07A\" opacity=\"0.5\"/>\n    <!-- hip -->\n    <rect x=\"192\" y=\"66\" width=\"46\" height=\"68\" rx=\"20\" fill=\"url(#clayGrad)\" opacity=\"0.7\"/>\n    <!-- torso -->\n    <rect x=\"94\" y=\"58\" width=\"100\" height=\"84\" rx=\"30\" fill=\"url(#clayGrad)\" opacity=\"0.75\"/>\n    <!-- arms -->\n    <rect x=\"104\" y=\"26\" width=\"86\" height=\"26\" rx=\"13\" fill=\"url(#clayGrad)\" opacity=\"0.55\"/>\n    <rect x=\"104\" y=\"148\" width=\"86\" height=\"26\" rx=\"13\" fill=\"url(#clayGrad)\" opacity=\"0.5\"/>\n    <!-- neck + head -->\n    <rect x=\"72\" y=\"88\" width=\"24\" height=\"24\" rx=\"9\" fill=\"url(#skinGrad)\" opacity=\"0.75\"/>\n    <circle cx=\"46\" cy=\"100\" r=\"30\" fill=\"url(#skinGrad)\" opacity=\"0.8\"/>\n    <path d=\"M22 84 Q18 58 46 58 Q76 58 72 86 Q70 66 46 66 Q24 66 24 86Z\" fill=\"url(#grayHairGrad)\" opacity=\"0.75\"/>\n  </svg>`;\n}\nfunction hotspotToggle(moduleId, id){\n  const s = state.hotspotSel[moduleId];\n  if(s.revealed) return;\n  if(s.sel.has(id)) s.sel.delete(id); else s.sel.add(id);\n  rerenderModule();\n}\nfunction hotspotCheck(moduleId){\n  const s = state.hotspotSel[moduleId];\n  s.revealed = true;\n  const correctTotal = HOTSPOTS.filter(h=>h.correct).length;\n  let correctHits = 0, wrongHits = 0;\n  HOTSPOTS.forEach(h=>{\n    if(s.sel.has(h.id)){ if(h.correct) correctHits++; else wrongHits++; }\n  });\n  const score = Math.max(0, correctHits - wrongHits);\n  setActivityScore(moduleId, 'hotspot', score, correctTotal);\n  refreshScoreBar(moduleId);\n  rerenderModule();\n}\nfunction hotspotReset(moduleId){\n  state.hotspotSel[moduleId] = { sel:new Set(), revealed:false };\n  rerenderModule();\n}\n\n/* ---- room hazards ---- */\nfunction renderRoomActivity(m){\n  if(!state.roomSel[m.id]) state.roomSel[m.id] = { sel:new Set(), revealed:false };\n  const s = state.roomSel[m.id];\n  return `\n  <div class=\"panel\">\n    <h4>Atividade \u00b7 Ca\u00e7a aos riscos</h4>\n    <div class=\"prompt\">Toque em tudo que representa risco de queda neste quarto</div>\n    <div class=\"scene\" style=\"background:linear-gradient(180deg, var(--sage) 0%, #DCE6CC 100%);\">\n      <svg viewBox=\"0 0 400 250\" style=\"position:absolute;inset:0;width:100%;height:100%;\" preserveAspectRatio=\"none\">\n        <!-- floor & wall -->\n        <rect x=\"0\" y=\"170\" width=\"400\" height=\"80\" fill=\"url(#floorGrad)\"/>\n        <line x1=\"0\" y1=\"190\" x2=\"400\" y2=\"190\" stroke=\"#D6CB9F\" stroke-width=\"1.5\" opacity=\"0.5\"/>\n        <line x1=\"0\" y1=\"212\" x2=\"400\" y2=\"212\" stroke=\"#D6CB9F\" stroke-width=\"1.5\" opacity=\"0.5\"/>\n        <line x1=\"0\" y1=\"232\" x2=\"400\" y2=\"232\" stroke=\"#D6CB9F\" stroke-width=\"1.5\" opacity=\"0.5\"/>\n        <rect x=\"0\" y=\"0\" width=\"400\" height=\"172\" fill=\"#EFEEE2\"/>\n        <!-- window -->\n        <rect x=\"20\" y=\"20\" width=\"90\" height=\"70\" rx=\"6\" fill=\"#E3DFC9\" stroke=\"#CFC9AE\" stroke-width=\"3\"/>\n        <line x1=\"65\" y1=\"20\" x2=\"65\" y2=\"90\" stroke=\"#CFC9AE\" stroke-width=\"3\"/>\n        <line x1=\"20\" y1=\"55\" x2=\"110\" y2=\"55\" stroke=\"#CFC9AE\" stroke-width=\"3\"/>\n        <!-- dresser -->\n        <rect x=\"250\" y=\"60\" width=\"130\" height=\"90\" rx=\"8\" fill=\"#F4EFDD\" stroke=\"#D6CFB8\" stroke-width=\"2\"/>\n        <rect x=\"250\" y=\"60\" width=\"130\" height=\"14\" rx=\"6\" fill=\"#DCD5B8\"/>\n        <!-- HAZARD: tapete solto -->\n        <ellipse cx=\"60\" cy=\"205\" rx=\"58\" ry=\"16\" fill=\"#C97B5F\" opacity=\"0.4\" transform=\"rotate(-6 60 205)\"/>\n        <ellipse cx=\"60\" cy=\"205\" rx=\"58\" ry=\"16\" fill=\"none\" stroke=\"#8A4E38\" stroke-width=\"1.5\" opacity=\"0.35\" transform=\"rotate(-6 60 205)\"/>\n        <!-- HAZARD: luz fraca (l\u00e2mpada apagada/fraca) -->\n        <line x1=\"330\" y1=\"40\" x2=\"330\" y2=\"145\" stroke=\"#C9A26B\" stroke-width=\"3\"/>\n        <ellipse cx=\"330\" cy=\"34\" rx=\"20\" ry=\"12\" fill=\"#EFE9D6\" stroke=\"#C9A26B\" stroke-width=\"2\" opacity=\"0.5\"/>\n        <!-- HAZARD: fio de aparelho atravessado (n\u00edvel do ch\u00e3o, longe da m\u00e3o) -->\n        <path d=\"M300,150 L300,230 Q272,238 240,236 Q208,234 180,239 Q168,241 158,238\" fill=\"none\" stroke=\"#3A3A32\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n        <rect x=\"294\" y=\"145\" width=\"10\" height=\"8\" rx=\"2\" fill=\"#3A3A32\"/>\n        <!-- HAZARD: piso molhado -->\n        <ellipse cx=\"212\" cy=\"222\" rx=\"30\" ry=\"11\" fill=\"#AFCBE0\" opacity=\"0.55\"/>\n        <ellipse cx=\"205\" cy=\"219\" rx=\"8\" ry=\"3\" fill=\"#EAF3FA\" opacity=\"0.8\"/>\n        <!-- HAZARD: chinelo ca\u00eddo -->\n        <g transform=\"translate(320,215) rotate(18)\">\n          <ellipse cx=\"0\" cy=\"0\" rx=\"16\" ry=\"7\" fill=\"#B9754F\"/>\n          <path d=\"M-10,0 Q0,-8 10,0\" fill=\"none\" stroke=\"#7A4A2E\" stroke-width=\"2\"/>\n        </g>\n        <!-- HAZARD: caixa no caminho -->\n        <rect x=\"252\" y=\"128\" width=\"34\" height=\"30\" rx=\"2\" fill=\"#D8C79A\" stroke=\"#B39F6E\" stroke-width=\"1.5\"/>\n        <line x1=\"252\" y1=\"140\" x2=\"286\" y2=\"140\" stroke=\"#B39F6E\" stroke-width=\"1.5\"/>\n        <!-- HAZARD: roupa jogada -->\n        <path d=\"M28,148 Q18,140 26,132 Q34,126 44,132 Q54,138 48,148 Q40,156 28,148Z\" fill=\"#8FA0C9\" opacity=\"0.85\"/>\n        <path d=\"M30,140 Q38,136 44,140\" stroke=\"#5F6E96\" stroke-width=\"1.5\" fill=\"none\"/>\n        <!-- HAZARD: degrau sem contraste (sutil, esse \u00e9 o ponto) -->\n        <rect x=\"345\" y=\"212\" width=\"55\" height=\"38\" fill=\"#E3DCC4\"/>\n        <rect x=\"345\" y=\"212\" width=\"55\" height=\"6\" fill=\"#00000010\"/>\n        <line x1=\"345\" y1=\"212\" x2=\"400\" y2=\"212\" stroke=\"#C0B48E\" stroke-width=\"2\"/>\n        <!-- SAFE: corrim\u00e3o firme -->\n        <line x1=\"14\" y1=\"112\" x2=\"96\" y2=\"112\" stroke=\"#33421F\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n        <rect x=\"20\" y=\"106\" width=\"8\" height=\"12\" rx=\"2\" fill=\"#33421F\"/>\n        <rect x=\"52\" y=\"106\" width=\"8\" height=\"12\" rx=\"2\" fill=\"#33421F\"/>\n        <rect x=\"82\" y=\"106\" width=\"8\" height=\"12\" rx=\"2\" fill=\"#33421F\"/>\n        <!-- SAFE: tapete antiderrapante -->\n        <rect x=\"235\" y=\"213\" width=\"70\" height=\"20\" rx=\"4\" fill=\"#E7EEDC\" stroke=\"#3E7A45\" stroke-width=\"1.5\"/>\n        <line x1=\"243\" y1=\"213\" x2=\"243\" y2=\"233\" stroke=\"#3E7A45\" stroke-width=\"2\" opacity=\"0.5\"/>\n        <line x1=\"253\" y1=\"213\" x2=\"253\" y2=\"233\" stroke=\"#3E7A45\" stroke-width=\"2\" opacity=\"0.5\"/>\n        <line x1=\"263\" y1=\"213\" x2=\"263\" y2=\"233\" stroke=\"#3E7A45\" stroke-width=\"2\" opacity=\"0.5\"/>\n        <line x1=\"273\" y1=\"213\" x2=\"273\" y2=\"233\" stroke=\"#3E7A45\" stroke-width=\"2\" opacity=\"0.5\"/>\n        <line x1=\"283\" y1=\"213\" x2=\"283\" y2=\"233\" stroke=\"#3E7A45\" stroke-width=\"2\" opacity=\"0.5\"/>\n        <line x1=\"293\" y1=\"213\" x2=\"293\" y2=\"233\" stroke=\"#3E7A45\" stroke-width=\"2\" opacity=\"0.5\"/>\n        <use href=\"#figElderlyStand\" transform=\"translate(150,60) scale(0.9)\"/>\n      </svg>\n      ${ROOM_ITEMS.map(it=>{\n        let cls = s.sel.has(it.id) ? 'selected' : '';\n        if(s.revealed){\n          if(it.correct && s.sel.has(it.id)) cls='reveal-correct';\n          else if(!it.correct && s.sel.has(it.id)) cls='reveal-wrong';\n          else if(it.correct && !s.sel.has(it.id)) cls='reveal-missed';\n        }\n        return `<button class=\"hotspot ${cls}\" style=\"left:${it.x}%;top:${it.y}%;width:40px;height:40px;\" title=\"${it.label}\" onclick=\"roomToggle('${m.id}','${it.id}')\">${s.revealed && it.correct ? '\u26a0\ufe0f':''}</button>`;\n      }).join('')}\n    </div>\n    <div class=\"btn-row\">\n      <button class=\"btn primary\" onclick=\"roomCheck('${m.id}')\">Conferir riscos</button>\n      <button class=\"btn\" onclick=\"roomReset('${m.id}')\">Recome\u00e7ar</button>\n    </div>\n    <div class=\"feedback ${s.revealed?'show good':''}\">${s.revealed? '\u2713 Riscos revelados \u2014 os itens verdes (\u2705/\ud83d\udfe9) eram seguros e n\u00e3o deviam ser marcados.' : ''}</div>\n  </div>`;\n}\nfunction roomToggle(moduleId, id){\n  const s = state.roomSel[moduleId];\n  if(s.revealed) return;\n  if(s.sel.has(id)) s.sel.delete(id); else s.sel.add(id);\n  rerenderModule();\n}\nfunction roomCheck(moduleId){\n  const s = state.roomSel[moduleId];\n  s.revealed = true;\n  const correctTotal = ROOM_ITEMS.filter(i=>i.correct).length;\n  let correctHits=0, wrongHits=0;\n  ROOM_ITEMS.forEach(it=>{ if(s.sel.has(it.id)){ if(it.correct) correctHits++; else wrongHits++; } });\n  const score = Math.max(0, correctHits-wrongHits);\n  setActivityScore(moduleId, 'room', score, correctTotal);\n  refreshScoreBar(moduleId);\n  rerenderModule();\n}\nfunction roomReset(moduleId){\n  state.roomSel[moduleId] = { sel:new Set(), revealed:false };\n  rerenderModule();\n}\n\n/* ---- dialogue simulator ---- */\nfunction renderDialogueActivity(m){\n  if(!state.dialogueStep[m.id]) state.dialogueStep[m.id] = { step:0, answered:false, done:false };\n  const s = state.dialogueStep[m.id];\n  if(s.done){\n    return `<div class=\"panel\"><h4>Atividade \u00b7 Simulador de conversa</h4><div class=\"feedback show good\">\u2713 Voc\u00ea concluiu as 3 cenas do simulador de comunica\u00e7\u00e3o.</div></div>`;\n  }\n  const scene = DIALOGUE_SCENES[s.step];\n  return `\n  <div class=\"panel\">\n    <h4>Atividade \u00b7 Simulador de conversa</h4>\n    <div class=\"scene-num\">Cena ${s.step+1} de ${DIALOGUE_SCENES.length}</div>\n    <div class=\"prompt\">${scene.situation}</div>\n    <div class=\"mcq\" data-dkey=\"${m.id}\">\n      ${scene.options.map((o,oi)=>`<button class=\"opt ${s.answered?'disabled':''}\" onclick=\"dialogueAnswer('${m.id}',${oi})\">${o.t}</button>`).join('')}\n    </div>\n    <div class=\"feedback ${s.answered?'show '+(s.lastCorrect?'good':'bad'):''}\" id=\"dialogueFb\">${s.answered? (s.lastCorrect?'\u2713 ':'\u2717 ')+ (s.lastFb||'') : ''}</div>\n    <div class=\"btn-row\">\n      <button class=\"btn primary\" onclick=\"dialogueNext('${m.id}')\" ${!s.answered?'disabled':''}>${s.step===DIALOGUE_SCENES.length-1?'Concluir simulador':'Pr\u00f3xima cena'} \u2192</button>\n    </div>\n  </div>`;\n}\nfunction dialogueAnswer(moduleId, oi){\n  const s = state.dialogueStep[moduleId];\n  if(s.answered) return;\n  const scene = DIALOGUE_SCENES[s.step];\n  const opt = scene.options[oi];\n  s.answered = true;\n  s.lastCorrect = opt.correct;\n  s.lastFb = opt.fb;\n  if(!s.results) s.results = [];\n  s.results.push(opt.correct);\n  setActivityScore(moduleId, 'dialogue', s.results.filter(Boolean).length, DIALOGUE_SCENES.length);\n  refreshScoreBar(moduleId);\n  rerenderModule();\n}\nfunction dialogueNext(moduleId){\n  const s = state.dialogueStep[moduleId];\n  if(s.step < DIALOGUE_SCENES.length-1){ s.step += 1; s.answered=false; }\n  else { s.done = true; }\n  rerenderModule();\n}\n\n/* ---- fazer / evitar sort ---- */\nfunction renderSortActivity(m){\n  const data = m.sort;\n  if(!state.sortState[m.id]) state.sortState[m.id] = { placed:{} };\n  const s = state.sortState[m.id];\n  return `\n  <div class=\"panel\">\n    <h4>Atividade \u00b7 Fazer ou Evitar</h4>\n    <div class=\"prompt\">${data.title}</div>\n    ${data.items.map((it,i)=>{\n      const placed = s.placed[i];\n      let cls = placed ? (placed==='good'?'placed-good':'placed-bad') : '';\n      return `<div class=\"sort-item ${cls}\">\n        <span>${it.text}</span>\n        <div class=\"sort-btns\">\n          <button ${placed?'disabled':''} onclick=\"sortPlace('${m.id}',${i},'good')\">\u2705 Fazer</button>\n          <button ${placed?'disabled':''} onclick=\"sortPlace('${m.id}',${i},'bad')\">\ud83d\udeab Evitar</button>\n        </div>\n      </div>`;\n    }).join('')}\n    <div class=\"feedback ${Object.keys(s.placed).length===data.items.length?'show good':''}\">${Object.keys(s.placed).length===data.items.length? '\u2713 Classifica\u00e7\u00e3o conclu\u00edda! Confira as cores: verde \u00e9 o que voc\u00ea marcou certo.' : ''}</div>\n  </div>`;\n}\nfunction sortPlace(moduleId, i, choice){\n  const m = MODULES.find(x=>x.id===moduleId);\n  const s = state.sortState[moduleId];\n  if(s.placed[i]) return;\n  const item = m.sort.items[i];\n  const correct = (choice==='good') === item.good;\n  s.placed[i] = correct ? 'good' : 'bad'; // 'good' = classified correctly, 'bad' = classified incorrectly\n  const rightCount = Object.values(s.placed).filter(v=>v==='good').length;\n  setActivityScore(moduleId, 'sort', rightCount, m.sort.items.length);\n  refreshScoreBar(moduleId);\n  rerenderModule();\n}\n\n/* ======================= RENDER: COMPLETE / CERTIFICATE ======================= */\nfunction renderComplete(){\n  const allPassed = MODULES.every(m=>modulePassed(m.id));\n  if(allPassed) return renderCertificate();\n  return renderResultsNotPassed();\n}\n\nfunction renderResultsNotPassed(){\n  const totalCorrect = MODULES.reduce((a,m)=>a+moduleTotals(m.id).correct,0);\n  const totalQ = MODULES.reduce((a,m)=>a+moduleTotals(m.id).total,0);\n  return `\n  <div class=\"complete-hero\">\n    <div class=\"badge-big pending\" style=\"background:conic-gradient(from -30deg, var(--clay) 0deg, var(--bad) 180deg, var(--clay) 360deg);\"></div>\n    <h1>Quase l\u00e1${state.caregiverName? ', '+state.caregiverName.split(' ')[0] : ''}!</h1>\n    <p>Voc\u00ea passou pelos 5 m\u00f3dulos, mas o crach\u00e1 final s\u00f3 sai quando cada m\u00f3dulo tem <b>6 acertos ou mais</b>. Veja abaixo onde vale revisar \u2014 \u00e9 s\u00f3 refazer o m\u00f3dulo que faltou.</p>\n  </div>\n\n  <div class=\"results-grid\">\n    ${MODULES.map((m,i)=>{\n      const passed = modulePassed(m.id);\n      return `\n      <div class=\"result-card\" style=\"${passed?'':'border-color:rgba(181,73,58,0.35);'}\">\n        <div class=\"t\">${m.icon} ${m.title} ${passed?'\u2705':'\u26d4'}</div>\n        <div class=\"s\" style=\"${passed?'':'color:var(--bad);'}\">${scoreLabel(m.id) || '0/0'}</div>\n        ${!passed?`<button class=\"btn\" style=\"margin-top:10px;\" onclick=\"redoModule(${i})\">Refazer este m\u00f3dulo \u2192</button>`:''}\n      </div>\n    `;}).join('')}\n  </div>\n\n  <p class=\"print-note\">Total geral: ${totalCorrect}/${totalQ} pontos. Meta: 6 ou mais em cada m\u00f3dulo.</p>\n  `;\n}\nfunction redoModule(idx){\n  const m = MODULES[idx];\n  state.completed.delete(m.id);\n  delete state.scoreLog[m.id];\n  delete state.quizLog[m.id];\n  delete state.quizOrder[m.id];\n  delete state.seqOrder[m.id];\n  delete state.matchState[m.id];\n  delete state.hotspotSel[m.id];\n  delete state.roomSel[m.id];\n  delete state.dialogueStep[m.id];\n  delete state.sortState[m.id];\n  if(m.id==='sonda'){ state.angle = { current:50, target:null, rounds:[], roundAnswered:false, lastOk:null }; }\n  state.screen='module';\n  state.moduleIdx = idx;\n  render();\n  window.scrollTo({top:0,behavior:'smooth'});\n}\n\nfunction printCertificate(){\n  const certEl = document.getElementById('certificateArea');\n  if(!certEl) return;\n  const certHTML = certEl.outerHTML;\n  const w = window.open('', '_blank');\n  if(!w){ alert('O navegador bloqueou a janela de impress\u00e3o. Permita pop-ups para este site e tente novamente.'); return; }\n  w.document.open();\n  w.document.write(`<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"UTF-8\">\n<title>Certificado</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,600;9..144,700&family=Work+Sans:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n  @page{ size: landscape; margin: 8mm; }\n  *{box-sizing:border-box;}\n  html,body{margin:0; padding:0; background:#fff;}\n  body{\n    font-family:'Work Sans', sans-serif; color:#2A2A20;\n    display:flex; align-items:center; justify-content:center;\n    width:100%; min-height:100vh;\n  }\n  .certificate-frame{\n    position:relative; background:#FFFDF8;\n    width:258mm; height:186mm; box-sizing:border-box;\n    padding:10mm 20mm;\n    text-align:center;\n    border:4px solid #28331C; outline:10px solid #F1EAB0; outline-offset:-20px;\n    display:flex; flex-direction:column; align-items:center; justify-content:center;\n    page-break-inside:avoid; break-inside:avoid; overflow:hidden;\n  }\n  .cert-leaf{position:absolute; font-size:42px; opacity:0.7;}\n  .cert-leaf.tl{top:14px; left:16px; transform:rotate(-25deg);}\n  .cert-leaf.br{bottom:14px; right:16px; transform:rotate(155deg);}\n  .cert-eyebrow{font-size:15px; letter-spacing:0.18em; text-transform:uppercase; color:#C97B5F; font-weight:700; margin-bottom:14px;}\n  .cert-course{font-family:'Fraunces',serif; font-size:19px; color:#5B5B4C; max-width:60ch; margin:0 auto 22px;}\n  .cert-name{font-family:'Fraunces',serif; font-size:50px; font-weight:700; color:#28331C; border-bottom:2px solid #E7EEDC; display:inline-block; padding:0 20px 14px; margin-bottom:18px;}\n  .cert-role{font-size:16px; font-weight:700; letter-spacing:0.05em; text-transform:uppercase; color:#C97B5F; margin-bottom:20px;}\n  .cert-body{max-width:65ch; margin:0 auto 28px; font-size:16px; color:#5B5B4C; line-height:1.5;}\n  .cert-footer{display:flex; justify-content:space-between; align-items:flex-end; max-width:560px; width:100%; margin:0 auto; padding-top:16px; border-top:1px solid rgba(59,74,46,0.15);}\n  .cert-date{font-size:14px; color:#5B5B4C;}\n  .cert-sign{font-family:'Fraunces',serif; font-weight:700; color:#28331C; font-size:18px; text-align:right;}\n  .cert-sign span{display:block; font-family:'Work Sans',sans-serif; font-weight:500; font-size:10.5px; color:#5B5B4C; text-transform:uppercase; letter-spacing:0.06em;}\n</style>\n</head>\n<body>\n${certHTML}\n</body>\n</html>`);\n  w.document.close();\n  let printed = false;\n  const doPrint = function(){\n    if(printed) return;\n    printed = true;\n    w.focus();\n    w.print();\n  };\n  w.onload = function(){ setTimeout(doPrint, 350); };\n  setTimeout(doPrint, 700); // fallback if onload doesn't fire\n}\n\nfunction renderCertificate(){\n  if(!state.reported){\n    state.reported = true;\n    try{\n      const totalCorrect = MODULES.reduce((a,m)=>a+moduleTotals(m.id).correct,0);\n      const totalQ = MODULES.reduce((a,m)=>a+moduleTotals(m.id).total,0);\n      window.parent.postMessage({type:'training-complete', caregiverName: state.caregiverName||'', score: totalQ? Math.round((totalCorrect/totalQ)*100):0, correct: totalCorrect, total: totalQ}, '*');\n    }catch(e){}\n  }\n  const today = new Date();\n  const dateStr = today.toLocaleDateString('pt-BR', {day:'2-digit', month:'long', year:'numeric'});\n  const name = state.caregiverName || 'Cuidadora(o)';\n  const role = effectiveRole() || 'Cuidador(a) de Idosos';\n  return `\n  <div class=\"complete-hero no-print\">\n    <div class=\"badge-big\"></div>\n    <h1>Crach\u00e1 completo, ${name.split(' ')[0]}! \ud83c\udf3f</h1>\n    <p>Voc\u00ea passou pelos 5 m\u00f3dulos com 6 acertos ou mais em cada um. Isso \u00e9 o que sustenta um plant\u00e3o seguro \u2014 para voc\u00ea e para quem est\u00e1 sob seu cuidado.</p>\n  </div>\n\n  <div class=\"certificate-frame\" id=\"certificateArea\">\n    <div class=\"cert-leaf tl\">\ud83c\udf3f</div>\n    <div class=\"cert-leaf br\">\ud83c\udf3f</div>\n    <div class=\"cert-eyebrow\">Certificado de Conclus\u00e3o</div>\n    <div class=\"cert-course\">Transfer\u00eancias, Posicionamento e Comunica\u00e7\u00e3o Humanizada para Idosos</div>\n    <div class=\"cert-name\">${name}</div>\n    <div class=\"cert-role\">${role}</div>\n    <div class=\"cert-body\">concluiu com aproveitamento o treinamento interativo para colaboradores, com desempenho m\u00ednimo de 6 acertos em cada um dos 5 m\u00f3dulos do programa.</div>\n    <div class=\"cert-footer\">\n      <div class=\"cert-date\">${dateStr}</div>\n      <div class=\"cert-sign\">Diu Vitae<span>Treinamento do Cuidador</span></div>\n    </div>\n  </div>\n\n  <div class=\"results-grid no-print\">\n    ${MODULES.map(m=>`\n      <div class=\"result-card\">\n        <div class=\"t\">${m.icon} ${m.title}</div>\n        <div class=\"s\">${scoreLabel(m.id) || '\u2014'}</div>\n      </div>\n    `).join('')}\n  </div>\n\n  <div class=\"quote-close no-print\">\n    \"Ao final de cada plant\u00e3o, nada \u00e9 mais valioso do que levar nossos h\u00f3spedes aos seus aposentos com <b>bem-estar, sa\u00fade e seguran\u00e7a</b>.\"\n    <div style=\"font-family:'Work Sans',sans-serif;font-size:13px;margin-top:14px;color:#B9C6A7;\">\u2014 Diu Vitae</div>\n  </div>\n\n  <div class=\"btn-row no-print\" style=\"justify-content:center;margin-top:28px;\">\n    <button class=\"btn primary\" onclick=\"printCertificate()\">\ud83d\udda8\ufe0f Imprimir certificado</button>\n    <button class=\"btn\" onclick=\"restartAll()\">\u21ba Refazer o treinamento</button>\n  </div>\n  `;\n}\n\nfunction restartAll(){\n  state.completed = new Set();\n  state.scoreLog = {};\n  state.quizLog = {};\n  state.quizOrder = {};\n  state.seqOrder = {};\n  state.matchState = {};\n  state.hotspotSel = {};\n  state.roomSel = {};\n  state.dialogueStep = {};\n  state.sortState = {};\n  state.angle = { current:50, target:null, rounds:[], roundAnswered:false, lastOk:null };\n  state.screen='home';\n  render();\n  window.scrollTo({top:0,behavior:'smooth'});\n}\n\n/* ======================= UTILS ======================= */\nfunction shuffle(arr){\n  const a = arr.slice();\n  for(let i=a.length-1;i>0;i--){ const j = Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; }\n  return a;\n}\nfunction rerenderModule(){\n  document.getElementById('app').innerHTML = renderModule(state.moduleIdx);\n  renderCrachaMini();\n}\n\n/* ======================= MAIN RENDER ======================= */\nfunction render(){\n  const app = document.getElementById('app');\n  if(state.screen==='home') app.innerHTML = renderHome();\n  else if(state.screen==='module') app.innerHTML = renderModule(state.moduleIdx);\n  else if(state.screen==='complete') app.innerHTML = renderComplete();\n  renderCrachaMini();\n}\nrender();\n</script>\n</body>\n</html>\n";
