const AUTO_CHECKLIST = {
  "p1-2": (pd) => (pd.processes.find((p) => p.nome === "Admissão")?.etapas.length || 0) >= 3,
  "p1-3": (pd) => (pd.processes.find((p) => p.nome === "Desligamento")?.etapas.length || 0) >= 3,
  "p1-4": (pd) => pd.colaboradores.length > 0,
  "p2-1": (pd) => !!(pd.culture.missao && pd.culture.visao && pd.culture.valores.length > 0),
  "p3-1": (pd) => pd.onboardingTemplates.length > 0,
  "p4-3": (pd) => !!pd.feedbackPolicy.objetivo || pd.feedbackPolicy.tipos.length > 0,
};

function currentMonthKey() { return new Date().toISOString().slice(0, 7); }
function formatMonthLabel(key) {
  const [y, m] = key.split("-");
  return new Date(Number(y), Number(m) - 1, 1).toLocaleDateString("pt-BR", { month: "long", year: "numeric" });
}
function isItemDone(item, pd, monthKey) {
  const auto = AUTO_CHECKLIST[item.id];
  if (auto) return auto(pd);
  return !!pd.checklistHistory[monthKey]?.[item.id]?.done;
}
function phaseProgress(phaseId, pd, monthKey) {
  const items = CHECKLIST_ITEMS.filter((i) => i.phase === phaseId);
  if (!items.length) return 0;
  return Math.round((items.filter((i) => isItemDone(i, pd, monthKey)).length / items.length) * 100);
}
function overallProgress(pd, monthKey) {
  return Math.round((CHECKLIST_ITEMS.filter((i) => isItemDone(i, pd, monthKey)).length / CHECKLIST_ITEMS.length) * 100);
}
function monthsAvailable(pd, submissions, turnover) {
  const set = new Set(Object.keys(pd.checklistHistory || {}));
  set.add(currentMonthKey());
  const addM = (list) => list.forEach((x) => { if (x.date) { const p = x.date.split("/"); if (p.length === 3) set.add(`${p[2]}-${p[1]}`); } });
  addM(submissions.diagnostico); addM(submissions.feedback); addM(submissions.ethicsAck); addM(submissions.muvAck); addM(submissions.leaderEvaluations);
  turnover.entries.forEach((e) => { if (e.mes) set.add(e.mes); });
  return Array.from(set).sort().reverse();
}
function filterByMonth(list, monthKey) {
  return list.filter((x) => { if (!x.date) return false; const p = x.date.split("/"); return p.length === 3 && `${p[2]}-${p[1]}` === monthKey; });
}

const DIAG_DIMENSIONS = [
  { key: "comunicacao", label: "Comunicação", questions: [{ id: "com1", text: "As informações importantes chegam até você com clareza?" }, { id: "com2", text: "Você se sente à vontade para se comunicar com a liderança?" }] },
  { key: "lideranca", label: "Liderança", questions: [{ id: "lid1", text: "Sua liderança direta reconhece seu trabalho?" }, { id: "lid2", text: "Você confia nas decisões da liderança?" }] },
  { key: "condicoes", label: "Condições de Trabalho", questions: [{ id: "cond1", text: "Você possui os materiais e equipamentos necessários?" }, { id: "cond2", text: "A carga de trabalho é adequada ao seu turno?" }] },
  { key: "relacionamento", label: "Relacionamento em Equipe", questions: [{ id: "rel1", text: "O ambiente entre colegas é colaborativo?" }, { id: "rel2", text: "Há respeito entre os membros da equipe?" }] },
  { key: "clareza", label: "Clareza de Papel", questions: [{ id: "cla1", text: "Você entende claramente suas responsabilidades?" }, { id: "cla2", text: "Você sabe a quem recorrer em caso de dúvidas?" }] },
  { key: "satisfacao", label: "Satisfação e Engajamento", questions: [{ id: "sat1", text: "Você se sente satisfeito(a) em trabalhar aqui?" }, { id: "sat2", text: "Você recomendaria esta instituição como um bom lugar para trabalhar?" }] },
];
function diagAverages(list) {
  return DIAG_DIMENSIONS.map((d) => {
    const vals = list.map((r) => r.scores?.[d.key]).filter((v) => typeof v === "number");
    return { dimension: d.label, media: vals.length ? +(vals.reduce((a, b) => a + b, 0) / vals.length).toFixed(2) : 0 };
  });
}

