function StatusStamp({ pct }) {
  let label = "PENDENTE", color = T.inkSoft;
  if (pct >= 100) { label = "CONCLUÍDO"; color = T.success; } else if (pct > 0) { label = "EM ANDAMENTO"; color = T.amber; }
  return <span className="stamp text-[10px] font-semibold inline-block" style={{ color }}>{label}</span>;
}
function ProgressBar({ pct, color = T.cyan }) {
  return <div className="w-full h-1.5 rounded-full" style={{ background: T.line + "55" }}><div className="h-1.5 rounded-full transition-all" style={{ width: `${pct}%`, background: color }} /></div>;
}
function Field({ label, children }) {
  return <label className="block mb-3"><span className="block text-xs f-mono uppercase tracking-wide mb-1" style={{ color: T.inkSoft }}>{label}</span>{children}</label>;
}
const inputCls = "w-full rounded-md px-3 py-2 text-sm f-body border outline-none focus:ring-2";
const inputStyle = { borderColor: T.line, background: T.paperRaised };
function Btn({ children, onClick, variant = "primary", type = "button", className = "", disabled }) {
  const styles = {
    primary: { background: T.ink, color: "#fff" }, accent: { background: T.cyan, color: "#fff" },
    ghost: { background: "transparent", color: T.ink, border: `1px solid ${T.line}` }, danger: { background: "transparent", color: T.danger, border: `1px solid ${T.danger}55` },
  };
  return <button type={type} onClick={onClick} disabled={disabled} className={`inline-flex items-center gap-1.5 px-3 py-2 rounded-md text-sm font-medium transition-opacity hover:opacity-85 disabled:opacity-40 ${className}`} style={styles[variant]}>{children}</button>;
}
function SectionCard({ children }) { return <Frame className="rounded-xl p-5 mb-4" style={{ background: T.paperRaised, border: `1px solid ${T.line}` }}>{children}</Frame>; }
function Confirm({ text }) { return <div className="flex items-center gap-2 text-sm px-3 py-2 rounded-md" style={{ background: T.successSoft, color: T.success }}><CheckCircle2 size={16} /> {text}</div>; }
function AddInline({ placeholder, onAdd }) {
  const [v, setV] = useState("");
  return <form onSubmit={(e) => { e.preventDefault(); if (v.trim()) { onAdd(v.trim()); setV(""); } }} className="flex gap-2 mt-2">
    <input className={inputCls} style={inputStyle} placeholder={placeholder} value={v} onChange={(e) => setV(e.target.value)} /><Btn type="submit" variant="ghost"><Plus size={13} /></Btn>
  </form>;
}
function TagList({ items, onAdd, onRemove, placeholder, bg, readOnly }) {
  const [val, setVal] = useState("");
  return (
    <div>
      <div className="flex flex-wrap gap-1.5 mb-2">
        {items.map((t, idx) => (
          <span key={idx} className="text-xs f-mono px-2 py-1 rounded-full inline-flex items-center gap-1" style={{ background: bg || T.cyanSoft, color: T.ink }}>
            {t}{!readOnly && <button onClick={() => onRemove(idx)} className="opacity-60 hover:opacity-100"><X size={11} /></button>}
          </span>
        ))}
        {items.length === 0 && <span className="text-xs italic" style={{ color: T.inkSoft }}>Nenhum item ainda.</span>}
      </div>
      {!readOnly && <form onSubmit={(e) => { e.preventDefault(); if (val.trim()) { onAdd(val.trim()); setVal(""); } }} className="flex gap-2">
        <input className={inputCls} style={inputStyle} placeholder={placeholder} value={val} onChange={(e) => setVal(e.target.value)} /><Btn type="submit" variant="ghost"><Plus size={14} /></Btn>
      </form>}
    </div>
  );
}
function MiniStat({ label, value, ok }) {
  return <div className="rounded-lg p-2.5 text-center" style={{ background: ok === true ? T.successSoft : ok === false ? T.amberSoft : T.paper, border: `1px solid ${T.line}` }}>
    <div className="f-display text-sm font-semibold" style={{ color: T.ink }}>{value}</div><div className="text-[10px] f-mono uppercase" style={{ color: T.inkSoft }}>{label}</div>
  </div>;
}

function ChecklistCategory({ title, items, pd, monthKey, onToggle, readOnly }) {
  return (
    <div className="mb-5">
      <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>{title}</div>
      <div className="space-y-1.5">
        {items.map((item) => {
          const auto = !!AUTO_CHECKLIST[item.id];
          const done = isItemDone(item, pd, monthKey);
          const disabled = auto || readOnly;
          return (
            <button key={item.id} disabled={disabled} onClick={() => !disabled && onToggle(item.id)} className="w-full flex items-start gap-2.5 text-left px-3 py-2 rounded-md hover:bg-black/[.02] disabled:cursor-default" style={{ border: `1px solid ${T.line}` }}>
              {done ? <CheckCircle2 size={18} style={{ color: T.success, flexShrink: 0, marginTop: 1 }} /> : <Circle size={18} style={{ color: T.inkSoft, flexShrink: 0, marginTop: 1 }} />}
              <span className="text-sm f-body flex-1" style={{ color: done ? T.inkSoft : T.ink, textDecoration: done ? "line-through" : "none" }}>{item.label}</span>
              {auto && <span className="text-[10px] f-mono shrink-0" style={{ color: T.cyan }}>AUTO</span>}
            </button>
          );
        })}
      </div>
    </div>
  );
}

function ListManager({ title, items, onAdd, onDelete, columns, readOnly }) {
  const emptyForm = Object.fromEntries(columns.map((c) => [c.key, c.default ?? ""]));
  const [form, setForm] = useState(emptyForm);
  const submit = (e) => { e.preventDefault(); onAdd({ ...form, id: Date.now() + "-" + Math.random().toString(36).slice(2, 7) }); setForm(emptyForm); };
  return (
    <div>
      {title && <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>{title}</div>}
      {!readOnly && (
        <form onSubmit={submit} className="flex flex-wrap gap-2 mb-3 items-end">
          {columns.map((c) => (
            <div key={c.key} style={{ minWidth: c.width || 140 }} className="flex-1">
              {c.type === "select" ? (
                <select className={inputCls} style={inputStyle} value={form[c.key]} onChange={(e) => setForm((f) => ({ ...f, [c.key]: e.target.value }))}>{c.options.map((o) => <option key={o} value={o}>{o}</option>)}</select>
              ) : <input className={inputCls} style={inputStyle} type={c.type || "text"} placeholder={c.label} value={form[c.key]} onChange={(e) => setForm((f) => ({ ...f, [c.key]: e.target.value }))} />}
            </div>
          ))}
          <Btn type="submit" variant="accent"><Plus size={16} />Adicionar</Btn>
        </form>
      )}
      <div className="space-y-1.5">
        {items.length === 0 && <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhum registro ainda.</p>}
        {items.map((it) => (
          <div key={it.id} className="flex items-center justify-between gap-2 px-3 py-2 rounded-md" style={{ border: `1px solid ${T.line}` }}>
            <div className="text-sm f-body flex flex-wrap gap-x-3 gap-y-0.5">{columns.map((c) => it[c.key] ? <span key={c.key}><span className="f-mono text-xs" style={{ color: T.inkSoft }}>{c.label}: </span>{it[c.key]}</span> : null)}</div>
            {!readOnly && <button onClick={() => onDelete(it.id)} className="p-1 rounded hover:bg-black/5" style={{ color: T.danger }}><Trash2 size={15} /></button>}
          </div>
        ))}
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* PROCESSOS (Fase 1)                                                   */
/* ------------------------------------------------------------------ */
function ProcessCard({ process, onUpdate, onDelete, custom, readOnly }) {
  const [stepForm, setStepForm] = useState({ label: "", responsavel: "", prazo: "" });
  const tip = PROCESS_TIPS[process.nome] || DEFAULT_PROCESS_TIP;
  const status = process.etapas.length >= 3 ? "Mapeado" : process.etapas.length > 0 ? "Em mapeamento" : "Pendente";
  const statusColor = status === "Mapeado" ? T.success : status === "Em mapeamento" ? T.amber : T.inkSoft;
  const addStep = (e) => { e.preventDefault(); if (!stepForm.label.trim()) return; onUpdate({ ...process, etapas: [...process.etapas, { id: Date.now() + "", ...stepForm }] }); setStepForm({ label: "", responsavel: "", prazo: "" }); };
  return (
    <div className="rounded-lg p-4 mb-3" style={{ border: `1px solid ${T.line}` }}>
      <div className="flex items-center justify-between mb-2">
        <h4 className="f-display font-semibold text-sm" style={{ color: T.ink }}>{process.nome}</h4>
        <div className="flex items-center gap-2">
          <span className="text-xs f-mono px-2 py-0.5 rounded-full" style={{ background: statusColor + "22", color: statusColor }}>{status}</span>
          {custom && !readOnly && <button onClick={onDelete} style={{ color: T.danger }}><Trash2 size={14} /></button>}
        </div>
      </div>
      <div className="flex gap-2 text-xs p-2 rounded-md mb-3" style={{ background: T.cyanSoft, color: T.ink }}><Wand2 size={14} style={{ flexShrink: 0, color: T.cyan, marginTop: 1 }} /><span>{tip}</span></div>
      <div className="mb-3">
        <div className="text-xs f-mono uppercase mb-1.5" style={{ color: T.inkSoft }}>Etapas ({process.etapas.length})</div>
        <div className="space-y-1.5 mb-2">
          {process.etapas.map((s, idx) => (
            <div key={s.id} className="flex items-center justify-between text-sm px-2.5 py-1.5 rounded" style={{ background: T.paper }}>
              <span><b>{idx + 1}.</b> {s.label}{s.responsavel && <span style={{ color: T.inkSoft }}> — {s.responsavel}</span>}{s.prazo && <span className="f-mono text-xs" style={{ color: T.inkSoft }}> ({s.prazo})</span>}</span>
              {!readOnly && <button onClick={() => onUpdate({ ...process, etapas: process.etapas.filter((x) => x.id !== s.id) })} style={{ color: T.danger }}><Trash2 size={13} /></button>}
            </div>
          ))}
        </div>
        {!readOnly && (
          <form onSubmit={addStep} className="flex flex-wrap gap-2">
            <input className={inputCls} style={{ ...inputStyle, flex: 2, minWidth: 140 }} placeholder="Etapa" value={stepForm.label} onChange={(e) => setStepForm((f) => ({ ...f, label: e.target.value }))} />
            <input className={inputCls} style={{ ...inputStyle, flex: 1, minWidth: 100 }} placeholder="Responsável" value={stepForm.responsavel} onChange={(e) => setStepForm((f) => ({ ...f, responsavel: e.target.value }))} />
            <input className={inputCls} style={{ ...inputStyle, flex: 1, minWidth: 90 }} placeholder="Prazo" value={stepForm.prazo} onChange={(e) => setStepForm((f) => ({ ...f, prazo: e.target.value }))} />
            <Btn type="submit" variant="accent"><Plus size={14} /></Btn>
          </form>
        )}
      </div>
      <div><div className="text-xs f-mono uppercase mb-1.5" style={{ color: T.inkSoft }}>Pontos de atenção / risco</div>
        <TagList readOnly={readOnly} items={process.riscos} onAdd={(v) => onUpdate({ ...process, riscos: [...process.riscos, v] })} onRemove={(idx) => onUpdate({ ...process, riscos: process.riscos.filter((_, i) => i !== idx) })} placeholder="Ex: prazo legal..." bg={T.amberSoft} /></div>
    </div>
  );
}
function ProcessMapper({ processes, onUpdateProcess, onAddProcess, onDeleteProcess, readOnly }) {
  const [newName, setNewName] = useState("");
  const defaultNames = ["Admissão", "Desligamento"];
  return (
    <div>
      {processes.map((p) => <ProcessCard key={p.id} process={p} onUpdate={(np) => onUpdateProcess(p.id, np)} onDelete={() => onDeleteProcess(p.id)} custom={!defaultNames.includes(p.nome)} readOnly={readOnly} />)}
      {!readOnly && (
        <form onSubmit={(e) => { e.preventDefault(); if (newName.trim()) { onAddProcess(newName.trim()); setNewName(""); } }} className="flex gap-2 mt-2">
          <input className={inputCls} style={inputStyle} placeholder="Novo processo a mapear (ex: Compras, Escalas...)" value={newName} onChange={(e) => setNewName(e.target.value)} />
          <Btn type="submit" variant="ghost"><Plus size={14} />Adicionar processo</Btn>
        </form>
      )}
    </div>
  );
}

