function AlignmentPlan({ valores, alignmentActions, onGenerate, onToggleAction, onAddAction, onRemoveAction, readOnly }) {
  return (
    <div>
      {valores.map((valor) => {
        const actions = alignmentActions[valor] || [];
        return (
          <div key={valor} className="mb-4 rounded-lg p-3" style={{ border: `1px solid ${T.line}` }}>
            <div className="flex items-center justify-between mb-2">
              <span className="f-display font-semibold text-sm" style={{ color: T.ink }}>{valor}</span>
              {actions.length === 0 && !readOnly && <Btn variant="ghost" onClick={() => onGenerate(valor)}><Wand2 size={13} />Gerar sugestões</Btn>}
            </div>
            <div className="space-y-1.5">
              {actions.map((a) => (
                <div key={a.id} className="flex items-center gap-2">
                  <button disabled={readOnly} onClick={() => onToggleAction(valor, a.id)}>{a.done ? <CheckCircle2 size={16} style={{ color: T.success }} /> : <Circle size={16} style={{ color: T.inkSoft }} />}</button>
                  <span className="text-sm flex-1" style={{ color: T.ink, textDecoration: a.done ? "line-through" : "none" }}>{a.text}</span>
                  {!readOnly && <button onClick={() => onRemoveAction(valor, a.id)} style={{ color: T.danger }}><Trash2 size={13} /></button>}
                </div>
              ))}
            </div>
            {actions.length > 0 && !readOnly && <AddInline placeholder="Adicionar ação de alinhamento..." onAdd={(v) => onAddAction(valor, v)} />}
          </div>
        );
      })}
    </div>
  );
}

