function OnboardingBuilder({ templates, onGenerate, onDeleteTemplate, onAddTask, onRemoveTask, readOnly }) {
  const [cargo, setCargo] = useState(ILPI_CARGOS[0]);
  return (
    <div>
      {!readOnly && (
        <div className="flex flex-wrap gap-2 items-end mb-4">
          <div style={{ minWidth: 200 }}><Field label="Gerar modelo para o cargo"><select className={inputCls} style={inputStyle} value={cargo} onChange={(e) => setCargo(e.target.value)}>{ILPI_CARGOS.map((c) => <option key={c}>{c}</option>)}</select></Field></div>
          <Btn variant="accent" onClick={() => onGenerate(cargo)}><Wand2 size={15} />Gerar plano de integração</Btn>
        </div>
      )}
      {templates.length === 0 && <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhum plano gerado ainda.</p>}
      {templates.map((t) => (
        <div key={t.id} className="rounded-lg p-4 mb-3" style={{ border: `1px solid ${T.line}` }}>
          <div className="flex justify-between items-center mb-2">
            <span className="f-display font-semibold text-sm" style={{ color: T.ink }}>Integração — {t.cargo}</span>
            {!readOnly && <button onClick={() => onDeleteTemplate(t.id)} style={{ color: T.danger }}><Trash2 size={14} /></button>}
          </div>
          <div className="grid sm:grid-cols-2 gap-3">
            {ONBOARDING_PERIODS.map(([key, label]) => (
              <div key={key}>
                <div className="text-xs f-mono uppercase mb-1" style={{ color: T.cyan }}>{label}</div>
                <ul className="space-y-1 mb-1.5">{t.tasks[key].map((task) => (
                  <li key={task.id} className="text-sm flex justify-between items-start gap-1"><span>• {task.text}</span>{!readOnly && <button onClick={() => onRemoveTask(t.id, key, task.id)} style={{ color: T.danger }}><Trash2 size={12} /></button>}</li>
                ))}</ul>
                {!readOnly && <AddInline placeholder="Adicionar tarefa..." onAdd={(v) => onAddTask(t.id, key, v)} />}
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

