function FeedbackPolicyBuilder({ policy, onChangeObjetivo, onChangeNotas, onAddTipo, onRemoveTipo, readOnly }) {
  return (
    <div>
      <div className="text-xs p-2 rounded-md mb-3 flex gap-2" style={{ background: T.cyanSoft, color: T.ink }}><Wand2 size={14} style={{ color: T.cyan, flexShrink: 0, marginTop: 1 }} /><span>Defina o objetivo, os formatos praticados (1:1, 360°, PDI) e a frequência de cada um.</span></div>
      <Field label="Objetivo da política de feedback"><textarea disabled={readOnly} className={inputCls} style={{ ...inputStyle, minHeight: 70 }} value={policy.objetivo} onChange={(e) => onChangeObjetivo(e.target.value)} /></Field>
      <ListManager title="Formatos de feedback" items={policy.tipos} onAdd={onAddTipo} onDelete={onRemoveTipo} readOnly={readOnly}
        columns={[{ key: "tipo", label: "Tipo", type: "select", options: ["1:1", "360°", "PDI", "Avaliação de desempenho", "Outro"], default: "1:1" }, { key: "frequencia", label: "Frequência", type: "select", options: ["Semanal", "Quinzenal", "Mensal", "Trimestral", "Semestral", "Anual"], default: "Mensal" }, { key: "descricao", label: "Descrição", width: 220 }]} />
      <Field label="Cole aqui sua política de feedback atual (referência)"><textarea disabled={readOnly} className={inputCls} style={{ ...inputStyle, minHeight: 90 }} value={policy.notasAtual} onChange={(e) => onChangeNotas(e.target.value)} placeholder="Cole aqui o texto atual..." /></Field>
    </div>
  );
}

