function OrgChart({ colaboradores }) {
  const ativos = colaboradores.filter((c) => (c.status || "Ativo") === "Ativo");
  if (ativos.length === 0) return <p className="text-sm italic" style={{ color: T.inkSoft }}>Adicione colaboradores em "Colaboradores" — o organograma é montado automaticamente a partir da equipe cadastrada.</p>;
  return (
    <div className="space-y-4">
      {CARGO_HIERARCHY.map((level) => {
        const people = ativos.filter((c) => level.cargos.includes(c.cargo));
        if (!people.length) return null;
        return (
          <div key={level.title}>
            <div className="text-center mb-2"><span className="text-xs f-mono uppercase tracking-wide px-2 py-0.5 rounded-full" style={{ background: T.cyanSoft, color: T.cyan }}>{level.title}</span></div>
            <div className="flex flex-wrap justify-center gap-2">
              {people.map((p) => (
                <div key={p.id} className="rounded-lg px-3 py-2 text-center" style={{ border: `1px solid ${T.line}`, background: T.paperRaised, minWidth: 110 }}>
                  <div className="text-xs font-medium" style={{ color: T.ink }}>{p.nome}</div>
                  <div className="text-[10px]" style={{ color: T.inkSoft }}>{p.cargo}</div>
                </div>
              ))}
            </div>
          </div>
        );
      })}
    </div>
  );
}

function Phase1({ pd, mk, toggle, submissions, addPartnership, delPartnership, updateProcess, addProcess, deleteProcess, readOnly }) {
  const diagList = submissions.diagnostico, chartData = diagAverages(diagList);
  return (
    <div>
      <PhaseHeader phase={PHASES[0]} />
      <SectionCard>
        <ChecklistCategory title="Formulários" items={catItems("fase1", "formularios")} pd={pd} monthKey={mk} onToggle={toggle} readOnly={readOnly} />
        <div className="text-xs f-mono uppercase tracking-wide mb-2 mt-4" style={{ color: T.cyan }}>Resultado do diagnóstico organizacional ({diagList.length} respostas)</div>
        {diagList.length === 0 ? <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhuma resposta recebida ainda.</p> : (
          <>
            <div className="h-52 mb-3"><ResponsiveContainer width="100%" height="100%"><BarChart data={chartData}><CartesianGrid strokeDasharray="3 3" stroke={T.line} /><XAxis dataKey="dimension" tick={{ fontSize: 10 }} interval={0} angle={-15} textAnchor="end" height={55} /><YAxis domain={[0, 5]} tick={{ fontSize: 11 }} /><Tooltip /><Bar dataKey="media" fill={T.cyan} radius={[4, 4, 0, 0]} /></BarChart></ResponsiveContainer></div>
            <div className="space-y-2 max-h-56 overflow-y-auto scrollbar-thin pr-1">{diagList.slice().reverse().map((d) => <div key={d.id} className="text-sm px-3 py-2 rounded-md" style={{ border: `1px solid ${T.line}` }}><div className="flex justify-between text-xs f-mono mb-1" style={{ color: T.inkSoft }}><span>{d.nome || "Anônimo"}{d.area && ` · ${d.area}`}</span><span>{d.date} · média {d.overall}</span></div>{d.comentario && <p className="italic" style={{ color: T.inkSoft }}>"{d.comentario}"</p>}</div>)}</div>
          </>
        )}
      </SectionCard>
      <SectionCard>
        <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Organograma (automático)</div>
        <OrgChart colaboradores={pd.colaboradores} />
      </SectionCard>
      <SectionCard>
        <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Processos (mapeamento guiado)</div>
        <ProcessMapper processes={pd.processes} onUpdateProcess={updateProcess} onAddProcess={addProcess} onDeleteProcess={deleteProcess} readOnly={readOnly} />
      </SectionCard>
      <SectionCard><ListManager title="Parcerias" items={pd.partnerships} onAdd={addPartnership} onDelete={delPartnership} readOnly={readOnly}
        columns={[{ key: "name", label: "Parceiro", width: 200 }, { key: "type", label: "Tipo", type: "select", options: ["Benefícios", "Saúde", "Recrutamento", "Treinamento", "Jurídico", "Outro"], default: "Benefícios" }, { key: "status", label: "Status", type: "select", options: ["Em negociação", "Ativa", "Encerrada"], default: "Em negociação" }]} /></SectionCard>
    </div>
  );
}

