function LeaderEvalForm({ onSubmit }) {
  const [scores, setScores] = useState(() => Object.fromEntries(LEADER_CRITERIA.map((c) => [c, "3"])));
  const [pontosPositivos, setPP] = useState(""), [pontosMelhoria, setPM] = useState(""), [avaliadora, setAvaliadora] = useState("");
  const [date, setDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [sent, setSent] = useState(false);
  if (sent) return <Confirm text="Avaliação registrada." />;
  const submit = (e) => {
    e.preventDefault();
    const vals = LEADER_CRITERIA.map((c) => Number(scores[c]));
    const media = +(vals.reduce((a, b) => a + b, 0) / vals.length).toFixed(2);
    onSubmit({ scores, media, pontosPositivos, pontosMelhoria, avaliadora, date: new Date(date + "T00:00:00").toLocaleDateString("pt-BR") });
    setSent(true);
  };
  return (
    <form onSubmit={submit}>
      <div className="grid sm:grid-cols-2 gap-2 mb-3">
        <Field label="Data da avaliação"><input type="date" required className={inputCls} style={inputStyle} value={date} onChange={(e) => setDate(e.target.value)} /></Field>
        <Field label="Nome da líder avaliadora"><input required className={inputCls} style={inputStyle} value={avaliadora} onChange={(e) => setAvaliadora(e.target.value)} /></Field>
      </div>
      <div className="grid sm:grid-cols-2 gap-x-4 gap-y-2 mb-3">
        {LEADER_CRITERIA.map((c) => (
          <div key={c}><div className="flex justify-between text-xs mb-0.5"><span style={{ color: T.ink }}>{c}</span><span className="f-mono" style={{ color: T.cyan }}>{scores[c]}</span></div>
            <input type="range" min="1" max="5" className="w-full" value={scores[c]} onChange={(e) => setScores((s) => ({ ...s, [c]: e.target.value }))} /></div>
        ))}
      </div>
      <Field label="Pontos positivos"><textarea required className={inputCls} style={{ ...inputStyle, minHeight: 60 }} value={pontosPositivos} onChange={(e) => setPP(e.target.value)} /></Field>
      <Field label="Pontos de melhoria"><textarea required className={inputCls} style={{ ...inputStyle, minHeight: 60 }} value={pontosMelhoria} onChange={(e) => setPM(e.target.value)} /></Field>
      <Btn type="submit" variant="accent"><Send size={15} />Registrar avaliação</Btn>
    </form>
  );
}

function CandidateEvalForm({ onSubmit }) {
  const [nome, setNome] = useState(""), [cpf, setCpf] = useState(""), [avaliadora, setAvaliadora] = useState("");
  const [scores, setScores] = useState(() => Object.fromEntries(LEADER_CRITERIA.map((c) => [c, "3"])));
  const [pontosPositivos, setPP] = useState(""), [pontosMelhoria, setPM] = useState("");
  const [date, setDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [sent, setSent] = useState(false);
  if (sent) return <Confirm text="Avaliação de dia de teste registrada." />;
  const submit = (e) => {
    e.preventDefault();
    const vals = LEADER_CRITERIA.map((c) => Number(scores[c]));
    const media = +(vals.reduce((a, b) => a + b, 0) / vals.length).toFixed(2);
    onSubmit({ id: uid(), nome, cpf, avaliadora, scores, media, pontosPositivos, pontosMelhoria, date: new Date(date + "T00:00:00").toLocaleDateString("pt-BR") });
    setSent(true);
  };
  return (
    <form onSubmit={submit}>
      <div className="grid sm:grid-cols-3 gap-2 mb-3">
        <Field label="Nome do candidato"><input required className={inputCls} style={inputStyle} value={nome} onChange={(e) => setNome(e.target.value)} /></Field>
        <Field label="CPF"><input required className={inputCls} style={inputStyle} value={cpf} onChange={(e) => setCpf(e.target.value)} /></Field>
        <Field label="Data do dia de teste"><input type="date" required className={inputCls} style={inputStyle} value={date} onChange={(e) => setDate(e.target.value)} /></Field>
      </div>
      <Field label="Nome da líder avaliadora"><input required className={inputCls} style={inputStyle} value={avaliadora} onChange={(e) => setAvaliadora(e.target.value)} /></Field>
      <div className="grid sm:grid-cols-2 gap-x-4 gap-y-2 mb-3">
        {LEADER_CRITERIA.map((c) => (
          <div key={c}><div className="flex justify-between text-xs mb-0.5"><span style={{ color: T.ink }}>{c}</span><span className="f-mono" style={{ color: T.cyan }}>{scores[c]}</span></div>
            <input type="range" min="1" max="5" className="w-full" value={scores[c]} onChange={(e) => setScores((s) => ({ ...s, [c]: e.target.value }))} /></div>
        ))}
      </div>
      <Field label="Pontos positivos"><textarea required className={inputCls} style={{ ...inputStyle, minHeight: 60 }} value={pontosPositivos} onChange={(e) => setPP(e.target.value)} /></Field>
      <Field label="Pontos de melhoria"><textarea required className={inputCls} style={{ ...inputStyle, minHeight: 60 }} value={pontosMelhoria} onChange={(e) => setPM(e.target.value)} /></Field>
      <Btn type="submit" variant="accent"><Send size={15} />Registrar avaliação</Btn>
    </form>
  );
}
