function EmployeeProfile({ emp, pd, submissions, role, onRemove, assignOnboarding, toggleOnboardingTask, toggleTraining, setTrainingScore, toggleIntegrationItem, addLeaderEvaluation, setColaboradorStatus }) {
  const canEdit = role === "rh" || role === "cliente";
  const canEval = role === "rh" || role === "lideranca" || role === "cliente";
  const ethicsOk = submissions.ethicsAck.some((a) => a.colaboradorId === emp.id);
  const muvOk = submissions.muvAck.some((a) => a.colaboradorId === emp.id);
  const diagCount = submissions.diagnostico.filter((d) => d.colaboradorId === emp.id).length;
  const feedbacks = submissions.feedback.filter((f) => f.colaboradorId === emp.id);
  const evals = submissions.leaderEvaluations.filter((ev) => ev.colaboradorId === emp.id);
  const assignment = pd.onboardingAssignments[emp.id];
  const template = assignment && pd.onboardingTemplates.find((t) => t.id === assignment.templateId);
  const [pickTemplate, setPickTemplate] = useState("");
  const allTasks = template ? Object.values(template.tasks).flat() : [];
  const doneCount = allTasks.filter((t) => assignment?.progress?.[t.id]).length;
  const onbPct = allTasks.length ? Math.round((doneCount / allTasks.length) * 100) : 0;
  const kit = pd.integrationChecklist[emp.id] || {};
  const kitDone = INTEGRATION_KIT_ITEMS.filter((_, idx) => kit[idx]).length;
  const tc = pd.trainingCompletions[emp.id] || {};
  const trainingScores = Object.values(tc).map((v) => (v && typeof v === "object" ? v.score : null)).filter((v) => typeof v === "number");
  const avgTrainingScore = trainingScores.length ? Math.round(trainingScores.reduce((a, b) => a + b, 0) / trainingScores.length) : null;
  const evalAvg = evals.length ? +(evals.reduce((a, b) => a + b.media, 0) / evals.length).toFixed(2) : null;

  return (
    <SectionCard>
      <div className="flex justify-between items-start mb-4">
        <div><h3 className="f-display text-lg font-semibold" style={{ color: T.ink }}>{emp.nome}</h3><p className="text-xs" style={{ color: T.inkSoft }}>{emp.cargo}{emp.setor && ` · ${emp.setor}`}{emp.cpf && ` · CPF ${emp.cpf}`}{emp.dataAdmissao && ` · desde ${emp.dataAdmissao}`} · <span style={{ color: (emp.status || "Ativo") === "Ativo" ? T.success : T.danger }}>{emp.status || "Ativo"}</span></p></div>
        <div className="flex items-center gap-2">
          {canEdit && <Btn variant="ghost" onClick={() => setColaboradorStatus(emp.id, (emp.status || "Ativo") === "Ativo" ? "Desligado" : "Ativo")}>{(emp.status || "Ativo") === "Ativo" ? "Marcar desligamento" : "Reativar"}</Btn>}
          {canEdit && <button onClick={onRemove} style={{ color: T.danger }}><Trash2 size={16} /></button>}
        </div>
      </div>
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 mb-5">
        <MiniStat label="Código de Ética" value={ethicsOk ? "Aceito" : "Pendente"} ok={ethicsOk} />
        <MiniStat label="MUV" value={muvOk ? "Compreendido" : "Pendente"} ok={muvOk} />
        <MiniStat label="Média avaliações" value={evalAvg ?? "—"} />
        <MiniStat label="Média treinamentos" value={avgTrainingScore ?? "—"} />
      </div>

      <div className="mb-5">
        <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Kit de Integração ({kitDone}/{INTEGRATION_KIT_ITEMS.length})</div>
        <ProgressBar pct={Math.round((kitDone / INTEGRATION_KIT_ITEMS.length) * 100)} />
        <div className="space-y-1 mt-2">
          {INTEGRATION_KIT_ITEMS.map((label, idx) => (
            <button key={idx} disabled={!canEdit} onClick={() => toggleIntegrationItem(emp.id, idx)} className="w-full flex items-start gap-2 text-left text-sm py-1">
              {kit[idx] ? <CheckCircle2 size={14} style={{ color: T.success, marginTop: 2, flexShrink: 0 }} /> : <Circle size={14} style={{ color: T.inkSoft, marginTop: 2, flexShrink: 0 }} />}
              <span style={{ textDecoration: kit[idx] ? "line-through" : "none" }}>{label}</span>
            </button>
          ))}
        </div>
      </div>

      <div className="mb-5">
        <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Integração (Onboarding 30/60/90)</div>
        {!template ? (canEdit && (
          <div className="flex flex-wrap gap-2 items-end">
            <select className={inputCls} style={{ ...inputStyle, minWidth: 200 }} value={pickTemplate} onChange={(e) => setPickTemplate(e.target.value)}><option value="">Selecione um plano gerado...</option>{pd.onboardingTemplates.map((t) => <option key={t.id} value={t.id}>{t.cargo}</option>)}</select>
            <Btn variant="accent" disabled={!pickTemplate} onClick={() => assignOnboarding(emp.id, pickTemplate)}>Atribuir plano</Btn>
          </div>
        )) : (
          <div>
            <div className="flex justify-between text-sm mb-1"><span>{template.cargo}</span><span className="f-mono" style={{ color: T.cyan }}>{onbPct}%</span></div>
            <ProgressBar pct={onbPct} />
            <div className="grid sm:grid-cols-2 gap-2 mt-3">{Object.entries(template.tasks).map(([period, tasks]) => <div key={period}>{tasks.map((t) => (
              <button key={t.id} disabled={!canEdit} onClick={() => toggleOnboardingTask(emp.id, t.id)} className="w-full flex items-center gap-2 text-left text-sm py-1">
                {assignment.progress?.[t.id] ? <CheckCircle2 size={14} style={{ color: T.success }} /> : <Circle size={14} style={{ color: T.inkSoft }} />}
                <span style={{ textDecoration: assignment.progress?.[t.id] ? "line-through" : "none" }}>{t.text}</span>
              </button>
            ))}</div>)}</div>
          </div>
        )}
      </div>

      <div className="mb-5">
        <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Treinamentos</div>
        {pd.trainings.length === 0 ? <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhum treinamento cadastrado.</p> : (
          <div className="space-y-1.5">{pd.trainings.map((tr) => {
            const rec = tc[tr.id]; const done = rec && typeof rec === "object" ? rec.done : !!rec; const score = rec && typeof rec === "object" ? rec.score : null;
            return (
              <div key={tr.id} className="flex items-center gap-2 text-sm py-1">
                <button disabled={!canEval} onClick={() => toggleTraining(emp.id, tr.id)}>{done ? <CheckCircle2 size={14} style={{ color: T.success }} /> : <Circle size={14} style={{ color: T.inkSoft }} />}</button>
                <span className="flex-1" style={{ textDecoration: done ? "line-through" : "none" }}>{tr.titulo}</span>
                <span className="f-mono text-xs" style={{ color: T.inkSoft }}>{tr.tipo}</span>
                {canEval ? <input type="number" min="0" max="100" placeholder="nota" className="text-xs rounded px-1.5 py-0.5 border" style={{ width: 56, borderColor: T.line }} value={score ?? ""} onChange={(e) => setTrainingScore(emp.id, tr.id, e.target.value === "" ? null : Number(e.target.value))} />
                  : <span className="f-mono text-xs" style={{ color: T.cyan }}>{score ?? "—"}</span>}
              </div>
            );
          })}</div>
        )}
      </div>

      <div className="mb-5">
        <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Desempenho — avaliações de líderes</div>
        {evals.length === 0 ? <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhuma avaliação registrada ainda.</p> : (
          <>
            {evals.length > 1 && <div className="h-40 mb-2"><ResponsiveContainer width="100%" height="100%"><LineChart data={evals.map((ev) => ({ data: ev.date, media: ev.media }))}><CartesianGrid strokeDasharray="3 3" stroke={T.line} /><XAxis dataKey="data" tick={{ fontSize: 10 }} /><YAxis domain={[0, 5]} tick={{ fontSize: 10 }} /><Tooltip /><Line type="monotone" dataKey="media" stroke={T.cyan} strokeWidth={2} /></LineChart></ResponsiveContainer></div>}
            <div className="space-y-1.5 max-h-40 overflow-y-auto scrollbar-thin pr-1">{evals.slice().reverse().map((ev) => <div key={ev.id} className="text-xs px-2.5 py-1.5 rounded" style={{ background: T.paper }}><b>{ev.date}</b> · média {ev.media} · avaliadora: {ev.avaliadora}</div>)}</div>
          </>
        )}
        {canEval && <div className="mt-3"><LeaderEvalForm onSubmit={(item) => addLeaderEvaluation({ ...item, id: uid(), colaboradorId: emp.id, nome: emp.nome })} /></div>}
      </div>

      {feedbacks.length > 0 && (
        <div><div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Histórico de feedbacks</div>
          <div className="space-y-1.5">{feedbacks.map((f) => <div key={f.id} className="text-sm px-3 py-2 rounded-md" style={{ border: `1px solid ${T.line}` }}><span className="f-mono text-xs" style={{ color: T.inkSoft }}>{f.tipo} · {f.date}</span><p>{f.mensagem}</p></div>)}</div>
        </div>
      )}
    </SectionCard>
  );
}

