/* FECHAMENTO DE PRESTADORES (DP preenche · RH/Direção recebem)         */
/* ------------------------------------------------------------------ */
function DateTagInput({ label, dates, onAdd, onRemove, withQty, max }) {
  const [date, setDate] = useState(""), [qty, setQty] = useState("");
  const add = () => {
    if (!date) return;
    if (dates.some((d) => d.date === date)) return;
    onAdd({ date, qty: withQty ? qty : undefined });
    setDate(""); setQty("");
  };
  return (
    <div>
      <div className="flex flex-wrap gap-1.5 mb-2">
        {dates.map((d) => (
          <span key={d.date} className="text-xs f-mono px-2 py-1 rounded-full inline-flex items-center gap-1" style={{ background: T.cyanSoft, color: T.ink }}>
            {new Date(d.date + "T00:00:00").toLocaleDateString("pt-BR")}{withQty && d.qty ? ` · ${d.qty} idoso(s)` : ""}
            <button onClick={() => onRemove(d.date)} className="opacity-60 hover:opacity-100"><X size={11} /></button>
          </span>
        ))}
        {dates.length === 0 && <span className="text-xs italic" style={{ color: T.inkSoft }}>Nenhuma data adicionada.</span>}
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <input type="date" className={inputCls} style={{ ...inputStyle, maxWidth: 160 }} value={date} onChange={(e) => setDate(e.target.value)} />
        {withQty && <input type="number" min="0" placeholder="Nº idosos" className={inputCls} style={{ ...inputStyle, maxWidth: 110 }} value={qty} onChange={(e) => setQty(e.target.value)} />}
        <Btn type="button" variant="ghost" onClick={add}><Plus size={14} /></Btn>
        {max && <span className="text-xs f-mono" style={{ color: T.inkSoft }}>{dates.length}/{max} datas</span>}
      </div>
    </div>
  );
}

function FechamentoPrestadoresForm({ pd, onSave }) {
  const mk = currentMonthKey();
  const existing = pd.fechamentosPrestadores.find((f) => f.monthKey === mk);
  const [liderNome, setLiderNome] = useState(existing?.liderNome || "");
  const [medico, setMedico] = useState(existing?.medico || []);
  const [pedagoga, setPedagoga] = useState(existing?.pedagoga || []);
  const [musicoterapia, setMusicoterapia] = useState(existing?.musicoterapia || "");
  const [edufisico, setEdufisico] = useState(existing?.edufisico || []);
  const [saved, setSaved] = useState(false);

  const save = () => {
    const now = new Date();
    onSave({ id: existing?.id || uid(), monthKey: mk, liderNome, medico, pedagoga, musicoterapia, edufisico,
      dateEnvio: now.toLocaleDateString("pt-BR"), horaEnvio: now.toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" }) });
    setSaved(true); setTimeout(() => setSaved(false), 3000);
  };

  return (
    <div>
      <div className="text-xs p-2 rounded-md mb-4" style={{ background: T.cyanSoft, color: T.ink }}>⏰ Prazo de envio: até o dia 09 de cada mês. Referente a <b>{formatMonthLabel(mk)}</b> — uma visita por semana por prestador.</div>
      <Field label="Seu nome (líder/DP responsável)"><input className={inputCls} style={inputStyle} value={liderNome} onChange={(e) => setLiderNome(e.target.value)} /></Field>

      <SectionCard>
        <div className="text-sm font-semibold mb-1" style={{ color: T.ink }}>🩺 Acompanhamento Médico</div>
        <p className="text-xs mb-2" style={{ color: T.inkSoft }}>Adicione cada data de visita e o nº de idosos atendidos.</p>
        <DateTagInput dates={medico} onAdd={(d) => setMedico((m) => [...m, d])} onRemove={(date) => setMedico((m) => m.filter((x) => x.date !== date))} withQty max={5} />
      </SectionCard>

      <SectionCard>
        <div className="text-sm font-semibold mb-1" style={{ color: T.ink }}>📚 Pedagoga</div>
        <p className="text-xs mb-2" style={{ color: T.inkSoft }}>Datas de presença (uma por semana).</p>
        <DateTagInput dates={pedagoga} onAdd={(d) => setPedagoga((m) => [...m, d])} onRemove={(date) => setPedagoga((m) => m.filter((x) => x.date !== date))} max={5} />
      </SectionCard>

      <SectionCard>
        <div className="text-sm font-semibold mb-1" style={{ color: T.ink }}>🎵 Musicoterapia</div>
        <Field label="Observação de ausência (opcional)"><textarea className={inputCls} style={{ ...inputStyle, minHeight: 70 }} placeholder="Ex: Ausente nos dias 10 e 17 por motivo..." value={musicoterapia} onChange={(e) => setMusicoterapia(e.target.value)} /></Field>
      </SectionCard>

      <SectionCard>
        <div className="text-sm font-semibold mb-1" style={{ color: T.ink }}>🏋️ Educador Físico</div>
        <p className="text-xs mb-2" style={{ color: T.inkSoft }}>Datas de presença (uma por semana).</p>
        <DateTagInput dates={edufisico} onAdd={(d) => setEdufisico((m) => [...m, d])} onRemove={(date) => setEdufisico((m) => m.filter((x) => x.date !== date))} max={5} />
      </SectionCard>

      <div className="flex items-center gap-3">
        <Btn variant="accent" onClick={save}>💾 Salvar Fechamento Mensal</Btn>
        {saved && <span className="text-sm" style={{ color: T.success }}>✅ Salvo com sucesso!</span>}
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* PROGRAMA DIU VINTÉM (moedas de reconhecimento → prêmios)             */
/* ------------------------------------------------------------------ */
const DIU_VINTEM_CRITERIOS = [
  { id: "assiduidade", label: "Destaque em assiduidade e pontualidade no período avaliado", pontos: 4 },
  { id: "proatividade", label: "Proatividade — ajuda além da função quando necessário", pontos: 5 },
  { id: "zelo", label: "Zelo pelo patrimônio (equipamentos, mobiliário, insumos)", pontos: 4 },
  { id: "epi", label: "Uso correto e constante do uniforme e dos EPIs", pontos: 3 },
  { id: "elogio", label: "Elogio espontâneo recebido de residente ou familiar", pontos: 2 },
  { id: "disciplina", label: "Zero ocorrências disciplinares formais no período", pontos: 2 },
  { id: "treinamentos", label: "Participação ativa em capacitações e treinamentos", pontos: 3 },
  { id: "equipe", label: "Colaboração e bom relacionamento em equipe", pontos: 4 },
  { id: "sugestao", label: "Sugestão de melhoria apresentada e efetivamente implementada", pontos: 2 },
  { id: "iniciativa", label: "Iniciativa de destaque em emergência ou imprevisto", pontos: 3 },
  { id: "manual", label: "Seguimento fiel e de destaque do Manual de Conduta e Regimento Interno", pontos: 3 },
];
const DIU_VINTEM_CARGOS_EXCLUIDOS = ["Enfermeira", "Supervisor Geral"];
function diuVintemElegivel(colaborador) { return !DIU_VINTEM_CARGOS_EXCLUIDOS.includes(colaborador.cargo); }
function diuVintemExpirado(dateBR) {
  const d = parseBR(dateBR); if (!d) return false;
  const venc = new Date(d); venc.setMonth(venc.getMonth() + 6);
  return new Date() > venc;
}
function diuVintemVencimento(dateBR) {
  const d = parseBR(dateBR); if (!d) return "";
  const venc = new Date(d); venc.setMonth(venc.getMonth() + 6);
  return venc.toLocaleDateString("pt-BR");
}
function diuVintemSaldo(colaboradorId, colaboradores, lancamentos, resgates) {
  const c = colaboradores.find((x) => x.id === colaboradorId);
  if (!c || c.status === "Desligado") return 0;
  const ganhos = lancamentos.filter((l) => l.colaboradorId === colaboradorId && !diuVintemExpirado(l.date)).reduce((a, l) => a + l.totalPontos, 0);
  const gastos = resgates.filter((r) => r.colaboradorId === colaboradorId).reduce((a, r) => a + r.pontosResgatados, 0);
  return Math.max(0, ganhos - gastos);
}
function CoinIcon({ size = 18 }) { return <img src={DIU_VINTEM_COIN} alt="Diu Vintém" style={{ width: size, height: size, display: "inline-block", verticalAlign: -4 }} />; }

function DiuVintemLancamentoForm({ colaboradores, onSubmit }) {
  const elegiveis = colaboradores.filter((c) => (c.status || "Ativo") === "Ativo" && diuVintemElegivel(c));
  const [colaboradorId, setColaboradorId] = useState("");
  const [sel, setSel] = useState([]);
  const [responsavel, setResponsavel] = useState("");
  const [sent, setSent] = useState(false);
  const toggle = (id) => setSel((s) => (s.includes(id) ? s.filter((x) => x !== id) : [...s, id]));
  const total = sel.reduce((a, id) => a + DIU_VINTEM_CRITERIOS.find((c) => c.id === id).pontos, 0);
  const submit = (e) => {
    e.preventDefault();
    if (!colaboradorId || sel.length === 0) return;
    const c = colaboradores.find((x) => x.id === colaboradorId);
    onSubmit({ id: uid(), colaboradorId, nome: c.nome, monthKey: currentMonthKey(), criterios: sel.map((id) => { const cr = DIU_VINTEM_CRITERIOS.find((x) => x.id === id); return { criterio: cr.label, pontos: cr.pontos }; }), totalPontos: total, responsavel, date: new Date().toLocaleDateString("pt-BR") });
    setColaboradorId(""); setSel([]); setResponsavel(""); setSent(true); setTimeout(() => setSent(false), 3000);
  };
  return (
    <form onSubmit={submit}>
      <div className="text-xs p-2.5 rounded-md mb-3 flex gap-2" style={{ background: T.amberSoft, color: T.ink }}>
        <span>⚠️</span>
        <span><b>Atenção:</b> este programa reconhece <b>desempenho de destaque</b>, acima da média esperada — não é sobre simplesmente cumprir a função básica do cargo. Marque apenas os critérios em que o colaborador realmente se destacou no período.</span>
      </div>
      <div className="grid sm:grid-cols-2 gap-3">
        <Field label="Colaborador"><select required className={inputCls} style={inputStyle} value={colaboradorId} onChange={(e) => setColaboradorId(e.target.value)}><option value="">Selecione...</option>{elegiveis.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></Field>
        <Field label="Responsável pelo lançamento"><input required className={inputCls} style={inputStyle} value={responsavel} onChange={(e) => setResponsavel(e.target.value)} /></Field>
      </div>
      <Field label={`Critérios do mês (${formatMonthLabel(currentMonthKey())})`}>
        <div className="space-y-1.5">
          {DIU_VINTEM_CRITERIOS.map((c) => (
            <button key={c.id} type="button" onClick={() => toggle(c.id)} className="w-full flex items-center justify-between gap-2 text-left px-3 py-2 rounded-md" style={{ border: `1px solid ${sel.includes(c.id) ? T.cyan : T.line}`, background: sel.includes(c.id) ? T.cyanSoft : "transparent" }}>
              <span className="text-sm flex items-center gap-2">{sel.includes(c.id) ? <CheckCircle2 size={15} style={{ color: T.cyan }} /> : <Circle size={15} style={{ color: T.inkSoft }} />}{c.label}</span>
              <span className="f-mono text-xs shrink-0 flex items-center gap-1" style={{ color: T.cyan }}>+{c.pontos} <CoinIcon size={16} /></span>
            </button>
          ))}
        </div>
      </Field>
      <div className="flex items-center justify-between mb-3"><span className="text-sm" style={{ color: T.inkSoft }}>Total do lançamento:</span><span className="f-display text-xl font-semibold flex items-center gap-1.5" style={{ color: T.ink }}>{total} <CoinIcon size={20} /></span></div>
      <Btn type="submit" variant="accent" disabled={!colaboradorId || sel.length === 0}>💾 Registrar Diu Vintém</Btn>
      {sent && <span className="text-sm ml-3" style={{ color: T.success }}>✅ Registrado!</span>}
    </form>
  );
}

function DiuVintemResgateForm({ colaboradores, lancamentos, resgates, onSubmit }) {
  const elegiveis = colaboradores.filter((c) => (c.status || "Ativo") === "Ativo" && diuVintemElegivel(c));
  const [colaboradorId, setColaboradorId] = useState(""), [pontos, setPontos] = useState(""), [premio, setPremio] = useState(""), [responsavel, setResponsavel] = useState("");
  const saldo = colaboradorId ? diuVintemSaldo(colaboradorId, colaboradores, lancamentos, resgates) : 0;
  const submit = (e) => {
    e.preventDefault();
    const p = Number(pontos);
    if (!colaboradorId || !(p > 0) || p > saldo) return;
    const c = colaboradores.find((x) => x.id === colaboradorId);
    onSubmit({ id: uid(), colaboradorId, nome: c.nome, pontosResgatados: p, premio, responsavel, date: new Date().toLocaleDateString("pt-BR") });
    setColaboradorId(""); setPontos(""); setPremio(""); setResponsavel("");
  };
  return (
    <form onSubmit={submit}>
      <p className="text-xs mb-3" style={{ color: T.inkSoft }}>Não há mais tabela fixa de prêmios — a lista é divulgada próximo da confraternização semestral. Registre aqui o prêmio efetivamente entregue. Premiação em dinheiro não é permitida.</p>
      <div className="grid sm:grid-cols-2 gap-3">
        <Field label="Colaborador"><select required className={inputCls} style={inputStyle} value={colaboradorId} onChange={(e) => setColaboradorId(e.target.value)}><option value="">Selecione...</option>{elegiveis.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></Field>
        <Field label="Responsável"><input className={inputCls} style={inputStyle} value={responsavel} onChange={(e) => setResponsavel(e.target.value)} /></Field>
      </div>
      {colaboradorId && <p className="text-xs mb-2 flex items-center gap-1" style={{ color: T.inkSoft }}>Saldo disponível: <b style={{ color: T.ink }}>{saldo}</b> <CoinIcon size={14} /></p>}
      <div className="grid sm:grid-cols-2 gap-3">
        <Field label="Pontos a resgatar"><input required type="number" min="1" max={saldo || undefined} className={inputCls} style={inputStyle} value={pontos} onChange={(e) => setPontos(e.target.value)} /></Field>
        <Field label="Prêmio entregue"><input required className={inputCls} style={inputStyle} placeholder="Ex: vale-presente, folga premiada..." value={premio} onChange={(e) => setPremio(e.target.value)} /></Field>
      </div>
      <Btn type="submit" variant="accent" disabled={!colaboradorId || !pontos || Number(pontos) > saldo}>🎁 Registrar resgate</Btn>
    </form>
  );
}

function DiuVintemRHPage({ pd, lancamentos, resgates, onAddLancamento, onAddResgate, onDeleteLancamento }) {
  const [expandId, setExpandId] = useState(null);
  const ranking = pd.colaboradores.filter(diuVintemElegivel).map((c) => ({ c, saldo: diuVintemSaldo(c.id, pd.colaboradores, lancamentos, resgates) })).sort((a, b) => b.saldo - a.saldo);
  return (
    <div>
      <div className="mb-6 flex items-center gap-3"><CoinIcon size={40} /><div><div className="text-xs f-mono uppercase tracking-wide mb-1" style={{ color: T.cyan }}>Programa de Reconhecimento</div><h1 className="f-display text-2xl font-semibold" style={{ color: T.ink }}>Diu Vintém</h1></div></div>
      <div className="text-xs p-2.5 rounded-md mb-4" style={{ background: T.cyanSoft, color: T.ink }}>Não participam: <b>Enfermeiros, Supervisor Geral e Gestores de RH</b> (regulamento item 5). Sem tabela fixa de resgate — a lista de prêmios é divulgada perto da confraternização semestral, nunca em dinheiro.</div>
      <SectionCard><div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Lançar pontos do mês</div><DiuVintemLancamentoForm colaboradores={pd.colaboradores} onSubmit={onAddLancamento} /></SectionCard>
      <SectionCard><div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Registrar resgate de prêmio</div><DiuVintemResgateForm colaboradores={pd.colaboradores} lancamentos={lancamentos} resgates={resgates} onSubmit={onAddResgate} /></SectionCard>
      <SectionCard>
        <div className="text-xs f-mono uppercase tracking-wide mb-3" style={{ color: T.cyan }}>Saldo por colaborador</div>
        <div className="space-y-1.5">
          {ranking.map(({ c, saldo }) => {
            const meusLancamentos = lancamentos.filter((l) => l.colaboradorId === c.id);
            const meusResgates = resgates.filter((r) => r.colaboradorId === c.id);
            const open = expandId === c.id;
            return (
              <div key={c.id} className="rounded-lg" style={{ border: `1px solid ${T.line}` }}>
                <button onClick={() => setExpandId(open ? null : c.id)} className="w-full flex items-center justify-between gap-2 px-3 py-2.5 text-left">
                  <span className="text-sm font-medium" style={{ color: T.ink }}>{c.nome} <span style={{ color: T.inkSoft, fontWeight: 400 }}>· {c.cargo}{c.status === "Desligado" && " · Desligado"}</span></span>
                  <span className="f-mono text-sm font-semibold shrink-0 flex items-center gap-1" style={{ color: c.status === "Desligado" ? T.inkSoft : T.cyan }}>{saldo} <CoinIcon size={16} /></span>
                </button>
                {open && (
                  <div className="px-3 pb-3">
                    {c.status === "Desligado" && <p className="text-xs mb-2" style={{ color: T.danger }}>Colaborador desligado — moedas desclassificadas conforme regulamento (item 5).</p>}
                    <div className="text-xs f-mono uppercase mb-1" style={{ color: T.inkSoft }}>Lançamentos</div>
                    {meusLancamentos.length === 0 ? <p className="text-xs italic mb-2" style={{ color: T.inkSoft }}>Nenhum lançamento.</p> : meusLancamentos.slice().reverse().map((l) => (
                      <div key={l.id} className="flex items-center justify-between text-xs px-2 py-1.5 rounded mb-1" style={{ background: diuVintemExpirado(l.date) ? T.danger + "11" : T.paper }}>
                        <span>{l.date} · +{l.totalPontos} 🪙 · {l.criterios.length} critério(s) · por {l.responsavel || "—"}{diuVintemExpirado(l.date) && <span style={{ color: T.danger }}> (expirado)</span>}</span>
                        <button onClick={() => onDeleteLancamento(l.id)} style={{ color: T.danger }}><Trash2 size={12} /></button>
                      </div>
                    ))}
                    {meusResgates.length > 0 && <><div className="text-xs f-mono uppercase mb-1 mt-2" style={{ color: T.inkSoft }}>Resgates</div>{meusResgates.slice().reverse().map((r) => <div key={r.id} className="text-xs px-2 py-1.5 rounded mb-1" style={{ background: T.successSoft }}>{r.date} · -{r.pontosResgatados} 🪙 · {r.premio}</div>)}</>}
                  </div>
                )}
              </div>
            );
          })}
          {ranking.length === 0 && <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhum colaborador elegível cadastrado.</p>}
        </div>
      </SectionCard>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* PLANO ODONTOLÓGICO (colaborador solicita · DP/RH/Direção recebem)   */
/* ------------------------------------------------------------------ */
const UF_LIST = ["SP", "AC", "AL", "AP", "AM", "BA", "CE", "DF", "ES", "GO", "MA", "MT", "MS", "MG", "PA", "PB", "PR", "PE", "PI", "RJ", "RN", "RS", "RO", "RR", "SC", "SE", "TO"];
function formatCEP(v) { v = v.replace(/\D/g, "").slice(0, 8); return v.length > 5 ? v.replace(/(\d{5})(\d{1,3})/, "$1-$2") : v; }
function formatCelular(v) { v = v.replace(/\D/g, "").slice(0, 11); if (v.length > 6) return v.replace(/(\d{2})(\d{5})(\d{0,4})/, "($1) $2-$3").replace(/-$/, ""); if (v.length > 2) return v.replace(/(\d{2})(\d{0,5})/, "($1) $2"); return v; }
function formatCNS(v) { v = v.replace(/\D/g, "").slice(0, 15); return v.replace(/(\d{3})(\d{4})?(\d{4})?(\d{4})?/, (m, a, b, c, d) => [a, b, c, d].filter(Boolean).join(" ")); }

function OdontoForm({ colaboradores, defaultId, list, onSubmit }) {
  const empDefault = colaboradores.find((c) => c.id === defaultId);
  const [colaboradorId, setColaboradorId] = useState(defaultId || "");
  const [f, setF] = useState({ nome: empDefault?.nome || "", cpf: "", rg: "", dataNascimento: "", sexo: "", estadoCivil: "", nomeMae: "", cep: "", logradouro: "", numero: "", complemento: "", bairro: "", cidade: "", uf: "", celular: "", email: "", dataAdmissao: empDefault?.dataAdmissao || "", cns: "" });
  const [sent, setSent] = useState(false);
  const set = (k) => (e) => setF((s) => ({ ...s, [k]: e.target.value }));
  const mine = list.filter((o) => (colaboradorId ? o.colaboradorId === colaboradorId : o.nome === f.nome));

  const buscarCEP = async () => {
    const cep = f.cep.replace(/\D/g, "");
    if (cep.length !== 8) return;
    try {
      const r = await fetch(`https://viacep.com.br/ws/${cep}/json/`);
      const d = await r.json();
      if (!d.erro) setF((s) => ({ ...s, logradouro: d.logradouro || s.logradouro, bairro: d.bairro || s.bairro, cidade: d.localidade || s.cidade, uf: d.uf || s.uf }));
    } catch {}
  };

  const submit = (e) => {
    e.preventDefault();
    const cpfNum = f.cpf.replace(/\D/g, "");
    if (cpfNum.length !== 11) return;
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(f.email)) return;
    const now = new Date();
    onSubmit({ id: uid(), colaboradorId: colaboradorId || null, ...f, monthKey: now.toISOString().slice(0, 7), dateEnvio: now.toLocaleDateString("pt-BR"), horaEnvio: now.toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" }), status: "pendente" });
    setSent(true);
  };

  return (
    <div>
      {sent ? (
        <div className="mb-5"><Confirm text="Cadastro enviado! O RH incluirá você no plano odontológico." /><Btn variant="ghost" className="mt-2" onClick={() => setSent(false)}>Enviar outro cadastro</Btn></div>
      ) : (
        <form onSubmit={submit} className="mb-5">
          <div className="text-xs p-2 rounded-md mb-4" style={{ background: T.cyanSoft, color: T.ink }}>🦷 Preencha com atenção. Seus dados serão enviados ao RH para inclusão no plano.</div>
          {colaboradores.length > 0 && (
            <Field label="Selecione seu nome"><select className={inputCls} style={inputStyle} value={colaboradorId} onChange={(e) => { setColaboradorId(e.target.value); const c = colaboradores.find((x) => x.id === e.target.value); if (c) setF((s) => ({ ...s, nome: c.nome, dataAdmissao: c.dataAdmissao || s.dataAdmissao })); }}><option value="">Prefiro digitar manualmente</option>{colaboradores.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></Field>
          )}
          <div className="text-sm font-semibold mb-2" style={{ color: T.ink }}>📋 Dados Pessoais</div>
          <div className="grid sm:grid-cols-2 gap-3">
            <Field label="Nome completo"><input required className={inputCls} style={inputStyle} value={f.nome} onChange={set("nome")} /></Field>
            <Field label="CPF"><input required className={inputCls} style={inputStyle} placeholder="000.000.000-00" maxLength={14} value={f.cpf} onChange={(e) => setF((s) => ({ ...s, cpf: formatCPF(e.target.value) }))} /></Field>
          </div>
          <div className="grid sm:grid-cols-2 gap-3">
            <Field label="RG"><input required className={inputCls} style={inputStyle} value={f.rg} onChange={set("rg")} /></Field>
            <Field label="Data de nascimento"><input required type="date" className={inputCls} style={inputStyle} value={f.dataNascimento} onChange={set("dataNascimento")} /></Field>
          </div>
          <div className="grid sm:grid-cols-2 gap-3">
            <Field label="Sexo"><select required className={inputCls} style={inputStyle} value={f.sexo} onChange={set("sexo")}><option value="">Selecione</option><option value="m">Masculino</option><option value="f">Feminino</option></select></Field>
            <Field label="Estado civil"><select required className={inputCls} style={inputStyle} value={f.estadoCivil} onChange={set("estadoCivil")}><option value="">Selecione</option><option value="s">Solteiro(a)</option><option value="c">Casado(a)</option><option value="d">Divorciado(a)</option><option value="v">Viúvo(a)</option><option value="u">União Estável</option></select></Field>
          </div>
          <Field label="Nome da mãe"><input required className={inputCls} style={inputStyle} value={f.nomeMae} onChange={set("nomeMae")} /></Field>

          <div className="text-sm font-semibold mb-2 mt-4" style={{ color: T.ink }}>🏠 Endereço</div>
          <div className="grid sm:grid-cols-2 gap-3">
            <Field label="CEP"><input required className={inputCls} style={inputStyle} placeholder="00000-000" maxLength={9} value={f.cep} onChange={(e) => setF((s) => ({ ...s, cep: formatCEP(e.target.value) }))} onBlur={buscarCEP} /></Field>
            <Field label="Logradouro"><input required className={inputCls} style={inputStyle} value={f.logradouro} onChange={set("logradouro")} /></Field>
          </div>
          <div className="grid sm:grid-cols-2 gap-3">
            <Field label="Número"><input required className={inputCls} style={inputStyle} value={f.numero} onChange={set("numero")} /></Field>
            <Field label="Complemento"><input className={inputCls} style={inputStyle} value={f.complemento} onChange={set("complemento")} /></Field>
          </div>
          <div className="grid sm:grid-cols-2 gap-3">
            <Field label="Bairro"><input required className={inputCls} style={inputStyle} value={f.bairro} onChange={set("bairro")} /></Field>
            <Field label="Cidade"><input required className={inputCls} style={inputStyle} value={f.cidade} onChange={set("cidade")} /></Field>
          </div>
          <Field label="UF"><select required className={inputCls} style={inputStyle} value={f.uf} onChange={set("uf")}><option value="">Selecione</option>{UF_LIST.map((u) => <option key={u}>{u}</option>)}</select></Field>

          <div className="text-sm font-semibold mb-2 mt-4" style={{ color: T.ink }}>📱 Contato</div>
          <div className="grid sm:grid-cols-2 gap-3">
            <Field label="Celular (WhatsApp)"><input required className={inputCls} style={inputStyle} placeholder="(00) 00000-0000" value={f.celular} onChange={(e) => setF((s) => ({ ...s, celular: formatCelular(e.target.value) }))} /></Field>
            <Field label="E-mail"><input required type="email" className={inputCls} style={inputStyle} value={f.email} onChange={set("email")} /></Field>
          </div>

          <div className="text-sm font-semibold mb-2 mt-4" style={{ color: T.ink }}>💼 Dados Profissionais</div>
          <Field label="Data de admissão"><input required type="date" className={inputCls} style={inputStyle} value={f.dataAdmissao} onChange={set("dataAdmissao")} /></Field>
          <Field label="Cartão Nacional de Saúde — CNS (opcional)"><input className={inputCls} style={inputStyle} placeholder="000 0000 0000 0000" maxLength={18} value={f.cns} onChange={(e) => setF((s) => ({ ...s, cns: formatCNS(e.target.value) }))} /></Field>

          <Btn type="submit" variant="accent" className="w-full justify-center">✅ Confirmar Cadastro</Btn>
        </form>
      )}
      <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Meus cadastros</div>
      {mine.length === 0 ? <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhum cadastro enviado ainda.</p> : mine.slice().reverse().map((o) => (
        <div key={o.id} className="flex items-center justify-between text-sm px-3 py-2 rounded-md mb-1.5" style={{ border: `1px solid ${T.line}` }}>
          <span>Enviado em {o.dateEnvio}</span>
          <span className="text-xs f-mono px-2 py-0.5 rounded-full" style={{ background: o.status === "processado" ? T.successSoft : T.amberSoft, color: o.status === "processado" ? T.success : T.amber }}>{o.status === "processado" ? "Processado" : "Pendente"}</span>
        </div>
      ))}
    </div>
  );
}

function OdontoRHPage({ pd, list, onMark, onDelete, onSetCorretor }) {
  const [statusF, setStatusF] = useState(""), [busca, setBusca] = useState("");
  const [openId, setOpenId] = useState(null);
  const [corretor, setCorretor] = useState(pd.odontoCorretorWhatsapp || "");
  let filtered = list;
  if (statusF) filtered = filtered.filter((o) => o.status === statusF);
  if (busca) filtered = filtered.filter((o) => o.nome.toLowerCase().includes(busca.toLowerCase()));
  filtered = filtered.slice().reverse();
  const pendentes = list.filter((o) => o.status === "pendente");
  const open = list.find((o) => o.id === openId);

  const exportarPlanilha = () => {
    const rows = list.map((o) => ({
      Nome: o.nome, CPF: o.cpf, RG: o.rg, "Data Nascimento": o.dataNascimento, Sexo: o.sexo === "m" ? "Masculino" : "Feminino",
      "Estado Civil": o.estadoCivil, "Nome da Mãe": o.nomeMae, CEP: o.cep, Logradouro: o.logradouro, Número: o.numero,
      Complemento: o.complemento, Bairro: o.bairro, Cidade: o.cidade, UF: o.uf, Celular: o.celular, "E-mail": o.email,
      "Data Admissão": o.dataAdmissao, CNS: o.cns, Status: o.status, "Enviado em": o.dateEnvio,
    }));
    const ws = XLSX.utils.json_to_sheet(rows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Plano Odontológico");
    XLSX.writeFile(wb, `plano-odontologico-${currentMonthKey()}.xlsx`);
  };

  const enviarWhatsapp = () => {
    const phone = corretor.replace(/\D/g, "");
    const texto = `Olá! Segue solicitação de inclusão no plano odontológico:\n\n${pendentes.length} colaborador(es) pendente(s):\n${pendentes.map((o) => `• ${o.nome} — CPF ${o.cpf}`).join("\n")}\n\nA planilha completa foi exportada em separado — favor anexar manualmente.`;
    window.open(`https://wa.me/${phone}?text=${encodeURIComponent(texto)}`, "_blank");
  };

  return (
    <div>
      <div className="mb-4"><div className="text-xs f-mono uppercase tracking-wide mb-1" style={{ color: T.cyan }}>DP · RH · Direção</div><h1 className="f-display text-2xl font-semibold" style={{ color: T.ink }}>🦷 Plano Odontológico</h1></div>
      <div className="grid grid-cols-3 gap-3 mb-4">
        {[["Total", list.length], ["Pendentes", pendentes.length], ["Processados", list.filter((o) => o.status === "processado").length]].map(([l, v]) => (
          <div key={l} className="rounded-lg p-3" style={{ border: `1px solid ${T.line}`, background: T.paperRaised }}><div className="f-display text-lg font-semibold" style={{ color: T.ink }}>{v}</div><div className="text-xs" style={{ color: T.inkSoft }}>{l}</div></div>
        ))}
      </div>
      <SectionCard>
        <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Enviar ao corretor</div>
        <div className="flex flex-wrap gap-2 items-end mb-2">
          <div className="flex-1" style={{ minWidth: 180 }}><Field label="WhatsApp do corretor"><input className={inputCls} style={inputStyle} placeholder="(00) 00000-0000" value={corretor} onChange={(e) => setCorretor(e.target.value)} onBlur={() => onSetCorretor(corretor)} /></Field></div>
          <Btn variant="accent" onClick={enviarWhatsapp}>📤 Enviar ao Corretor</Btn>
          <Btn variant="ghost" onClick={exportarPlanilha}>📥 Baixar Planilha Excel</Btn>
        </div>
        <p className="text-xs" style={{ color: T.inkSoft }}>O WhatsApp abre com um resumo em texto — anexe a planilha baixada manualmente (não é possível anexar arquivos automaticamente pelo link).</p>
      </SectionCard>
      <div className="flex flex-wrap gap-2 items-end mb-4">
        <Field label="Status"><select className={inputCls} style={inputStyle} value={statusF} onChange={(e) => setStatusF(e.target.value)}><option value="">Todos</option><option value="pendente">Pendentes</option><option value="processado">Processados</option></select></Field>
        <Field label="Buscar por nome"><input className={inputCls} style={inputStyle} value={busca} onChange={(e) => setBusca(e.target.value)} /></Field>
      </div>
      {open && (
        <SectionCard>
          <div className="flex justify-between items-center mb-3"><h3 className="f-display text-lg font-semibold" style={{ color: T.ink }}>{open.nome}</h3><button onClick={() => setOpenId(null)} className="text-xs f-mono" style={{ color: T.inkSoft }}>Fechar ✕</button></div>
          <div className="grid sm:grid-cols-2 gap-2 text-sm mb-3">
            {[["CPF", open.cpf], ["RG", open.rg], ["Nascimento", open.dataNascimento], ["Sexo", open.sexo === "m" ? "Masculino" : "Feminino"], ["Estado Civil", open.estadoCivil], ["Nome da Mãe", open.nomeMae],
              ["Endereço", `${open.logradouro}, ${open.numero} ${open.complemento || ""}`], ["Bairro/Cidade", `${open.bairro} — ${open.cidade}/${open.uf}`], ["CEP", open.cep],
              ["Celular", open.celular], ["E-mail", open.email], ["Admissão", open.dataAdmissao], ["CNS", open.cns || "—"]].map(([l, v]) => (
              <div key={l}><span style={{ color: T.inkSoft }}>{l}:</span> <b style={{ color: T.ink }}>{v}</b></div>
            ))}
          </div>
          <div className="flex gap-2">
            {open.status === "pendente" && <Btn variant="accent" onClick={() => onMark(open.id, "processado")}>Marcar como processado</Btn>}
            <Btn variant="danger" onClick={() => { onDelete(open.id); setOpenId(null); }}>Excluir</Btn>
          </div>
        </SectionCard>
      )}
      {filtered.length === 0 ? <SectionCard><p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhum cadastro encontrado.</p></SectionCard> : filtered.map((o) => (
        <button key={o.id} onClick={() => setOpenId(o.id === openId ? null : o.id)} className="w-full text-left rounded-lg p-3 mb-2 flex items-center justify-between gap-2" style={{ border: `1px solid ${T.line}`, background: T.paperRaised }}>
          <div><div className="text-sm font-medium" style={{ color: T.ink }}>{o.nome}</div><div className="text-xs" style={{ color: T.inkSoft }}>CPF {o.cpf} · enviado {o.dateEnvio}</div></div>
          <span className="text-xs f-mono px-2 py-0.5 rounded-full shrink-0" style={{ background: o.status === "processado" ? T.successSoft : T.amberSoft, color: o.status === "processado" ? T.success : T.amber }}>{o.status === "processado" ? "Processado" : "Pendente"}</span>
        </button>
      ))}
    </div>
  );
}

function DiuVintemColaborador({ pd, lancamentos, resgates, myColaboradorId }) {
  const emp = pd.colaboradores.find((c) => c.id === myColaboradorId);
  if (!emp) return <p className="text-sm italic" style={{ color: T.inkSoft }}>Entre selecionando seu nome para ver seu saldo.</p>;
  if (!diuVintemElegivel(emp)) return <p className="text-sm italic" style={{ color: T.inkSoft }}>Este programa não se aplica ao seu cargo (Enfermeiros, Supervisor Geral e Gestores de RH não participam, conforme regulamento).</p>;
  const saldo = diuVintemSaldo(emp.id, pd.colaboradores, lancamentos, resgates);
  const meus = lancamentos.filter((l) => l.colaboradorId === emp.id).slice().reverse();
  const meusResgates = resgates.filter((r) => r.colaboradorId === emp.id).slice().reverse();
  return (
    <div>
      <div className="rounded-xl p-5 mb-4 text-center" style={{ background: T.cyanSoft }}>
        <CoinIcon size={56} />
        <div className="text-xs f-mono uppercase tracking-wide mt-2 mb-1" style={{ color: T.cyan }}>Seu saldo atual</div>
        <div className="f-display text-4xl font-semibold" style={{ color: T.ink }}>{saldo}</div>
      </div>
      <div className="text-xs p-2.5 rounded-md mb-4" style={{ background: T.amberSoft, color: T.ink }}>🏆 O Diu Vintém reconhece quem se <b>destaca acima da média esperada</b> — não é dado automaticamente por cumprir as tarefas básicas do cargo. É um prêmio pra quem vai além.</div>
      <SectionCard>
        <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Como funciona</div>
        <ul className="text-sm space-y-1" style={{ color: T.inkSoft }}>
          <li>• As moedas são um reconhecimento simbólico — não têm natureza salarial.</li>
          <li>• Válidas por 2 trimestres (6 meses) a partir do lançamento.</li>
          <li>• Não podem ser vendidas, cedidas ou trocadas entre colaboradores.</li>
          <li>• Trocas por prêmios ocorrem em confraternizações semestrais — a lista de prêmios é divulgada perto do evento, nunca em dinheiro.</li>
          <li>• Em caso de desligamento, as moedas acumuladas são desclassificadas.</li>
          <li>• Não participam: Enfermeiros, Supervisor Geral e Gestores de RH.</li>
        </ul>
      </SectionCard>
      <SectionCard>
        <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Seu histórico</div>
        {meus.length === 0 && meusResgates.length === 0 ? <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhum lançamento ainda.</p> : (
          <div className="space-y-1.5">
            {meus.map((l) => (
              <div key={l.id} className="text-xs px-3 py-2 rounded-md" style={{ border: `1px solid ${T.line}` }}>
                <div className="flex justify-between mb-1"><span className="f-mono" style={{ color: T.cyan }}>+{l.totalPontos} 🪙</span><span style={{ color: T.inkSoft }}>{l.date}{diuVintemExpirado(l.date) ? " · expirado" : ` · válido até ${diuVintemVencimento(l.date)}`}</span></div>
                {l.criterios.map((c, i) => <div key={i} style={{ color: T.ink }}>• {c.criterio}</div>)}
              </div>
            ))}
            {meusResgates.map((r) => <div key={r.id} className="text-xs px-3 py-2 rounded-md" style={{ background: T.successSoft }}>-{r.pontosResgatados} 🪙 · {r.premio} · {r.date}</div>)}
          </div>
        )}
      </SectionCard>
    </div>
  );
}

function FechamentoPrestadoresRHPage({ pd }) {
  const list = pd.fechamentosPrestadores.slice().sort((a, b) => b.monthKey.localeCompare(a.monthKey));
  return (
    <div>
      <div className="mb-6"><div className="text-xs f-mono uppercase tracking-wide mb-1" style={{ color: T.cyan }}>DP</div><h1 className="f-display text-2xl font-semibold" style={{ color: T.ink }}>Fechamento de Prestadores</h1></div>
      {list.length === 0 ? <SectionCard><p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhum fechamento enviado ainda.</p></SectionCard> : list.map((f) => {
        const totalIdosos = f.medico.reduce((a, m) => a + (Number(m.qty) || 0), 0);
        return (
          <SectionCard key={f.id}>
            <div className="flex flex-wrap items-center justify-between gap-2 mb-3">
              <h3 className="f-display text-lg font-semibold" style={{ color: T.ink }}>{formatMonthLabel(f.monthKey)}</h3>
              <span className="text-xs f-mono" style={{ color: T.inkSoft }}>Enviado por {f.liderNome || "—"} em {f.dateEnvio} às {f.horaEnvio}</span>
            </div>
            <div className="grid sm:grid-cols-2 gap-3">
              <div className="rounded-lg p-3" style={{ background: T.paper }}>
                <div className="text-xs f-mono uppercase mb-1" style={{ color: T.cyan }}>🩺 Médico ({f.medico.length} visita(s) · {totalIdosos} atendimento(s))</div>
                {f.medico.map((m) => <div key={m.date} className="text-sm">{new Date(m.date + "T00:00:00").toLocaleDateString("pt-BR")} — {m.qty || 0} idoso(s)</div>)}
                {f.medico.length === 0 && <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhuma visita registrada.</p>}
              </div>
              <div className="rounded-lg p-3" style={{ background: T.paper }}>
                <div className="text-xs f-mono uppercase mb-1" style={{ color: T.cyan }}>📚 Pedagoga ({f.pedagoga.length} dia(s))</div>
                {f.pedagoga.map((d) => <div key={d.date} className="text-sm">{new Date(d.date + "T00:00:00").toLocaleDateString("pt-BR")}</div>)}
                {f.pedagoga.length === 0 && <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhuma presença registrada.</p>}
              </div>
              <div className="rounded-lg p-3" style={{ background: T.paper }}>
                <div className="text-xs f-mono uppercase mb-1" style={{ color: T.cyan }}>🎵 Musicoterapia</div>
                <p className="text-sm">{f.musicoterapia || "Sem ausências registradas."}</p>
              </div>
              <div className="rounded-lg p-3" style={{ background: T.paper }}>
                <div className="text-xs f-mono uppercase mb-1" style={{ color: T.cyan }}>🏋️ Educador Físico ({f.edufisico.length} dia(s))</div>
                {f.edufisico.map((d) => <div key={d.date} className="text-sm">{new Date(d.date + "T00:00:00").toLocaleDateString("pt-BR")}</div>)}
                {f.edufisico.length === 0 && <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhuma presença registrada.</p>}
              </div>
            </div>
          </SectionCard>
        );
      })}
    </div>
  );
}

function EducacaoContinuadaPage({ pd, onAddEvento, onToggleParticipante, onDeleteEvento, onOpenCertificado }) {
  const empty = { titulo: "", tema: "", tipo: EVENTO_TIPOS[0], data: "", cargaHoraria: "", palestrante: "", descricao: "" };
  const [form, setForm] = useState(empty);
  const submit = (e) => { e.preventDefault(); if (!form.titulo.trim() || !form.data) return; onAddEvento({ id: uid(), ...form, participantes: {} }); setForm(empty); };
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));
  const eventos = pd.eventosEducacao.slice().sort((a, b) => (a.data || "").localeCompare(b.data || ""));
  const hoje = new Date().toISOString().slice(0, 10);
  const proximos = eventos.filter((e) => e.data >= hoje);
  const passados = eventos.filter((e) => e.data < hoje).reverse();

  return (
    <div>
      <div className="mb-6"><div className="text-xs f-mono uppercase tracking-wide mb-1" style={{ color: T.cyan }}>Desenvolvimento</div><h1 className="f-display text-2xl font-semibold" style={{ color: T.ink }}>Educação Continuada</h1><p className="text-sm mt-1" style={{ color: T.inkSoft }}>Cronograma anual de palestras, treinamentos e eventos.</p></div>
      <SectionCard>
        <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Agendar novo evento</div>
        <form onSubmit={submit}>
          <div className="grid sm:grid-cols-2 gap-3">
            <Field label="Título"><input required className={inputCls} style={inputStyle} value={form.titulo} onChange={set("titulo")} /></Field>
            <Field label="Tema"><input className={inputCls} style={inputStyle} value={form.tema} onChange={set("tema")} /></Field>
          </div>
          <div className="grid sm:grid-cols-3 gap-3">
            <Field label="Tipo"><select className={inputCls} style={inputStyle} value={form.tipo} onChange={set("tipo")}>{EVENTO_TIPOS.map((t) => <option key={t}>{t}</option>)}</select></Field>
            <Field label="Data"><input required type="date" className={inputCls} style={inputStyle} value={form.data} onChange={set("data")} /></Field>
            <Field label="Carga horária (h)"><input type="number" min="0" className={inputCls} style={inputStyle} value={form.cargaHoraria} onChange={set("cargaHoraria")} /></Field>
          </div>
          <Field label="Palestrante / responsável"><input className={inputCls} style={inputStyle} value={form.palestrante} onChange={set("palestrante")} /></Field>
          <Field label="Descrição"><textarea className={inputCls} style={{ ...inputStyle, minHeight: 70 }} value={form.descricao} onChange={set("descricao")} /></Field>
          <Btn type="submit" variant="accent"><Plus size={15} />Agendar evento</Btn>
        </form>
      </SectionCard>
      <div className="text-xs f-mono uppercase tracking-wide mb-2 mt-4" style={{ color: T.cyan }}>Próximos eventos</div>
      {proximos.length === 0 ? <SectionCard><p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhum evento futuro agendado.</p></SectionCard> : proximos.map((ev) => <EventoCard key={ev.id} evento={ev} colaboradores={pd.colaboradores} onToggleParticipante={onToggleParticipante} onDelete={onDeleteEvento} onOpenCertificado={onOpenCertificado} />)}
      {passados.length > 0 && (
        <>
          <div className="text-xs f-mono uppercase tracking-wide mb-2 mt-4" style={{ color: T.cyan }}>Eventos realizados</div>
          {passados.map((ev) => <EventoCard key={ev.id} evento={ev} colaboradores={pd.colaboradores} onToggleParticipante={onToggleParticipante} onDelete={onDeleteEvento} onOpenCertificado={onOpenCertificado} />)}
        </>
      )}
    </div>
  );
}

function TreinamentosResultsPage({ pd }) {
  const ativos = pd.colaboradores.filter((c) => (c.status || "Ativo") === "Ativo");
  return (
    <div>
      <div className="mb-6"><div className="text-xs f-mono uppercase tracking-wide mb-1" style={{ color: T.cyan }}>Desempenho</div><h1 className="f-display text-2xl font-semibold" style={{ color: T.ink }}>Resultados de Treinamentos</h1></div>
      {pd.trainings.length === 0 ? <SectionCard><p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhum treinamento cadastrado.</p></SectionCard> : pd.trainings.map((tr) => {
        const rows = ativos.map((c) => {
          const rec = pd.trainingCompletions[c.id]?.[tr.id];
          const done = rec && typeof rec === "object" ? rec.done : !!rec;
          const score = rec && typeof rec === "object" ? rec.score : null;
          const date = rec && typeof rec === "object" ? rec.date : null;
          return { colaborador: c, done, score, date };
        });
        const completedRows = rows.filter((r) => r.done);
        const scores = completedRows.map((r) => r.score).filter((s) => typeof s === "number");
        const avgScore = scores.length ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length) : null;
        const pct = ativos.length ? Math.round((completedRows.length / ativos.length) * 100) : 0;
        return (
          <SectionCard key={tr.id}>
            <div className="flex flex-wrap items-center justify-between gap-2 mb-2">
              <div><div className="text-sm font-semibold" style={{ color: T.ink }}>{tr.titulo}</div><div className="text-xs" style={{ color: T.inkSoft }}>{tr.tipo}</div></div>
              <div className="flex gap-4 text-right">
                <div><div className="f-display text-lg font-semibold" style={{ color: T.cyan }}>{pct}%</div><div className="text-[10px]" style={{ color: T.inkSoft }}>concluíram</div></div>
                <div><div className="f-display text-lg font-semibold" style={{ color: T.ink }}>{avgScore ?? "—"}</div><div className="text-[10px]" style={{ color: T.inkSoft }}>nota média</div></div>
              </div>
            </div>
            <ProgressBar pct={pct} />
            <div className="mt-3 space-y-1">
              {rows.sort((a, b) => (b.score || -1) - (a.score || -1)).map((r) => (
                <div key={r.colaborador.id} className="flex items-center justify-between text-sm px-2.5 py-1.5 rounded" style={{ background: T.paper }}>
                  <span>{r.done ? <CheckCircle2 size={14} style={{ color: T.success, display: "inline", verticalAlign: -2, marginRight: 6 }} /> : <Circle size={14} style={{ color: T.inkSoft, display: "inline", verticalAlign: -2, marginRight: 6 }} />}{r.colaborador.nome} <span style={{ color: T.inkSoft }}>· {r.colaborador.cargo}</span></span>
                  <span className="f-mono text-xs" style={{ color: T.inkSoft }}>{r.done ? `${typeof r.score === "number" ? r.score + "%" : "concluído"}${r.date ? " · " + r.date : ""}` : "pendente"}</span>
                </div>
              ))}
              {ativos.length === 0 && <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhum colaborador ativo cadastrado.</p>}
            </div>
          </SectionCard>
        );
      })}
    </div>
  );
}

function DPPanel({ pd, atestados, adiantamentos, solicitacoes, justificativas, onNavigate, toggleAdmissaoStep, toggleDesligamentoStep, toggleIntegrationItem }) {
  const admissaoProc = pd.processes.find((p) => p.nome === "Admissão");
  const desligamentoProc = pd.processes.find((p) => p.nome === "Desligamento");
  const ativos = pd.colaboradores.filter((c) => (c.status || "Ativo") === "Ativo");
  const desligados = pd.colaboradores.filter((c) => c.status === "Desligado");
  const kitAvg = ativos.length ? Math.round(ativos.reduce((acc, c) => acc + (Object.values(pd.integrationChecklist[c.id] || {}).filter(Boolean).length / INTEGRATION_KIT_ITEMS.length), 0) / ativos.length * 100) : 0;
  const mk = currentMonthKey();
  const [selectedId, setSelectedId] = useState(null);
  const [selectedDesligadoId, setSelectedDesligadoId] = useState(null);
  const overview = [
    { label: "Atestados novos", value: atestados.filter((a) => a.status === "novo").length, view: "atestados" },
    { label: "Adiantamentos pendentes", value: adiantamentos.filter((a) => a.status === "pendente").length, view: "adiantamentos" },
    { label: "Solicitações abertas", value: solicitacoes.filter((s) => s.status === "aberta").length, view: "solicitacoes" },
    { label: "Justificativas de ponto pendentes", value: justificativas.filter((j) => j.status === "pendente").length, view: "justificativas" },
    { label: "Fechamento prestadores (mês)", value: pd.fechamentosPrestadores.some((f) => f.monthKey === mk) ? "Enviado" : "Pendente", view: "prestadores" },
    { label: "Integração da equipe", value: `${kitAvg}%`, view: null },
  ];
  const selected = ativos.find((c) => c.id === selectedId);
  const selectedDesligado = desligados.find((c) => c.id === selectedDesligadoId);

  const kitPctOf = (c) => Math.round((INTEGRATION_KIT_ITEMS.filter((_, idx) => (pd.integrationChecklist[c.id] || {})[idx]).length / INTEGRATION_KIT_ITEMS.length) * 100);
  const deslPctOf = (c) => {
    if (!desligamentoProc || desligamentoProc.etapas.length === 0) return 0;
    const des = pd.desligamentoChecklist[c.id] || {};
    return Math.round((desligamentoProc.etapas.filter((s) => des[s.id]).length / desligamentoProc.etapas.length) * 100);
  };

  return (
    <div>
      <div className="mb-6"><div className="text-xs f-mono uppercase tracking-wide mb-1" style={{ color: T.cyan }}>Departamento Pessoal</div><h1 className="f-display text-2xl font-semibold" style={{ color: T.ink }}>Painel DP</h1><p className="text-sm mt-1" style={{ color: T.inkSoft }}>Visão geral do trabalho do DP.</p></div>

      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mb-6">
        {overview.map((o) => (
          <button key={o.label} disabled={!o.view || !onNavigate} onClick={() => o.view && onNavigate && onNavigate(o.view)} className="text-left rounded-lg p-3 disabled:cursor-default" style={{ border: `1px solid ${T.line}`, background: T.paperRaised }}>
            <div className="f-display text-xl font-semibold" style={{ color: typeof o.value === "number" && o.value > 0 ? T.amber : T.ink }}>{o.value}</div>
            <div className="text-xs" style={{ color: T.inkSoft }}>{o.label}</div>
          </button>
        ))}
      </div>

      <SectionCard>
        <div className="text-xs f-mono uppercase tracking-wide mb-1" style={{ color: T.cyan }}>Integração — colaboradores ativos ({ativos.length})</div>
        <p className="text-xs mb-3" style={{ color: T.inkSoft }}>Clique em um colaborador para ver e marcar o kit de integração e as etapas de admissão.</p>
        {ativos.length === 0 && <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhum colaborador ativo cadastrado.</p>}
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-2 mb-4">
          {ativos.map((c) => {
            const pct = kitPctOf(c);
            return (
              <button key={c.id} onClick={() => setSelectedId(selectedId === c.id ? null : c.id)} className="text-left rounded-lg p-3" style={{ border: `1px solid ${selectedId === c.id ? T.cyan : T.line}`, background: selectedId === c.id ? T.cyanSoft : T.paperRaised }}>
                <div className="text-sm font-medium" style={{ color: T.ink }}>{c.nome}</div>
                <div className="text-xs mb-1.5" style={{ color: T.inkSoft }}>{c.cargo}</div>
                <ProgressBar pct={pct} color={pct === 100 ? T.success : T.amber} />
                <div className="text-[10px] f-mono mt-1" style={{ color: pct === 100 ? T.success : T.amber }}>{pct}% integrado</div>
              </button>
            );
          })}
        </div>
        {selected && (
          <div className="rounded-lg p-3" style={{ border: `1px solid ${T.line}` }}>
            <div className="text-sm font-semibold mb-2" style={{ color: T.ink }}>{selected.nome} <span style={{ color: T.inkSoft, fontWeight: 400 }}>· {selected.cargo}</span></div>
            <div className="grid sm:grid-cols-2 gap-x-4">
              <div className="space-y-1">
                <div className="text-[10px] f-mono uppercase mb-0.5" style={{ color: T.inkSoft }}>Kit de Integração</div>
                {INTEGRATION_KIT_ITEMS.map((label, idx) => {
                  const kit = pd.integrationChecklist[selected.id] || {};
                  return (
                    <button key={idx} onClick={() => toggleIntegrationItem(selected.id, idx)} className="w-full flex items-start gap-2 text-left text-xs py-0.5">
                      {kit[idx] ? <CheckCircle2 size={13} style={{ color: T.success, marginTop: 2, flexShrink: 0 }} /> : <Circle size={13} style={{ color: T.inkSoft, marginTop: 2, flexShrink: 0 }} />}
                      <span style={{ textDecoration: kit[idx] ? "line-through" : "none" }}>{label}</span>
                    </button>
                  );
                })}
              </div>
              {admissaoProc && admissaoProc.etapas.length > 0 && (
                <div className="space-y-1">
                  <div className="text-[10px] f-mono uppercase mb-0.5" style={{ color: T.inkSoft }}>Etapas de admissão</div>
                  {admissaoProc.etapas.map((s) => {
                    const adm = pd.admissaoChecklist[selected.id] || {};
                    return (
                      <button key={s.id} onClick={() => toggleAdmissaoStep(selected.id, s.id)} className="w-full flex items-start gap-2 text-left text-xs py-0.5">
                        {adm[s.id] ? <CheckCircle2 size={13} style={{ color: T.success, marginTop: 2, flexShrink: 0 }} /> : <Circle size={13} style={{ color: T.inkSoft, marginTop: 2, flexShrink: 0 }} />}
                        <span style={{ textDecoration: adm[s.id] ? "line-through" : "none" }}>{s.label}</span>
                      </button>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        )}
      </SectionCard>

      {desligados.length > 0 && (
        <SectionCard>
          <div className="text-xs f-mono uppercase tracking-wide mb-1" style={{ color: T.cyan }}>Desligamentos em andamento ({desligados.length})</div>
          <p className="text-xs mb-3" style={{ color: T.inkSoft }}>Clique em um colaborador para conferir as etapas de desligamento.</p>
          <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-2 mb-4">
            {desligados.map((c) => {
              const pct = deslPctOf(c);
              return (
                <button key={c.id} onClick={() => setSelectedDesligadoId(selectedDesligadoId === c.id ? null : c.id)} className="text-left rounded-lg p-3" style={{ border: `1px solid ${selectedDesligadoId === c.id ? T.cyan : T.line}`, background: selectedDesligadoId === c.id ? T.cyanSoft : T.paperRaised }}>
                  <div className="text-sm font-medium" style={{ color: T.ink }}>{c.nome}</div>
                  <div className="text-xs mb-1.5" style={{ color: T.inkSoft }}>{c.cargo}</div>
                  <ProgressBar pct={pct} color={pct === 100 ? T.success : T.amber} />
                  <div className="text-[10px] f-mono mt-1" style={{ color: pct === 100 ? T.success : T.amber }}>{pct}%</div>
                </button>
              );
            })}
          </div>
          {selectedDesligado && (
            <div className="rounded-lg p-3" style={{ border: `1px solid ${T.line}` }}>
              <div className="text-sm font-semibold mb-2" style={{ color: T.ink }}>{selectedDesligado.nome} <span style={{ color: T.inkSoft, fontWeight: 400 }}>· {selectedDesligado.cargo}</span></div>
              {!desligamentoProc || desligamentoProc.etapas.length === 0 ? <p className="text-xs italic" style={{ color: T.inkSoft }}>Mapeie o processo de Desligamento na Fase 1 para listar as etapas aqui.</p> : (
                <div className="space-y-1">{desligamentoProc.etapas.map((s) => {
                  const des = pd.desligamentoChecklist[selectedDesligado.id] || {};
                  return (
                    <button key={s.id} onClick={() => toggleDesligamentoStep(selectedDesligado.id, s.id)} className="w-full flex items-start gap-2 text-left text-xs py-0.5">
                      {des[s.id] ? <CheckCircle2 size={13} style={{ color: T.success, marginTop: 2, flexShrink: 0 }} /> : <Circle size={13} style={{ color: T.inkSoft, marginTop: 2, flexShrink: 0 }} />}
                      <span style={{ textDecoration: des[s.id] ? "line-through" : "none" }}>{s.label}</span>
                    </button>
                  );
                })}</div>
              )}
            </div>
          )}
        </SectionCard>
      )}
    </div>
  );
}

function ColaboradoresPage({ pd, submissions, role, addColaborador, removeColaborador, assignOnboarding, toggleOnboardingTask, toggleTraining, setTrainingScore, toggleIntegrationItem, addLeaderEvaluation, setColaboradorStatus }) {
  const [form, setForm] = useState({ nome: "", cpf: "", cargo: ILPI_CARGOS[0], setor: "", dataAdmissao: "", senha: "" });
  const [selectedId, setSelectedId] = useState(null);
  const selected = pd.colaboradores.find((c) => c.id === selectedId);
  const submit = (e) => { e.preventDefault(); if (!form.nome.trim()) return; addColaborador({ ...form, id: Date.now() + "" }); setForm({ nome: "", cpf: "", cargo: ILPI_CARGOS[0], setor: "", dataAdmissao: "", senha: "" }); };
  return (
    <div>
      <div className="mb-6"><div className="text-xs f-mono uppercase tracking-wide mb-1" style={{ color: T.cyan }}>Equipe</div><h1 className="f-display text-2xl font-semibold" style={{ color: T.ink }}>Colaboradores</h1></div>
      {(role === "rh" || role === "cliente") && (
        <SectionCard>
          <form onSubmit={submit} className="flex flex-wrap gap-2 items-end">
            <div style={{ minWidth: 160 }} className="flex-1"><Field label="Nome"><input required className={inputCls} style={inputStyle} value={form.nome} onChange={(e) => setForm((f) => ({ ...f, nome: e.target.value }))} /></Field></div>
            <div style={{ minWidth: 140 }} className="flex-1"><Field label="CPF"><input className={inputCls} style={inputStyle} value={form.cpf} onChange={(e) => setForm((f) => ({ ...f, cpf: e.target.value }))} /></Field></div>
            <div style={{ minWidth: 160 }} className="flex-1"><Field label="Cargo"><select className={inputCls} style={inputStyle} value={form.cargo} onChange={(e) => setForm((f) => ({ ...f, cargo: e.target.value }))}>{ILPI_CARGOS.map((c) => <option key={c}>{c}</option>)}</select></Field></div>
            <div style={{ minWidth: 140 }} className="flex-1"><Field label="Setor"><input className={inputCls} style={inputStyle} value={form.setor} onChange={(e) => setForm((f) => ({ ...f, setor: e.target.value }))} /></Field></div>
            <div style={{ minWidth: 140 }}><Field label="Admissão"><input type="date" className={inputCls} style={inputStyle} value={form.dataAdmissao} onChange={(e) => setForm((f) => ({ ...f, dataAdmissao: e.target.value }))} /></Field></div>
            <div style={{ minWidth: 140 }}><Field label="Senha de acesso"><input className={inputCls} style={inputStyle} value={form.senha} onChange={(e) => setForm((f) => ({ ...f, senha: e.target.value }))} /></Field></div>
            <Btn type="submit" variant="accent"><UserPlus size={15} />Adicionar</Btn>
          </form>
        </SectionCard>
      )}
      <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3 mb-5">
        {pd.colaboradores.map((c) => <button key={c.id} onClick={() => setSelectedId(c.id)} className="text-left rounded-lg p-3" style={{ border: `1px solid ${selectedId === c.id ? T.cyan : T.line}`, background: selectedId === c.id ? T.cyanSoft : T.paperRaised }}><div className="text-sm font-medium" style={{ color: T.ink }}>{c.nome}</div><div className="text-xs" style={{ color: T.inkSoft }}>{c.cargo}{c.setor && ` · ${c.setor}`}</div></button>)}
        {pd.colaboradores.length === 0 && <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhum colaborador cadastrado ainda.</p>}
      </div>
      {selected && <EmployeeProfile emp={selected} pd={pd} submissions={submissions} role={role} onRemove={() => { removeColaborador(selected.id); setSelectedId(null); }} assignOnboarding={assignOnboarding} toggleOnboardingTask={toggleOnboardingTask} toggleTraining={toggleTraining} setTrainingScore={setTrainingScore} toggleIntegrationItem={toggleIntegrationItem} addLeaderEvaluation={addLeaderEvaluation} setColaboradorStatus={setColaboradorStatus} />}
    </div>
  );
}

