      <div className="flex-1" style={{ minWidth: 180 }}><Field label="Seu nome"><select required className={inputCls} style={inputStyle} value={colaboradorId} onChange={(e) => setColaboradorId(e.target.value)}><option value="">Selecione...</option>{colaboradores.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></Field></div>
