function TrainingModal({ html, onClose }) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3" style={{ background: "#00000099" }}>
      <div className="w-full h-full max-w-3xl rounded-xl overflow-hidden flex flex-col" style={{ background: "#fff" }}>
        <div className="flex justify-end p-2 no-print"><button onClick={onClose} className="text-sm f-mono px-3 py-1 rounded" style={{ color: T.ink }}>Fechar ✕</button></div>
        <iframe title="treinamento" srcDoc={html} style={{ flex: 1, width: "100%", border: "none" }} />
      </div>
    </div>
  );
}
function TreinamentosPortal({ trainings, myColaboradorId, myCompletions, onComplete }) {
  const [openId, setOpenId] = useState(null);
  useEffect(() => {
    if (!openId) return;
    const handler = (e) => {
      if (e.data && e.data.type === "training-complete" && myColaboradorId) {
        onComplete(myColaboradorId, openId, e.data.score);
      }
    };
    window.addEventListener("message", handler);
    return () => window.removeEventListener("message", handler);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [openId]);
  if (trainings.length === 0) return <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhum treinamento disponível no momento.</p>;
  return (
    <div className="space-y-2">
      {trainings.map((tr) => {
        const rec = myCompletions[tr.id]; const done = rec && typeof rec === "object" ? rec.done : !!rec; const score = rec && typeof rec === "object" ? rec.score : null;
        const embedded = EMBEDDED_TRAININGS[tr.id];
        return (
          <div key={tr.id} className="flex items-center justify-between gap-2 px-3 py-2.5 rounded-lg" style={{ border: `1px solid ${T.line}` }}>
            <div>
              <div className="text-sm font-medium" style={{ color: T.ink }}>{tr.titulo}</div>
              <div className="text-xs" style={{ color: T.inkSoft }}>{tr.tipo}{done && <span style={{ color: T.success }}> · Concluído{typeof score === "number" ? ` — ${score}%` : ""}</span>}</div>
            </div>
            {embedded ? <Btn variant="accent" onClick={() => setOpenId(tr.id)}>{done ? "Refazer" : "Fazer treinamento"}</Btn>
              : tr.link ? <a href={tr.link} target="_blank" rel="noreferrer"><Btn variant="accent">Abrir treinamento</Btn></a>
              : <span className="text-xs italic" style={{ color: T.inkSoft }}>Em breve</span>}
          </div>
        );
      })}
      {openId && EMBEDDED_TRAININGS[openId] && <TrainingModal html={EMBEDDED_TRAININGS[openId]} onClose={() => setOpenId(null)} />}
    </div>
  );
}
