/* ATESTADOS (colaborador envia, RH/DP recebe)                         */
/* ------------------------------------------------------------------ */
const CID_DATABASE = {
  A00: "Cólera", A09: "Diarreia e gastroenterite", A15: "Tuberculose respiratória", A90: "Dengue",
  B34: "Infecção viral não especificada", C50: "Neoplasia maligna da mama", C61: "Neoplasia maligna da próstata",
  G43: "Enxaqueca", G44: "Outras síndromes de algias cefálicas", J00: "Nasofaringite aguda (resfriado comum)",
  J01: "Sinusite aguda", J02: "Faringite aguda", J03: "Amigdalite aguda", J06: "Infecção aguda das vias aéreas superiores",
  J11: "Influenza (gripe)", J18: "Pneumonia", J20: "Bronquite aguda", J30: "Rinite alérgica", J40: "Bronquite não especificada",
  J45: "Asma", K21: "Doença de refluxo gastroesofágico", K29: "Gastrite e duodenite", K30: "Dispepsia",
  K35: "Apendicite aguda", K52: "Outras gastroenterites e colites", K59: "Outros transtornos funcionais do intestino",
  K80: "Colelitíase", M10: "Gota", M17: "Gonartrose (artrose do joelho)", M19: "Outras artroses",
  M25: "Outros transtornos articulares", M47: "Espondilose", M51: "Outros transtornos de discos intervertebrais",
  M53: "Outras dorsopatias", M54: "Dorsalgia (dor nas costas)", M62: "Outros transtornos musculares",
  M65: "Sinovite e tenossinovite", M75: "Lesões do ombro", M77: "Outras entesopatias", M79: "Outros transtornos dos tecidos moles",
  N30: "Cistite", N39: "Outros transtornos do trato urinário", R05: "Tosse", R10: "Dor abdominal e pélvica",
  R11: "Náusea e vômitos", R50: "Febre de origem desconhecida", R51: "Cefaleia (dor de cabeça)", R52: "Dor não classificada",
  S06: "Traumatismo intracraniano", S13: "Luxação, entorse do pescoço", S43: "Luxação, entorse do ombro",
  S52: "Fratura do antebraço", S53: "Luxação, entorse do cotovelo", S60: "Traumatismo superficial do punho",
  S61: "Ferimento do punho e mão", S62: "Fratura do punho e mão", S63: "Luxação, entorse do punho",
  S82: "Fratura da perna", S83: "Luxação, entorse do joelho", S93: "Luxação, entorse do tornozelo",
  T14: "Traumatismo não especificado", Z00: "Exame geral", Z01: "Outros exames especiais", Z03: "Observação médica",
  Z09: "Exame de seguimento", Z23: "Imunização bacteriana", Z25: "Imunização viral", Z76: "Pessoas em contato com serviços de saúde",
};
const ATESTADO_TIPOS = [{ id: "atestado", label: "Atestado Médico" }, { id: "cerest", label: "CEREST (Acidente de Trabalho)" }, { id: "acidente", label: "Comunicação de Acidente" }, { id: "outro", label: "Outro" }];
function formatBytes(b) { return (b / (1024 * 1024)).toFixed(2) + " MB"; }
function fileToBase64(file) { return new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(r.result); r.onerror = rej; r.readAsDataURL(file); }); }

function AtestadoForm({ colaboradores, defaultId, onSubmit }) {
  const [colaboradorId, setColaboradorId] = useState(defaultId || "");
  const [nome, setNome] = useState(colaboradores.find((c) => c.id === defaultId)?.nome || "");
  const [tipo, setTipo] = useState(""), [cid, setCid] = useState("");
  const [file, setFile] = useState(null), [fileErr, setFileErr] = useState("");
  const [sending, setSending] = useState(false), [sent, setSent] = useState(false);
  const cidUpper = cid.trim().toUpperCase();
  const cidDesc = cidUpper.length >= 2 ? (CID_DATABASE[cidUpper] || "CID não encontrado na base — pode enviar mesmo assim.") : null;

  const handleFile = async (f) => {
    setFileErr("");
    if (!f) return;
    if (f.size > 3 * 1024 * 1024) { setFileErr("Arquivo muito grande! Tamanho máximo: 3MB."); return; }
    const base64 = await fileToBase64(f);
    setFile({ name: f.name, size: f.size, type: f.type, base64 });
  };

  if (sent) return <Confirm text="Documento enviado com sucesso! O RH foi notificado." />;

  const submit = async (e) => {
    e.preventDefault();
    if (!nome.trim() || !tipo || !file) return;
    setSending(true);
    const id = uid();
    try { await window.storage.set(`atestado-file:${id}`, file.base64, true); } catch { setFileErr("Falha ao enviar o arquivo. Tente novamente."); setSending(false); return; }
    onSubmit({ id, colaboradorId: colaboradorId || null, nome, tipo, cid: cidUpper || "Não informado", cidDescricao: cidUpper ? (CID_DATABASE[cidUpper] || "Não encontrado") : "Não informado", arquivoNome: file.name, arquivoTipo: file.type, arquivoTamanho: file.size, date: new Date().toLocaleDateString("pt-BR"), status: "novo" });
    setSending(false); setSent(true);
  };

  return (
    <form onSubmit={submit}>
      {colaboradores.length > 0 && (
        <Field label="Selecione seu nome (opcional)">
          <select className={inputCls} style={inputStyle} value={colaboradorId} onChange={(e) => { setColaboradorId(e.target.value); const c = colaboradores.find((x) => x.id === e.target.value); if (c) setNome(c.nome); }}>
            <option value="">Prefiro digitar manualmente</option>{colaboradores.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}
          </select>
        </Field>
      )}
      <Field label="Nome do colaborador"><input required className={inputCls} style={inputStyle} value={nome} onChange={(e) => setNome(e.target.value)} /></Field>
      <Field label="Tipo de documento"><select required className={inputCls} style={inputStyle} value={tipo} onChange={(e) => setTipo(e.target.value)}><option value="">Selecione o tipo</option>{ATESTADO_TIPOS.map((t) => <option key={t.id} value={t.id}>{t.label}</option>)}</select></Field>
      <Field label="CID (opcional)">
        <input className={inputCls} style={inputStyle} placeholder="Ex: J00, M54, Z76" maxLength={5} value={cid} onChange={(e) => setCid(e.target.value)} />
        {cidDesc && <div className="text-xs mt-1.5 p-2 rounded-md" style={{ background: T.cyanSoft, color: T.ink }}><b>CID {cidUpper}</b> — {cidDesc}</div>}
      </Field>
      <Field label="Anexar documento (PDF, JPG ou PNG — máx. 3MB)">
        {!file ? (
          <label className="block text-center px-4 py-8 rounded-lg cursor-pointer" style={{ border: `2px dashed ${T.line}`, background: T.paper }}>
            <input type="file" required accept=".pdf,.jpg,.jpeg,.png" className="hidden" onChange={(e) => handleFile(e.target.files[0])} />
            <Paperclip size={28} style={{ color: T.inkSoft, margin: "0 auto 8px" }} />
            <div className="text-sm" style={{ color: T.inkSoft }}>Clique para selecionar o arquivo</div>
          </label>
        ) : (
          <div className="flex items-center gap-3 p-3 rounded-lg" style={{ background: T.successSoft }}>
            <span className="text-2xl">{file.type.includes("pdf") ? "📄" : "🖼️"}</span>
            <div className="flex-1"><div className="text-sm font-medium" style={{ color: T.success }}>{file.name}</div><div className="text-xs" style={{ color: T.success }}>{formatBytes(file.size)}</div></div>
            <Btn variant="danger" onClick={() => setFile(null)}>Remover</Btn>
          </div>
        )}
        {fileErr && <p className="text-xs mt-1" style={{ color: T.danger }}>{fileErr}</p>}
      </Field>
      <Btn type="submit" variant="accent" className="w-full justify-center" disabled={sending}>{sending ? "Enviando..." : "📤 Enviar documento"}</Btn>
    </form>
  );
}

function AtestadoDetail({ item, onClose, onDelete }) {
  const [base64, setBase64] = useState(null);
  useEffect(() => { (async () => { try { const r = await window.storage.get(`atestado-file:${item.id}`, true); setBase64(r ? r.value : null); } catch { setBase64(null); } })(); }, [item.id]);
  return (
    <SectionCard>
      <div className="flex justify-between items-start mb-3">
        <div><div className="text-sm font-semibold" style={{ color: T.ink }}>{item.nome}</div><div className="text-xs" style={{ color: T.inkSoft }}>{ATESTADO_TIPOS.find((t) => t.id === item.tipo)?.label} · {item.date}</div></div>
        <button onClick={onClose} className="text-xs f-mono" style={{ color: T.inkSoft }}>Fechar ✕</button>
      </div>
      <div className="grid sm:grid-cols-2 gap-2 text-sm mb-3">
        <div><span style={{ color: T.inkSoft }}>CID:</span> <b>{item.cid}</b></div>
        <div><span style={{ color: T.inkSoft }}>Descrição:</span> {item.cidDescricao}</div>
        <div><span style={{ color: T.inkSoft }}>Arquivo:</span> {item.arquivoNome} ({formatBytes(item.arquivoTamanho)})</div>
      </div>
      {base64 ? (
        item.arquivoTipo === "application/pdf" ? (
          <iframe title="atestado" src={base64} style={{ width: "100%", height: 420, border: `1px solid ${T.line}`, borderRadius: 8 }} />
        ) : <img src={base64} alt="Documento" style={{ maxWidth: "100%", borderRadius: 8, border: `1px solid ${T.line}` }} />
      ) : <p className="text-sm italic" style={{ color: T.inkSoft }}>Carregando arquivo…</p>}
      <div className="flex gap-2 mt-3">
        {base64 && <a href={base64} download={item.arquivoNome}><Btn variant="ghost"><Download size={14} />Baixar</Btn></a>}
        <Btn variant="danger" onClick={() => onDelete(item.id)}>Excluir</Btn>
      </div>
    </SectionCard>
  );
}

function AtestadosRHPage({ list, onMarkVisto, onDelete }) {
  const [filtroTipo, setFiltroTipo] = useState(""), [filtroStatus, setFiltroStatus] = useState(""), [busca, setBusca] = useState("");
  const [openId, setOpenId] = useState(null);
  const novos = list.filter((a) => a.status === "novo").length;
  const vistos = list.filter((a) => a.status === "visto").length;
  const cerestAcidente = list.filter((a) => a.tipo === "cerest" || a.tipo === "acidente").length;
  let filtrados = list;
  if (filtroTipo) filtrados = filtrados.filter((a) => a.tipo === filtroTipo);
  if (filtroStatus) filtrados = filtrados.filter((a) => (a.status || "novo") === filtroStatus);
  if (busca) filtrados = filtrados.filter((a) => a.nome.toLowerCase().includes(busca.toLowerCase()));
  filtrados = filtrados.slice().reverse();
  const open = list.find((a) => a.id === openId);
  return (
    <div>
      <div className="mb-4"><div className="text-xs f-mono uppercase tracking-wide mb-1" style={{ color: T.cyan }}>RH · DP</div><h1 className="f-display text-2xl font-semibold" style={{ color: T.ink }}>Atestados e Documentos</h1></div>
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-4">
        {[["Total", list.length], ["Novos", novos], ["Vistos", vistos], ["CEREST/Acidentes", cerestAcidente]].map(([l, v]) => (
          <div key={l} className="rounded-lg p-3" style={{ border: `1px solid ${T.line}`, background: T.paperRaised }}><div className="f-display text-xl font-semibold" style={{ color: T.ink }}>{v}</div><div className="text-xs" style={{ color: T.inkSoft }}>{l}</div></div>
        ))}
      </div>
      <div className="flex flex-wrap gap-2 items-end mb-4">
        <Field label="Tipo"><select className={inputCls} style={inputStyle} value={filtroTipo} onChange={(e) => setFiltroTipo(e.target.value)}><option value="">Todos</option>{ATESTADO_TIPOS.map((t) => <option key={t.id} value={t.id}>{t.label}</option>)}</select></Field>
        <Field label="Status"><select className={inputCls} style={inputStyle} value={filtroStatus} onChange={(e) => setFiltroStatus(e.target.value)}><option value="">Todos</option><option value="novo">Novos</option><option value="visto">Vistos</option></select></Field>
        <Field label="Buscar por nome"><input className={inputCls} style={inputStyle} value={busca} onChange={(e) => setBusca(e.target.value)} /></Field>
      </div>
      {open && <AtestadoDetail item={open} onClose={() => setOpenId(null)} onDelete={(id) => { onDelete(id); setOpenId(null); }} />}
      {filtrados.length === 0 ? <SectionCard><p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhum documento encontrado.</p></SectionCard> : filtrados.map((a) => (
        <button key={a.id} onClick={() => { setOpenId(a.id); if ((a.status || "novo") === "novo") onMarkVisto(a.id); }} className="w-full text-left rounded-lg p-3 mb-2 flex items-center justify-between gap-2" style={{ border: `1px solid ${T.line}`, background: T.paperRaised }}>
          <div>
            <div className="text-sm font-medium" style={{ color: T.ink }}>{a.nome}</div>
            <div className="text-xs" style={{ color: T.inkSoft }}>{ATESTADO_TIPOS.find((t) => t.id === a.tipo)?.label} · {a.date}{a.cid !== "Não informado" && ` · CID ${a.cid}`}</div>
          </div>
          <span className="text-xs f-mono px-2 py-0.5 rounded-full shrink-0" style={{ background: (a.status || "novo") === "novo" ? T.amberSoft : T.successSoft, color: (a.status || "novo") === "novo" ? T.amber : T.success }}>{(a.status || "novo") === "novo" ? "Novo" : "Visto"}</span>
        </button>
      ))}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* ADIANTAMENTO DE SALÁRIO (colaborador → DP autoriza → cliente paga)  */
/* ------------------------------------------------------------------ */
const ADIANT_STATUS = {
  pendente: { label: "Aguardando DP", color: T.amber, bg: T.amberSoft },
  autorizado: { label: "Autorizado — aguardando pagamento", color: T.cyan, bg: T.cyanSoft },
  recusado: { label: "Recusado", color: T.danger, bg: T.danger + "22" },
  pago: { label: "Pago", color: T.success, bg: T.successSoft },
};
function brl(v) { return Number(v || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" }); }

function AdiantamentoForm({ colaboradores, defaultId, list, onSubmit }) {
  const [colaboradorId, setColaboradorId] = useState(defaultId || "");
  const [nome, setNome] = useState(colaboradores.find((c) => c.id === defaultId)?.nome || "");
  const [valor, setValor] = useState(""), [motivo, setMotivo] = useState("");
  const [sent, setSent] = useState(false);
  const mine = list.filter((a) => (colaboradorId ? a.colaboradorId === colaboradorId : a.nome === nome));
  const submit = (e) => {
    e.preventDefault();
    const v = Number(String(valor).replace(",", "."));
    if (!nome.trim() || !(v > 0)) return;
    const now = new Date();
    const c = colaboradores.find((x) => x.id === colaboradorId);
    onSubmit({ id: uid(), colaboradorId: colaboradorId || null, nome, cargo: c?.cargo || "", valor: v, motivo,
      monthKey: now.toISOString().slice(0, 7), date: now.toLocaleDateString("pt-BR"), hora: now.toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" }),
      status: "pendente", dpNota: "" });
    setSent(true); setValor(""); setMotivo("");
  };
  return (
    <div>
      {sent ? (
        <div className="mb-4"><Confirm text="Solicitação registrada! O DP fará a conferência e autorização." /><Btn variant="ghost" className="mt-2" onClick={() => setSent(false)}>Fazer outra solicitação</Btn></div>
      ) : (
        <form onSubmit={submit} className="mb-5">
          {colaboradores.length > 0 && (
            <Field label="Selecione seu nome">
              <select className={inputCls} style={inputStyle} value={colaboradorId} onChange={(e) => { setColaboradorId(e.target.value); const c = colaboradores.find((x) => x.id === e.target.value); if (c) setNome(c.nome); }}>
                <option value="">Prefiro digitar manualmente</option>{colaboradores.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
            </Field>
          )}
          <Field label="Nome do colaborador"><input required className={inputCls} style={inputStyle} value={nome} onChange={(e) => setNome(e.target.value)} /></Field>
          <Field label="Valor solicitado (R$)"><input required type="number" min="1" step="0.01" className={inputCls} style={inputStyle} placeholder="Ex: 300,00" value={valor} onChange={(e) => setValor(e.target.value)} /></Field>
          <Field label="Motivo (opcional)"><textarea className={inputCls} style={{ ...inputStyle, minHeight: 70 }} value={motivo} onChange={(e) => setMotivo(e.target.value)} /></Field>
          <Btn type="submit" variant="accent" className="w-full justify-center">Solicitar adiantamento</Btn>
        </form>
      )}
      <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Minhas solicitações</div>
      {mine.length === 0 ? <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhuma solicitação registrada.</p> : (
        <div className="space-y-1.5">{mine.slice().reverse().map((a) => { const st = ADIANT_STATUS[a.status]; return (
          <div key={a.id} className="flex items-center justify-between gap-2 px-3 py-2 rounded-md" style={{ border: `1px solid ${T.line}` }}>
            <div><div className="text-sm font-medium" style={{ color: T.ink }}>{brl(a.valor)}</div><div className="text-xs" style={{ color: T.inkSoft }}>{a.date} às {a.hora}</div></div>
            <span className="text-xs f-mono px-2 py-0.5 rounded-full shrink-0" style={{ background: st.bg, color: st.color }}>{st.label}</span>
          </div>
        ); })}</div>
      )}
    </div>
  );
}

function AdiantamentosPage({ list, role, onUpdate, onDelete }) {
  const months = [...new Set(list.map((a) => a.monthKey))].sort().reverse();
  const [month, setMonth] = useState(months[0] || currentMonthKey());
  const [statusF, setStatusF] = useState("");
  const isDP = role === "dp" || role === "rh" || role === "cliente";
  const isCliente = role === "cliente";
  let filtered = list.filter((a) => a.monthKey === month);
  if (statusF) filtered = filtered.filter((a) => a.status === statusF);
  filtered = filtered.slice().reverse();
  const totalMes = filtered.reduce((s, a) => s + Number(a.valor || 0), 0);
  const aPagar = filtered.filter((a) => a.status === "autorizado").reduce((s, a) => s + Number(a.valor || 0), 0);
  const pago = filtered.filter((a) => a.status === "pago").reduce((s, a) => s + Number(a.valor || 0), 0);
  const pendentes = list.filter((a) => a.monthKey === month && a.status === "pendente").length;

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-4 no-print">
        <div><div className="text-xs f-mono uppercase tracking-wide mb-1" style={{ color: T.cyan }}>{isCliente ? "Pagamentos autorizados" : "Conferência e autorização"}</div><h1 className="f-display text-2xl font-semibold" style={{ color: T.ink }}>Adiantamento de Salário</h1></div>
        <div className="flex items-center gap-2">
          <select className={inputCls} style={{ ...inputStyle, minWidth: 160 }} value={month} onChange={(e) => setMonth(e.target.value)}>
            {(months.length ? months : [currentMonthKey()]).map((m) => <option key={m} value={m}>{formatMonthLabel(m)}</option>)}
          </select>
          <Btn variant="ghost" onClick={() => window.print()}><FileText size={15} />Imprimir</Btn>
        </div>
      </div>
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-4">
        {[["Total do mês", brl(totalMes)], ["A pagar", brl(aPagar)], ["Já pago", brl(pago)], [isCliente ? "Solicitações" : "Aguardando DP", isCliente ? filtered.length : pendentes]].map(([l, v]) => (
          <div key={l} className="rounded-lg p-3" style={{ border: `1px solid ${T.line}`, background: T.paperRaised }}><div className="f-display text-lg font-semibold" style={{ color: T.ink }}>{v}</div><div className="text-xs" style={{ color: T.inkSoft }}>{l}</div></div>
        ))}
      </div>
      <div className="mb-4" style={{ maxWidth: 220 }}>
        <Field label="Filtrar por status">
          <select className={inputCls} style={inputStyle} value={statusF} onChange={(e) => setStatusF(e.target.value)}>
            <option value="">Todos</option>
            {Object.entries(ADIANT_STATUS).filter(([k]) => !isCliente || k === "autorizado" || k === "pago").map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}
          </select>
        </Field>
      </div>
      {filtered.length === 0 ? <SectionCard><p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhuma solicitação neste período.</p></SectionCard> : filtered.map((a) => {
        const st = ADIANT_STATUS[a.status];
        return (
          <SectionCard key={a.id}>
            <div className="flex flex-wrap items-start justify-between gap-2 mb-2">
              <div>
                <div className="text-sm font-semibold" style={{ color: T.ink }}>{a.nome} <span style={{ color: T.inkSoft, fontWeight: 400 }}>{a.cargo && `· ${a.cargo}`}</span></div>
                <div className="text-xs f-mono" style={{ color: T.inkSoft }}>Solicitado em {a.date} às {a.hora}</div>
              </div>
              <div className="text-right">
                <div className="f-display text-lg font-semibold" style={{ color: T.ink }}>{brl(a.valor)}</div>
                <span className="text-xs f-mono px-2 py-0.5 rounded-full" style={{ background: st.bg, color: st.color }}>{st.label}</span>
              </div>
            </div>
            {a.motivo && <p className="text-sm mb-2" style={{ color: T.inkSoft }}>Motivo: {a.motivo}</p>}
            {a.dpNota && <p className="text-xs mb-2" style={{ color: T.inkSoft }}>Nota do DP: {a.dpNota}</p>}
            {isDP && a.status === "pendente" && (
              <div className="flex flex-wrap gap-2 items-end mt-2">
                <div className="flex-1" style={{ minWidth: 180 }}><Field label="Nota do DP (opcional)"><input className={inputCls} style={inputStyle} defaultValue="" onBlur={(e) => onUpdate(a.id, { dpNota: e.target.value })} /></Field></div>
                <Btn variant="accent" onClick={() => onUpdate(a.id, { status: "autorizado", dpData: new Date().toLocaleDateString("pt-BR") })}>Autorizar</Btn>
                <Btn variant="danger" onClick={() => onUpdate(a.id, { status: "recusado", dpData: new Date().toLocaleDateString("pt-BR") })}>Recusar</Btn>
              </div>
            )}
            {isCliente && a.status === "autorizado" && <Btn variant="accent" onClick={() => onUpdate(a.id, { status: "pago", pagoData: new Date().toLocaleDateString("pt-BR") })}>Marcar como pago</Btn>}
            {a.status === "pago" && a.pagoData && <p className="text-xs" style={{ color: T.success }}>Pago em {a.pagoData}</p>}
            {isDP && a.status !== "pendente" && <div className="mt-2"><Btn variant="danger" onClick={() => onDelete(a.id)}>Excluir</Btn></div>}
          </SectionCard>
        );
      })}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* SOLICITAÇÕES E DÚVIDAS (férias / RH / holerite)                     */
/* ------------------------------------------------------------------ */
const SOLIC_TIPOS = [
  { id: "ferias", label: "Solicitação de Férias", icon: "🏖️", desc: "Pedir período de férias" },
  { id: "duvida_rh", label: "Dúvida com o RH", icon: "💬", desc: "Benefícios, contrato, políticas, escala" },
  { id: "duvida_holerite", label: "Dúvida sobre Holerite", icon: "🧾", desc: "Descontos, horas extras, valores" },
];
const SOLIC_STATUS = {
  aberta: { label: "Aberta", color: T.amber, bg: T.amberSoft },
  analise: { label: "Em análise", color: T.cyan, bg: T.cyanSoft },
  respondida: { label: "Respondida", color: T.success, bg: T.successSoft },
  recusada: { label: "Recusada", color: T.danger, bg: T.danger + "22" },
};

function SolicitacaoForm({ colaboradores, defaultId, list, onSubmit }) {
  const [tipo, setTipo] = useState(null);
  const [colaboradorId, setColaboradorId] = useState(defaultId || "");
  const [nome, setNome] = useState(colaboradores.find((c) => c.id === defaultId)?.nome || "");
  const [inicio, setInicio] = useState(""), [dias, setDias] = useState(""), [mensagem, setMensagem] = useState(""), [competencia, setCompetencia] = useState("");
  const [sent, setSent] = useState(false);
  const mine = list.filter((s) => (colaboradorId ? s.colaboradorId === colaboradorId : s.nome === nome));

  const submit = (e) => {
    e.preventDefault();
    if (!nome.trim() || !mensagem.trim()) return;
    const now = new Date();
    const c = colaboradores.find((x) => x.id === colaboradorId);
    onSubmit({ id: uid(), tipo, colaboradorId: colaboradorId || null, nome, cargo: c?.cargo || "",
      inicio, dias, competencia, mensagem, monthKey: now.toISOString().slice(0, 7),
      date: now.toLocaleDateString("pt-BR"), hora: now.toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" }),
      status: "aberta", resposta: "" });
    setSent(true); setInicio(""); setDias(""); setMensagem(""); setCompetencia("");
  };

  return (
    <div>
      {sent ? (
        <div className="mb-5"><Confirm text="Solicitação enviada! O RH/DP responderá em breve." /><Btn variant="ghost" className="mt-2" onClick={() => { setSent(false); setTipo(null); }}>Fazer outra solicitação</Btn></div>
      ) : !tipo ? (
        <div className="mb-5">
          <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>O que você deseja solicitar?</div>
          <div className="space-y-2">
            {SOLIC_TIPOS.map((t) => (
              <button key={t.id} onClick={() => setTipo(t.id)} className="w-full flex items-center gap-3 text-left px-4 py-3 rounded-xl" style={{ border: `1px solid ${T.line}`, background: T.paperRaised }}>
                <span className="text-xl">{t.icon}</span>
                <span className="flex-1"><span className="text-sm font-medium block" style={{ color: T.ink }}>{t.label}</span><span className="text-xs" style={{ color: T.inkSoft }}>{t.desc}</span></span>
                <ChevronRight size={16} style={{ color: T.inkSoft }} />
              </button>
            ))}
          </div>
        </div>
      ) : (
        <form onSubmit={submit} className="mb-5">
          <button type="button" onClick={() => setTipo(null)} className="text-xs f-mono mb-3" style={{ color: T.inkSoft }}>&larr; Trocar tipo de solicitação</button>
          <div className="text-sm font-medium mb-3" style={{ color: T.ink }}>{SOLIC_TIPOS.find((t) => t.id === tipo).icon} {SOLIC_TIPOS.find((t) => t.id === tipo).label}</div>
          {colaboradores.length > 0 && (
            <Field label="Selecione seu nome">
              <select className={inputCls} style={inputStyle} value={colaboradorId} onChange={(e) => { setColaboradorId(e.target.value); const c = colaboradores.find((x) => x.id === e.target.value); if (c) setNome(c.nome); }}>
                <option value="">Prefiro digitar manualmente</option>{colaboradores.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
            </Field>
          )}
          <Field label="Nome do colaborador"><input required className={inputCls} style={inputStyle} value={nome} onChange={(e) => setNome(e.target.value)} /></Field>
          {tipo === "ferias" && (
            <div className="grid sm:grid-cols-2 gap-3">
              <Field label="Data de início pretendida"><input required type="date" className={inputCls} style={inputStyle} value={inicio} onChange={(e) => setInicio(e.target.value)} /></Field>
              <Field label="Quantos dias"><input required type="number" min="1" max="30" className={inputCls} style={inputStyle} value={dias} onChange={(e) => setDias(e.target.value)} /></Field>
            </div>
          )}
          {tipo === "duvida_holerite" && <Field label="Competência (mês do holerite)"><input type="month" className={inputCls} style={inputStyle} value={competencia} onChange={(e) => setCompetencia(e.target.value)} /></Field>}
          <Field label={tipo === "ferias" ? "Observações" : "Sua dúvida"}><textarea required className={inputCls} style={{ ...inputStyle, minHeight: 90 }} placeholder={tipo === "ferias" ? "Ex: gostaria de dividir em dois períodos..." : "Descreva sua dúvida com detalhes..."} value={mensagem} onChange={(e) => setMensagem(e.target.value)} /></Field>
          <Btn type="submit" variant="accent" className="w-full justify-center">Enviar solicitação</Btn>
        </form>
      )}
      <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Minhas solicitações</div>
      {mine.length === 0 ? <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhuma solicitação registrada.</p> : (
        <div className="space-y-1.5">{mine.slice().reverse().map((s) => { const st = SOLIC_STATUS[s.status]; const t = SOLIC_TIPOS.find((x) => x.id === s.tipo); return (
          <div key={s.id} className="px-3 py-2 rounded-md" style={{ border: `1px solid ${T.line}` }}>
            <div className="flex items-center justify-between gap-2 mb-1">
              <span className="text-sm font-medium" style={{ color: T.ink }}>{t?.icon} {t?.label}</span>
              <span className="text-xs f-mono px-2 py-0.5 rounded-full shrink-0" style={{ background: st.bg, color: st.color }}>{st.label}</span>
            </div>
            <div className="text-xs" style={{ color: T.inkSoft }}>{s.date} às {s.hora}{s.inicio && ` · início ${s.inicio} · ${s.dias} dia(s)`}</div>
            {s.resposta && <div className="text-xs mt-1.5 p-2 rounded" style={{ background: T.cyanSoft, color: T.ink }}><b>Resposta do RH:</b> {s.resposta}</div>}
          </div>
        ); })}</div>
      )}
    </div>
  );
}

function SolicitacoesPage({ list, onUpdate, onDelete }) {
  const months = [...new Set(list.map((s) => s.monthKey))].sort().reverse();
  const [month, setMonth] = useState(months[0] || currentMonthKey());
  const [tipoF, setTipoF] = useState(""), [statusF, setStatusF] = useState("");
  const [openId, setOpenId] = useState(null);
  let filtered = list.filter((s) => s.monthKey === month);
  if (tipoF) filtered = filtered.filter((s) => s.tipo === tipoF);
  if (statusF) filtered = filtered.filter((s) => s.status === statusF);
  filtered = filtered.slice().reverse();
  const abertas = list.filter((s) => s.monthKey === month && s.status === "aberta").length;
  const ferias = list.filter((s) => s.monthKey === month && s.tipo === "ferias").length;

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-4 no-print">
        <div><div className="text-xs f-mono uppercase tracking-wide mb-1" style={{ color: T.cyan }}>Atendimento ao colaborador</div><h1 className="f-display text-2xl font-semibold" style={{ color: T.ink }}>Solicitações e Dúvidas</h1></div>
        <div className="flex items-center gap-2">
          <select className={inputCls} style={{ ...inputStyle, minWidth: 160 }} value={month} onChange={(e) => setMonth(e.target.value)}>
            {(months.length ? months : [currentMonthKey()]).map((m) => <option key={m} value={m}>{formatMonthLabel(m)}</option>)}
          </select>
          <Btn variant="ghost" onClick={() => window.print()}><FileText size={15} />Imprimir</Btn>
        </div>
      </div>
      <div className="grid grid-cols-3 gap-3 mb-4">
        {[["Total do mês", filtered.length], ["Aguardando resposta", abertas], ["Pedidos de férias", ferias]].map(([l, v]) => (
          <div key={l} className="rounded-lg p-3" style={{ border: `1px solid ${T.line}`, background: T.paperRaised }}><div className="f-display text-lg font-semibold" style={{ color: T.ink }}>{v}</div><div className="text-xs" style={{ color: T.inkSoft }}>{l}</div></div>
        ))}
      </div>
      <div className="flex flex-wrap gap-2 items-end mb-4">
        <Field label="Tipo"><select className={inputCls} style={inputStyle} value={tipoF} onChange={(e) => setTipoF(e.target.value)}><option value="">Todos</option>{SOLIC_TIPOS.map((t) => <option key={t.id} value={t.id}>{t.label}</option>)}</select></Field>
        <Field label="Status"><select className={inputCls} style={inputStyle} value={statusF} onChange={(e) => setStatusF(e.target.value)}><option value="">Todos</option>{Object.entries(SOLIC_STATUS).map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}</select></Field>
      </div>
      {filtered.length === 0 ? <SectionCard><p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhuma solicitação neste período.</p></SectionCard> : filtered.map((s) => {
        const st = SOLIC_STATUS[s.status]; const t = SOLIC_TIPOS.find((x) => x.id === s.tipo);
        const isOpen = openId === s.id;
        return (
          <SectionCard key={s.id}>
            <button onClick={() => setOpenId(isOpen ? null : s.id)} className="w-full text-left">
              <div className="flex flex-wrap items-start justify-between gap-2 mb-1">
                <div><div className="text-sm font-semibold" style={{ color: T.ink }}>{t?.icon} {s.nome} <span style={{ color: T.inkSoft, fontWeight: 400 }}>{s.cargo && `· ${s.cargo}`}</span></div><div className="text-xs f-mono" style={{ color: T.inkSoft }}>{t?.label} · {s.date} às {s.hora}</div></div>
                <span className="text-xs f-mono px-2 py-0.5 rounded-full shrink-0" style={{ background: st.bg, color: st.color }}>{st.label}</span>
              </div>
              {s.inicio && <p className="text-sm" style={{ color: T.ink }}>Período: a partir de <b>{s.inicio}</b> · <b>{s.dias}</b> dia(s)</p>}
              {s.competencia && <p className="text-sm" style={{ color: T.ink }}>Competência: <b>{s.competencia}</b></p>}
              <p className="text-sm mt-1" style={{ color: T.inkSoft }}>{s.mensagem}</p>
            </button>
            {s.resposta && !isOpen && <div className="text-xs mt-2 p-2 rounded" style={{ background: T.cyanSoft, color: T.ink }}><b>Resposta:</b> {s.resposta}</div>}
            {isOpen && (
              <div className="mt-3 pt-3" style={{ borderTop: `1px solid ${T.line}` }}>
                <Field label="Resposta ao colaborador"><textarea className={inputCls} style={{ ...inputStyle, minHeight: 80 }} defaultValue={s.resposta} onBlur={(e) => onUpdate(s.id, { resposta: e.target.value })} /></Field>
                <div className="flex flex-wrap gap-2">
                  <Btn variant="ghost" onClick={() => onUpdate(s.id, { status: "analise" })}>Em análise</Btn>
                  <Btn variant="accent" onClick={() => onUpdate(s.id, { status: "respondida" })}>Marcar como respondida</Btn>
                  {s.tipo === "ferias" && <Btn variant="danger" onClick={() => onUpdate(s.id, { status: "recusada" })}>Recusar</Btn>}
                  <Btn variant="danger" onClick={() => onDelete(s.id)}>Excluir</Btn>
                </div>
              </div>
            )}
          </SectionCard>
        );
      })}
    </div>
  );
}

