/* JUSTIFICATIVA DE PONTO (colaborador envia, DP analisa)              */
/* ------------------------------------------------------------------ */
const MARCACAO_TIPOS = [
  { value: "entrada", label: "Entrada" }, { value: "saida_almoco", label: "Saída para Almoço" },
  { value: "volta_almoco", label: "Volta do Almoço" }, { value: "intervalo_entrada", label: "Intervalo — Entrada" },
  { value: "intervalo_saida", label: "Intervalo — Saída" }, { value: "saida", label: "Saída" },
];
const JUST_STATUS = {
  pendente: { label: "Aguardando análise", color: T.amber, bg: T.amberSoft },
  aprovada: { label: "Aprovada", color: T.success, bg: T.successSoft },
  recusada: { label: "Recusada", color: T.danger, bg: T.danger + "22" },
};
function formatCPF(v) {
  v = v.replace(/\D/g, "").slice(0, 11);
  if (v.length > 9) return v.replace(/(\d{3})(\d{3})(\d{3})(\d{1,2})/, "$1.$2.$3-$4");
  if (v.length > 6) return v.replace(/(\d{3})(\d{3})(\d{1,3})/, "$1.$2.$3");
  if (v.length > 3) return v.replace(/(\d{3})(\d{1,3})/, "$1.$2");
  return v;
}

function JustificativaForm({ colaboradores, defaultId, list, onSubmit }) {
  const [colaboradorId, setColaboradorId] = useState(defaultId || "");
  const [nome, setNome] = useState(colaboradores.find((c) => c.id === defaultId)?.nome || "");
  const [cpf, setCpf] = useState(""), [data, setData] = useState(""), [motivo, setMotivo] = useState("");
  const [marcacoes, setMarcacoes] = useState([{ tipo: "", horario: "" }]);
  const [sent, setSent] = useState(false);
  const today = new Date().toISOString().slice(0, 10);
  const mine = list.filter((j) => (colaboradorId ? j.colaboradorId === colaboradorId : j.nome === nome));

  const updateMarc = (idx, field, val) => setMarcacoes((m) => m.map((x, i) => (i === idx ? { ...x, [field]: val } : x)));
  const addMarc = () => setMarcacoes((m) => [...m, { tipo: "", horario: "" }]);
  const removeMarc = (idx) => setMarcacoes((m) => m.filter((_, i) => i !== idx));

  const submit = (e) => {
    e.preventDefault();
    const cpfLimpo = cpf.replace(/\D/g, "");
    if (cpfLimpo.length !== 11) return;
    if (!nome.trim() || !data || !motivo.trim()) return;
    if (marcacoes.some((m) => !m.tipo || !m.horario)) return;
    const now = new Date();
    onSubmit({ id: uid(), colaboradorId: colaboradorId || null, nome, cpf, data, marcacoes, motivo,
      monthKey: data.slice(0, 7), dateEnvio: now.toLocaleDateString("pt-BR"), horaEnvio: now.toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" }),
      status: "pendente", dpNota: "" });
    setSent(true); setCpf(""); setData(""); setMotivo(""); setMarcacoes([{ tipo: "", horario: "" }]);
  };

  return (
    <div>
      {sent ? (
        <div className="mb-5"><Confirm text="Justificativa enviada! O DP analisará em breve." /><Btn variant="ghost" className="mt-2" onClick={() => setSent(false)}>Enviar outra justificativa</Btn></div>
      ) : (
        <form onSubmit={submit} className="mb-5">
          <div className="text-xs p-2 rounded-md mb-3" style={{ background: T.cyanSoft, color: T.ink }}>ℹ️ Preencha quando esquecer ou não conseguir bater o ponto. O DP analisará sua solicitação.</div>
          {colaboradores.length > 0 && (
            <Field label="Selecione seu nome">
              <select className={inputCls} style={inputStyle} value={colaboradorId} onChange={(e) => { setColaboradorId(e.target.value); const c = colaboradores.find((x) => x.id === e.target.value); if (c) setNome(c.nome); }}>
                <option value="">Prefiro digitar manualmente</option>{colaboradores.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
            </Field>
          )}
          <Field label="Nome completo"><input required className={inputCls} style={inputStyle} value={nome} onChange={(e) => setNome(e.target.value)} /></Field>
          <div className="grid sm:grid-cols-2 gap-3">
            <Field label="CPF"><input required className={inputCls} style={inputStyle} placeholder="000.000.000-00" maxLength={14} value={cpf} onChange={(e) => setCpf(formatCPF(e.target.value))} /></Field>
            <Field label="Data da ocorrência"><input required type="date" max={today} className={inputCls} style={inputStyle} value={data} onChange={(e) => setData(e.target.value)} /></Field>
          </div>
          <Field label="Marcações esquecidas">
            <div className="space-y-2">
              {marcacoes.map((m, idx) => (
                <div key={idx} className="rounded-lg p-3" style={{ border: `1px solid ${T.line}`, background: T.paper }}>
                  <div className="flex justify-between items-center mb-2"><span className="text-xs f-mono" style={{ color: T.cyan }}>📌 Marcação {idx + 1}</span>{marcacoes.length > 1 && <button type="button" onClick={() => removeMarc(idx)} className="text-xs" style={{ color: T.danger }}>✕ Remover</button>}</div>
                  <div className="grid sm:grid-cols-2 gap-2">
                    <select required className={inputCls} style={inputStyle} value={m.tipo} onChange={(e) => updateMarc(idx, "tipo", e.target.value)}><option value="">Selecione o tipo</option>{MARCACAO_TIPOS.map((t) => <option key={t.value} value={t.value}>{t.label}</option>)}</select>
                    <input required type="time" className={inputCls} style={inputStyle} value={m.horario} onChange={(e) => updateMarc(idx, "horario", e.target.value)} />
                  </div>
                </div>
              ))}
            </div>
            <Btn type="button" variant="ghost" className="w-full justify-center mt-2" onClick={addMarc}>➕ Adicionar outro horário esquecido</Btn>
          </Field>
          <Field label="Motivo"><textarea required className={inputCls} style={{ ...inputStyle, minHeight: 80 }} placeholder="Ex: sistema fora do ar, esquecimento..." value={motivo} onChange={(e) => setMotivo(e.target.value)} /></Field>
          <Btn type="submit" variant="accent" className="w-full justify-center">✅ Enviar justificativa</Btn>
        </form>
      )}
      <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Minhas justificativas</div>
      {mine.length === 0 ? <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhuma justificativa enviada.</p> : (
        <div className="space-y-1.5">{mine.slice().reverse().map((j) => { const st = JUST_STATUS[j.status]; return (
          <div key={j.id} className="px-3 py-2 rounded-md" style={{ border: `1px solid ${T.line}` }}>
            <div className="flex justify-between items-center gap-2"><span className="text-sm font-medium" style={{ color: T.ink }}>{j.data}</span><span className="text-xs f-mono px-2 py-0.5 rounded-full" style={{ background: st.bg, color: st.color }}>{st.label}</span></div>
            <div className="text-xs" style={{ color: T.inkSoft }}>{j.marcacoes.map((m) => MARCACAO_TIPOS.find((t) => t.value === m.tipo)?.label + " " + m.horario).join(" · ")}</div>
            {j.dpNota && <div className="text-xs mt-1 p-1.5 rounded" style={{ background: T.cyanSoft, color: T.ink }}><b>DP:</b> {j.dpNota}</div>}
          </div>
        ); })}</div>
      )}
    </div>
  );
}

function JustificativasPage({ list, onUpdate, onDelete }) {
  const months = [...new Set(list.map((j) => j.monthKey))].sort().reverse();
  const [month, setMonth] = useState(months[0] || currentMonthKey());
  const [statusF, setStatusF] = useState("");
  let filtered = list.filter((j) => j.monthKey === month);
  if (statusF) filtered = filtered.filter((j) => j.status === statusF);
  filtered = filtered.slice().reverse();
  const pendentes = list.filter((j) => j.monthKey === month && j.status === "pendente").length;

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-4 no-print">
        <div><div className="text-xs f-mono uppercase tracking-wide mb-1" style={{ color: T.cyan }}>DP · Ponto</div><h1 className="f-display text-2xl font-semibold" style={{ color: T.ink }}>Justificativas de Ponto</h1></div>
        <div className="flex items-center gap-2">
          <select className={inputCls} style={{ ...inputStyle, minWidth: 160 }} value={month} onChange={(e) => setMonth(e.target.value)}>{(months.length ? months : [currentMonthKey()]).map((m) => <option key={m} value={m}>{formatMonthLabel(m)}</option>)}</select>
          <Btn variant="ghost" onClick={() => window.print()}><FileText size={15} />Imprimir</Btn>
        </div>
      </div>
      <div className="grid grid-cols-2 gap-3 mb-4">
        <div className="rounded-lg p-3" style={{ border: `1px solid ${T.line}`, background: T.paperRaised }}><div className="f-display text-lg font-semibold" style={{ color: T.ink }}>{filtered.length}</div><div className="text-xs" style={{ color: T.inkSoft }}>Total do mês</div></div>
        <div className="rounded-lg p-3" style={{ border: `1px solid ${T.line}`, background: T.paperRaised }}><div className="f-display text-lg font-semibold" style={{ color: T.amber }}>{pendentes}</div><div className="text-xs" style={{ color: T.inkSoft }}>Aguardando análise</div></div>
      </div>
      <div className="mb-4" style={{ maxWidth: 220 }}><Field label="Filtrar por status"><select className={inputCls} style={inputStyle} value={statusF} onChange={(e) => setStatusF(e.target.value)}><option value="">Todos</option>{Object.entries(JUST_STATUS).map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}</select></Field></div>
      {filtered.length === 0 ? <SectionCard><p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhuma justificativa neste período.</p></SectionCard> : filtered.map((j) => {
        const st = JUST_STATUS[j.status];
        return (
          <SectionCard key={j.id}>
            <div className="flex flex-wrap items-start justify-between gap-2 mb-2">
              <div><div className="text-sm font-semibold" style={{ color: T.ink }}>{j.nome}</div><div className="text-xs f-mono" style={{ color: T.inkSoft }}>CPF {j.cpf} · Ocorrência em {j.data} · enviado {j.dateEnvio} às {j.horaEnvio}</div></div>
              <span className="text-xs f-mono px-2 py-0.5 rounded-full" style={{ background: st.bg, color: st.color }}>{st.label}</span>
            </div>
            <div className="text-sm mb-2">{j.marcacoes.map((m, i) => <div key={i}>📌 {MARCACAO_TIPOS.find((t) => t.value === m.tipo)?.label}: <b>{m.horario}</b></div>)}</div>
            <p className="text-sm mb-2" style={{ color: T.inkSoft }}>Motivo: {j.motivo}</p>
            {j.status === "pendente" && (
              <div className="flex flex-wrap gap-2 items-end mt-2">
                <div className="flex-1" style={{ minWidth: 180 }}><Field label="Nota do DP (opcional)"><input className={inputCls} style={inputStyle} defaultValue="" onBlur={(e) => onUpdate(j.id, { dpNota: e.target.value })} /></Field></div>
                <Btn variant="accent" onClick={() => onUpdate(j.id, { status: "aprovada" })}>Aprovar</Btn>
                <Btn variant="danger" onClick={() => onUpdate(j.id, { status: "recusada" })}>Recusar</Btn>
              </div>
            )}
            {j.status !== "pendente" && <Btn variant="danger" onClick={() => onDelete(j.id)}>Excluir</Btn>}
          </SectionCard>
        );
      })}
    </div>
  );
}

function MeuDesempenho({ pd, submissions, myColaboradorId }) {
  const emp = pd.colaboradores.find((c) => c.id === myColaboradorId);
  if (!emp) return <p className="text-sm italic" style={{ color: T.inkSoft }}>Para ver seu desempenho, volte ao início e entre selecionando seu nome na lista de colaboradores.</p>;

  const evals = submissions.leaderEvaluations.filter((ev) => ev.colaboradorId === emp.id);
  const evalAvg = evals.length ? +(evals.reduce((a, b) => a + b.media, 0) / evals.length).toFixed(2) : null;
  const tc = pd.trainingCompletions[emp.id] || {};
  const trainingScores = Object.values(tc).map((v) => (v && typeof v === "object" ? v.score : null)).filter((v) => typeof v === "number");
  const avgTrainingScore = trainingScores.length ? Math.round(trainingScores.reduce((a, b) => a + b, 0) / trainingScores.length) : null;
  const kit = pd.integrationChecklist[emp.id] || {};
  const kitPct = Math.round((INTEGRATION_KIT_ITEMS.filter((_, idx) => kit[idx]).length / INTEGRATION_KIT_ITEMS.length) * 100);
  const assignment = pd.onboardingAssignments[emp.id];
  const template = assignment && pd.onboardingTemplates.find((t) => t.id === assignment.templateId);
  const allTasks = template ? Object.values(template.tasks).flat() : [];
  const onbPct = allTasks.length ? Math.round((allTasks.filter((t) => assignment?.progress?.[t.id]).length / allTasks.length) * 100) : null;

  return (
    <div>
      <div className="grid grid-cols-2 gap-2 mb-5">
        <MiniStat label="Média avaliações" value={evalAvg ?? "—"} />
        <MiniStat label="Média treinamentos" value={avgTrainingScore ?? "—"} />
      </div>

      <div className="mb-5">
        <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Kit de Integração</div>
        <ProgressBar pct={kitPct} color={kitPct === 100 ? T.success : T.amber} />
        <p className="text-xs mt-1" style={{ color: T.inkSoft }}>{kitPct}% concluído</p>
      </div>

      {template && (
        <div className="mb-5">
          <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Integração (Onboarding)</div>
          <ProgressBar pct={onbPct} color={onbPct === 100 ? T.success : T.amber} />
          <p className="text-xs mt-1" style={{ color: T.inkSoft }}>{onbPct}% do plano de {template.cargo}</p>
        </div>
      )}

      <div className="mb-5">
        <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Treinamentos</div>
        {pd.trainings.length === 0 ? <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhum treinamento disponível.</p> : (
          <div className="space-y-1.5">{pd.trainings.map((tr) => {
            const rec = tc[tr.id]; const done = rec && typeof rec === "object" ? rec.done : !!rec; const score = rec && typeof rec === "object" ? rec.score : null;
            return (
              <div key={tr.id} className="flex items-center justify-between text-sm px-2.5 py-1.5 rounded" style={{ background: T.paper }}>
                <span>{done ? <CheckCircle2 size={14} style={{ color: T.success, display: "inline", verticalAlign: -2, marginRight: 6 }} /> : <Circle size={14} style={{ color: T.inkSoft, display: "inline", verticalAlign: -2, marginRight: 6 }} />}{tr.titulo}</span>
                <span className="f-mono text-xs" style={{ color: T.inkSoft }}>{done ? (typeof score === "number" ? `${score}%` : "concluído") : "pendente"}</span>
              </div>
            );
          })}</div>
        )}
      </div>

      <div>
        <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Avaliações de desempenho</div>
        {evals.length === 0 ? <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhuma avaliação registrada ainda.</p> : (
          <>
            {evals.length > 1 && <div className="h-40 mb-2"><ResponsiveContainer width="100%" height="100%"><LineChart data={evals.map((ev) => ({ data: ev.date, media: ev.media }))}><CartesianGrid strokeDasharray="3 3" stroke={T.line} /><XAxis dataKey="data" tick={{ fontSize: 10 }} /><YAxis domain={[0, 5]} tick={{ fontSize: 10 }} /><Tooltip /><Line type="monotone" dataKey="media" stroke={T.cyan} strokeWidth={2} /></LineChart></ResponsiveContainer></div>}
            <div className="space-y-1.5">{evals.slice().reverse().map((ev) => (
              <div key={ev.id} className="text-sm px-3 py-2 rounded-md" style={{ border: `1px solid ${T.line}` }}>
                <div className="flex justify-between text-xs f-mono mb-1" style={{ color: T.inkSoft }}><span>{ev.date}</span><span>média {ev.media}</span></div>
                {ev.pontosPositivos && <p><b>Pontos positivos:</b> {ev.pontosPositivos}</p>}
                {ev.pontosMelhoria && <p><b>Pontos de melhoria:</b> {ev.pontosMelhoria}</p>}
              </div>
            ))}</div>
          </>
        )}
      </div>
    </div>
  );
}

function EmployeePortal({ pd, submissions, myColaboradorId, addDiagnostico, addFeedback, ackEthics, ackMuv, onCompleteTraining, addAtestado, adiantamentos, addAdiantamento, solicitacoes, addSolicitacao, justificativas, addJustificativa, odonto, addOdonto }) {
  const colaboradoresAtivos = pd.colaboradores.filter((c) => (c.status || "Ativo") === "Ativo");
  const [section, setSection] = useState(null);
  const ALL_SECTIONS = {
    desempenho: { label: "Meu Desempenho", icon: TrendingUp },
    diuvintem: { label: "Diu Vintém", icon: Coins },
    treinamentos: { label: "Treinamentos", icon: GraduationCap },
    diagnostico: { label: "Diagnóstico Organizacional", icon: FileText },
    feedback: { label: "Canal de Feedback", icon: MessagesSquare },
    muv: { label: "Missão, Visão e Valores", icon: Compass },
    etica: { label: "Código de Ética", icon: ShieldCheck },
    regulamento: { label: "Regulamento Interno", icon: BookOpen },
    convencao: { label: "Convenção Coletiva", icon: FileText },
    atestado: { label: "Envio de Atestados", icon: Paperclip },
    adiantamento: { label: "Adiantamento de Salário", icon: Wallet },
    odonto: { label: "Plano Odontológico", icon: HeartPulse },
    solicitacao: { label: "Férias e Dúvidas RH", icon: HelpCircle },
    justificativa: { label: "Justificativa de Ponto", icon: Clock },
  };
  const GROUPS = [
    { label: "Meu Desenvolvimento", items: ["desempenho", "diuvintem", "treinamentos"] },
    { label: "Sua Opinião", items: ["diagnostico", "feedback"] },
    { label: "Institucional", items: ["muv", "etica", "regulamento", "convencao"] },
    { label: "Solicitações e Benefícios", items: ["atestado", "adiantamento", "odonto", "solicitacao", "justificativa"] },
  ];

  if (section) {
    const s = ALL_SECTIONS[section];
    return (
      <div className="max-w-2xl mx-auto">
        <button onClick={() => setSection(null)} className="text-xs f-mono mb-4" style={{ color: T.inkSoft }}>&larr; Voltar ao menu</button>
        <FormCard title={s.label} icon={s.icon}>
          {section === "desempenho" && <MeuDesempenho pd={pd} submissions={submissions} myColaboradorId={myColaboradorId} />}
          {section === "diuvintem" && <DiuVintemColaborador pd={pd} lancamentos={pd.diuVintemLancamentos} resgates={pd.diuVintemResgates} myColaboradorId={myColaboradorId} />}
          {section === "treinamentos" && <TreinamentosPortal trainings={pd.trainings} myColaboradorId={myColaboradorId} myCompletions={pd.trainingCompletions[myColaboradorId] || {}} onComplete={onCompleteTraining} />}
          {section === "diagnostico" && <DiagnosticoForm colaboradores={colaboradoresAtivos} defaultId={myColaboradorId} onSubmit={addDiagnostico} />}
          {section === "feedback" && <FeedbackForm colaboradores={colaboradoresAtivos} defaultId={myColaboradorId} onSubmit={addFeedback} />}
          {section === "muv" && (
            <>
              <div className="text-sm mb-3" style={{ color: T.inkSoft }}><p className="mb-2"><b>Missão:</b> {pd.culture.missao}</p><p className="mb-2"><b>Visão:</b> {pd.culture.visao}</p><p><b>Valores:</b> {pd.culture.valores.join(" · ")}</p></div>
              <MuvAckForm colaboradores={colaboradoresAtivos} defaultId={myColaboradorId} already={submissions.muvAck} onSubmit={ackMuv} />
            </>
          )}
          {section === "etica" && (
            <>
              <div className="text-sm p-3 rounded-md mb-3 whitespace-pre-wrap max-h-56 overflow-y-auto scrollbar-thin" style={{ background: T.paper, border: `1px solid ${T.line}`, color: T.inkSoft }}>{pd.ethicsText}</div>
              <EthicsAckForm colaboradores={colaboradoresAtivos} defaultId={myColaboradorId} already={submissions.ethicsAck} onSubmit={ackEthics} />
            </>
          )}
          {section === "regulamento" && <RegulamentoView />}
          {section === "convencao" && <ConvencaoColetivaView doc={pd.convencaoColetiva} />}
          {section === "atestado" && <AtestadoForm colaboradores={colaboradoresAtivos} defaultId={myColaboradorId} onSubmit={addAtestado} />}
          {section === "adiantamento" && <AdiantamentoForm colaboradores={colaboradoresAtivos} defaultId={myColaboradorId} list={adiantamentos} onSubmit={addAdiantamento} />}
          {section === "odonto" && <OdontoForm colaboradores={colaboradoresAtivos} defaultId={myColaboradorId} list={odonto} onSubmit={addOdonto} />}
          {section === "solicitacao" && <SolicitacaoForm colaboradores={colaboradoresAtivos} defaultId={myColaboradorId} list={solicitacoes} onSubmit={addSolicitacao} />}
          {section === "justificativa" && <JustificativaForm colaboradores={colaboradoresAtivos} defaultId={myColaboradorId} list={justificativas} onSubmit={addJustificativa} />}
        </FormCard>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto">
      <div className="mb-6"><div className="text-xs f-mono uppercase tracking-wide mb-1" style={{ color: T.cyan }}>Portal do Colaborador</div><h1 className="f-display text-2xl font-semibold" style={{ color: T.ink }}>Formulários e pesquisas</h1></div>
      {GROUPS.map((g) => (
        <div key={g.label} className="mb-5">
          <div className="text-xs f-mono uppercase tracking-wide mb-2 px-1" style={{ color: T.cyan }}>{g.label}</div>
          <div className="space-y-2">
            {g.items.map((id) => { const s = ALL_SECTIONS[id]; return (
              <button key={id} onClick={() => setSection(id)} className="w-full flex items-center gap-3 text-left px-4 py-3.5 rounded-xl transition-colors hover:opacity-90" style={{ border: `1px solid ${T.line}`, background: T.paperRaised }}>
                <s.icon size={19} style={{ color: T.cyan }} />
                <span className="text-sm font-medium flex-1" style={{ color: T.ink }}>{s.label}</span>
                <ChevronRight size={16} style={{ color: T.inkSoft }} />
              </button>
            ); })}
          </div>
        </div>
      ))}
    </div>
  );
}

