function parseBR(d) { if (!d) return null; const [dd, mm, yy] = d.split("/"); return new Date(Number(yy), Number(mm) - 1, Number(dd)); }
function inRange(dateBR, from, to) { const d = parseBR(dateBR); if (!d) return true; if (from && d < new Date(from)) return false; if (to && d > new Date(to + "T23:59:59")) return false; return true; }

function WellbeingChannel({ onSubmit, onBack }) {
  const [tipos, setTipos] = useState([]);
  const [severidade, setSeveridade] = useState(null);
  const [descricao, setDescricao] = useState(""), [nome, setNome] = useState(""), [envolvido, setEnvolvido] = useState(""), [cargo, setCargo] = useState("");
  const [protocolo, setProtocolo] = useState(null);
  const toggleTipo = (id) => setTipos((t) => (t.includes(id) ? t.filter((x) => x !== id) : [...t, id]));
  const submit = (e) => {
    e.preventDefault();
    if (!descricao.trim()) return;
    const proto = genProtocol();
    onSubmit({ id: uid(), protocolo: proto, date: new Date().toLocaleDateString("pt-BR"), tipos, severidade, descricao, nome, envolvido, cargo, status: "aberto", notaRH: "", acaoCorretiva: "" });
    setProtocolo(proto);
  };
  if (protocolo) {
    return (
      <div className="min-h-screen flex items-center justify-center px-4 grid-paper" style={{ background: T.paper }}>
        <Frame className="rounded-2xl p-8 max-w-md w-full text-center" style={{ background: T.paperRaised, border: `1px solid ${T.line}` }}>
          <div className="text-4xl mb-2">✅</div>
          <p className="text-sm font-medium mb-3" style={{ color: T.success }}>Relato recebido com sucesso!</p>
          <div className="f-mono text-lg font-semibold mb-3" style={{ color: T.ink }}>{protocolo}</div>
          <p className="text-xs mb-6" style={{ color: T.inkSoft }}>Guarde este número de protocolo. O RH iniciará a apuração em até 24 horas. Obrigado por confiar no canal.</p>
          <Btn variant="accent" className="w-full justify-center" onClick={() => { setProtocolo(null); setTipos([]); setSeveridade(null); setDescricao(""); setNome(""); setEnvolvido(""); setCargo(""); }}>Enviar outro relato</Btn>
          <button onClick={onBack} className="text-xs f-mono mt-4" style={{ color: T.inkSoft }}>&larr; Voltar</button>
        </Frame>
      </div>
    );
  }
  return (
    <div className="min-h-screen px-4 py-8 grid-paper" style={{ background: T.paper }}>
      <div className="max-w-xl mx-auto">
        <button onClick={onBack} className="text-xs f-mono mb-4" style={{ color: T.inkSoft }}>&larr; Voltar</button>
        <Frame className="rounded-2xl p-6 mb-4" style={{ background: T.paperRaised, border: `1px solid ${T.line}` }}>
          <h1 className="f-display text-xl font-semibold mb-1" style={{ color: T.ink }}>Canal de Saúde e Bem-Estar</h1>
          <p className="text-sm mb-6" style={{ color: T.inkSoft }}>Selecione a situação, descreva o ocorrido e envie. Você receberá um número de protocolo para acompanhamento. Este canal é 100% anônimo — não é necessário login.</p>
          <form onSubmit={submit}>
            <Field label="Tipo de situação (selecione uma ou mais)">
              <div className="grid sm:grid-cols-2 gap-2">
                {WELLBEING_TYPES.map((t) => (
                  <button key={t.id} type="button" onClick={() => toggleTipo(t.id)} className="text-left px-3 py-2 rounded-lg" style={{ border: `1px solid ${tipos.includes(t.id) ? T.cyan : T.line}`, background: tipos.includes(t.id) ? T.cyanSoft : "transparent" }}>
                    <div className="text-sm">{t.icon} <b>{t.label}</b></div><div className="text-xs" style={{ color: T.inkSoft }}>{t.desc}</div>
                  </button>
                ))}
              </div>
            </Field>
            <Field label="Como está afetando você?">
              <div className="grid sm:grid-cols-3 gap-2">
                {WELLBEING_SEVERITY.map((s) => (
                  <button key={s.id} type="button" onClick={() => setSeveridade(s.id)} className="text-center px-2 py-2 rounded-lg" style={{ border: `2px solid ${severidade === s.id ? s.color : T.line}`, background: severidade === s.id ? s.color + "22" : "transparent" }}>
                    <div className="text-sm font-medium" style={{ color: s.color }}>{s.label}</div><div className="text-[10px]" style={{ color: T.inkSoft }}>{s.desc}</div>
                  </button>
                ))}
              </div>
            </Field>
            <Field label="Conte o que aconteceu"><textarea required className={inputCls} style={{ ...inputStyle, minHeight: 100 }} placeholder="Descreva a situação: quando aconteceu, onde, com quem, e como afetou você ou a equipe..." value={descricao} onChange={(e) => setDescricao(e.target.value)} /></Field>
            <div className="grid sm:grid-cols-2 gap-3">
              <Field label="Seu nome (opcional)"><input className={inputCls} style={inputStyle} placeholder="Deixe em branco para ficar anônimo" value={nome} onChange={(e) => setNome(e.target.value)} /></Field>
              <Field label="Pessoa ou setor envolvido (opcional)"><input className={inputCls} style={inputStyle} value={envolvido} onChange={(e) => setEnvolvido(e.target.value)} /></Field>
            </div>
            <Field label="Seu cargo (opcional)">
              <select className={inputCls} style={inputStyle} value={cargo} onChange={(e) => setCargo(e.target.value)}><option value="">Prefiro não informar</option>{ILPI_CARGOS.map((c) => <option key={c}>{c}</option>)}</select>
            </Field>
            <Btn type="submit" variant="accent" className="w-full justify-center">Enviar relato com sigilo total</Btn>
            <p className="text-xs text-center mt-3" style={{ color: T.inkSoft }}>Seu relato é criptografado e acessado apenas pelo RH. Garantia de não retaliação institucional.</p>
          </form>
        </Frame>
      </div>
    </div>
  );
}

function WellbeingDashboardTab({ submissions, pd, setClima }) {
  const [from, setFrom] = useState(""), [to, setTo] = useState("");
  const relatos = submissions.wellbeing.filter((r) => inRange(r.date, from, to));
  const manual = submissions.wellbeingManual;
  const somaManual = (key) => manual.reduce((a, m) => a + (Number(m[key]) || 0), 0);
  const resolvidos = relatos.filter((r) => r.status === "resolvido").length + somaManual("resolvidos");
  const acolhimentos = relatos.length + somaManual("acolhimentos");
  const afastamentos = somaManual("afastamentos");
  const desligamentos = somaManual("desligamentos");
  const headcount = somaManual("headcount");
  const turnover = headcount > 0 ? ((desligamentos / headcount) * 100).toFixed(1) : "—";
  const emApuracao = relatos.filter((r) => r.status === "apurando").length;
  const byTipo = {};
  relatos.forEach((r) => r.tipos.forEach((tid) => { byTipo[tid] = (byTipo[tid] || 0) + 1; }));
  const [editing, setEditing] = useState(false);
  const [climaDraft, setClimaDraft] = useState(pd.wellbeingClima || "");
  const metrics = [
    { label: "Acolhimentos", value: acolhimentos, sub: "Individuais no período" },
    { label: "Relatos recebidos", value: relatos.length, sub: "Via canal digital" },
    { label: "Casos resolvidos", value: resolvidos, sub: "Apurados e encerrados" },
    { label: "Afastamentos CID-F", value: afastamentos, sub: "Transtornos mentais" },
    { label: "Turnover voluntário", value: `${turnover}${headcount > 0 ? "%" : ""}`, sub: `${desligamentos} deslig. / ${headcount || "—"} colab.` },
    { label: "Em apuração", value: emApuracao, sub: "Casos abertos ativos" },
  ];
  return (
    <div>
      <div className="flex flex-wrap gap-2 items-end mb-4">
        <Field label="De"><input type="date" className={inputCls} style={inputStyle} value={from} onChange={(e) => setFrom(e.target.value)} /></Field>
        <Field label="Até"><input type="date" className={inputCls} style={inputStyle} value={to} onChange={(e) => setTo(e.target.value)} /></Field>
      </div>
      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mb-4">
        {metrics.map((m) => (
          <div key={m.label} className="rounded-lg p-3" style={{ border: `1px solid ${T.line}`, background: T.paperRaised }}>
            <div className="f-display text-xl font-semibold" style={{ color: T.ink }}>{m.value}</div>
            <div className="text-xs font-medium" style={{ color: T.inkSoft }}>{m.label}</div>
            <div className="text-[10px]" style={{ color: T.inkSoft }}>{m.sub}</div>
          </div>
        ))}
      </div>
      <SectionCard>
        <div className="flex justify-between items-center mb-2"><div className="text-xs f-mono uppercase tracking-wide" style={{ color: T.cyan }}>Status do clima / ações corretivas</div>{!editing && <Btn variant="ghost" onClick={() => { setClimaDraft(pd.wellbeingClima || ""); setEditing(true); }}>Editar</Btn>}</div>
        {editing ? (
          <div>
            <textarea className={inputCls} style={{ ...inputStyle, minHeight: 90 }} value={climaDraft} onChange={(e) => setClimaDraft(e.target.value)} />
            <div className="flex gap-2 mt-2"><Btn variant="accent" onClick={() => { setClima(climaDraft); setEditing(false); }}>Salvar</Btn><Btn variant="ghost" onClick={() => setEditing(false)}>Cancelar</Btn></div>
          </div>
        ) : <p className="text-sm" style={{ color: T.ink }}>{pd.wellbeingClima || (relatos.length === 0 ? "Nenhum relato registrado no período. Monitoramento contínuo ativo." : `${relatos.length} relato(s) recebido(s). Planos de ação iniciados conforme protocolo.`)}</p>}
      </SectionCard>
      {Object.keys(byTipo).length > 0 && (
        <SectionCard>
          <div className="text-xs f-mono uppercase tracking-wide mb-3" style={{ color: T.cyan }}>Relatos por tipo de situação</div>
          {Object.entries(byTipo).sort((a, b) => b[1] - a[1]).map(([k, v]) => {
            const t = WELLBEING_TYPES.find((x) => x.id === k); const pct = Math.round((v / relatos.length) * 100);
            return (
              <div key={k} className="mb-2">
                <div className="flex justify-between text-xs mb-1"><span>{t ? `${t.icon} ${t.label}` : k}</span><span style={{ color: T.inkSoft }}>{v} ({pct}%)</span></div>
                <ProgressBar pct={pct} />
              </div>
            );
          })}
        </SectionCard>
      )}
    </div>
  );
}

function WellbeingRelatoDetail({ r, onSave, onDelete, onClose }) {
  const [notaRH, setNotaRH] = useState(r.notaRH || ""), [acaoCorretiva, setAcaoCorretiva] = useState(r.acaoCorretiva || ""), [status, setStatus] = useState(r.status || "aberto");
  const steps = [...new Set(r.tipos.flatMap((t) => WELLBEING_PLANS[t] || WELLBEING_PLANS.outro))].slice(0, 8);
  const sev = WELLBEING_SEVERITY.find((s) => s.id === r.severidade);
  return (
    <SectionCard>
      <div className="flex justify-between items-start mb-2">
        <div><div className="f-mono text-sm font-semibold" style={{ color: T.ink }}>{r.protocolo}</div><div className="text-xs" style={{ color: T.inkSoft }}>{r.date} · {r.cargo || "cargo não informado"} · {r.nome || "Anônimo"}{r.envolvido && ` · Envolvido: ${r.envolvido}`}</div></div>
        <button onClick={onClose} className="text-xs f-mono" style={{ color: T.inkSoft }}>Fechar ✕</button>
      </div>
      <div className="flex flex-wrap gap-1.5 mb-3">{r.tipos.map((tid) => { const t = WELLBEING_TYPES.find((x) => x.id === tid); return t ? <span key={tid} className="text-xs px-2 py-0.5 rounded-full" style={{ background: T.cyanSoft, color: T.cyan }}>{t.icon} {t.label}</span> : null; })}{sev && <span className="text-xs px-2 py-0.5 rounded-full" style={{ background: sev.color + "22", color: sev.color }}>{sev.label}</span>}</div>
      <div className="rounded-lg p-3 mb-3" style={{ background: T.paper }}><div className="text-xs f-mono uppercase mb-1" style={{ color: T.inkSoft }}>Relato</div><p className="text-sm">{r.descricao}</p></div>
      <div className="rounded-lg p-3 mb-3" style={{ background: T.cyanSoft }}>
        <div className="text-xs f-mono uppercase mb-2" style={{ color: T.cyan }}>Plano de ação sugerido</div>
        {steps.map((s, i) => <div key={i} className="text-sm mb-1"><b>{i + 1}.</b> {s}</div>)}
      </div>
      <Field label="Nota interna do RH"><textarea className={inputCls} style={{ ...inputStyle, minHeight: 70 }} placeholder="Observações internas sobre este caso..." value={notaRH} onChange={(e) => setNotaRH(e.target.value)} /></Field>
      <Field label="Ação corretiva adotada"><textarea className={inputCls} style={{ ...inputStyle, minHeight: 70 }} placeholder="Descreva a ação corretiva tomada..." value={acaoCorretiva} onChange={(e) => setAcaoCorretiva(e.target.value)} /></Field>
      <Field label="Status do caso">
        <div className="flex gap-2">{WELLBEING_STATUS.map((s) => <button key={s.id} type="button" onClick={() => setStatus(s.id)} className="px-3 py-1.5 rounded-md text-sm" style={{ border: `1px solid ${status === s.id ? T.cyan : T.line}`, background: status === s.id ? T.cyanSoft : "transparent", color: status === s.id ? T.cyan : T.ink }}>{s.label}</button>)}</div>
      </Field>
      <div className="flex flex-wrap gap-2">
        <Btn variant="accent" onClick={() => onSave(r.id, { notaRH, acaoCorretiva, status })}>Salvar alterações</Btn>
        <Btn variant="danger" onClick={() => onDelete(r.id)}>Apagar relato</Btn>
      </div>
    </SectionCard>
  );
}

function WellbeingRelatosTab({ submissions, onSave, onDelete }) {
  const [from, setFrom] = useState(""), [to, setTo] = useState(""), [statusF, setStatusF] = useState(""), [tipoF, setTipoF] = useState("");
  const [openId, setOpenId] = useState(null);
  let list = submissions.wellbeing.filter((r) => inRange(r.date, from, to));
  if (statusF) list = list.filter((r) => r.status === statusF);
  if (tipoF) list = list.filter((r) => r.tipos.includes(tipoF));
  list = list.slice().reverse();
  const open = list.find((r) => r.id === openId);
  return (
    <div>
      <div className="text-xs p-2 rounded-md mb-3" style={{ background: T.amberSoft, color: T.amber }}>🔒 Conteúdo sigiloso — acesso restrito ao RH. SLA: apuração iniciada em até 24h do recebimento.</div>
      <div className="flex flex-wrap gap-2 items-end mb-4">
        <Field label="De"><input type="date" className={inputCls} style={inputStyle} value={from} onChange={(e) => setFrom(e.target.value)} /></Field>
        <Field label="Até"><input type="date" className={inputCls} style={inputStyle} value={to} onChange={(e) => setTo(e.target.value)} /></Field>
        <Field label="Status"><select className={inputCls} style={inputStyle} value={statusF} onChange={(e) => setStatusF(e.target.value)}><option value="">Todos</option>{WELLBEING_STATUS.map((s) => <option key={s.id} value={s.id}>{s.label}</option>)}</select></Field>
        <Field label="Tipo"><select className={inputCls} style={inputStyle} value={tipoF} onChange={(e) => setTipoF(e.target.value)}><option value="">Todos</option>{WELLBEING_TYPES.map((t) => <option key={t.id} value={t.id}>{t.label}</option>)}</select></Field>
      </div>
      {open && <WellbeingRelatoDetail r={open} onSave={(id, patch) => onSave(id, patch)} onDelete={(id) => { onDelete(id); setOpenId(null); }} onClose={() => setOpenId(null)} />}
      {list.length === 0 ? <SectionCard><p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhum relato encontrado para os filtros selecionados.</p></SectionCard> : list.map((r) => {
        const sev = WELLBEING_SEVERITY.find((s) => s.id === r.severidade);
        const st = WELLBEING_STATUS.find((s) => s.id === r.status) || WELLBEING_STATUS[0];
        return (
          <button key={r.id} onClick={() => setOpenId(r.id === openId ? null : r.id)} className="w-full text-left rounded-lg p-3 mb-2" style={{ border: `1px solid ${T.line}`, background: T.paperRaised }}>
            <div className="flex flex-wrap items-center justify-between gap-2 mb-1">
              <span className="text-sm font-medium" style={{ color: T.ink }}>{r.tipos.map((tid) => WELLBEING_TYPES.find((x) => x.id === tid)?.label).filter(Boolean).join(" · ") || "Situação"}</span>
              <span className="f-mono text-xs" style={{ color: T.inkSoft }}>{r.protocolo}</span>
            </div>
            <div className="text-xs mb-1" style={{ color: T.inkSoft }}>{r.date} · {r.cargo || "—"}</div>
            <p className="text-xs mb-2" style={{ color: T.inkSoft }}>{(r.descricao || "").slice(0, 120)}{(r.descricao || "").length > 120 ? "…" : ""}</p>
            <div className="flex flex-wrap gap-1.5">
              <span className="text-[10px] px-2 py-0.5 rounded-full" style={{ background: T.cyanSoft, color: T.cyan }}>{st.label}</span>
              {sev && <span className="text-[10px] px-2 py-0.5 rounded-full" style={{ background: sev.color + "22", color: sev.color }}>{sev.label}</span>}
              <span className="text-[10px] px-2 py-0.5 rounded-full" style={{ background: T.paper, color: T.inkSoft }}>{r.nome || "Anônimo"}</span>
            </div>
          </button>
        );
      })}
    </div>
  );
}

function WellbeingManualTab({ submissions, onAdd, onDelete }) {
  const empty = { fromDate: "", toDate: "", acolhimentos: "", resolvidos: "", afastamentos: "", desligamentos: "", headcount: "", clima: "" };
  const [form, setForm] = useState(empty);
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));
  const submit = (e) => { e.preventDefault(); if (!form.fromDate || !form.toDate) return; onAdd({ id: uid(), ...form }); setForm(empty); };
  return (
    <div>
      <SectionCard>
        <div className="text-xs f-mono uppercase tracking-wide mb-1" style={{ color: T.cyan }}>Inserir dados manualmente</div>
        <p className="text-xs mb-3" style={{ color: T.inkSoft }}>Registre acolhimentos presenciais, afastamentos e turnover que chegaram por outros canais (WhatsApp, e-mail, urna física).</p>
        <form onSubmit={submit}>
          <div className="grid sm:grid-cols-2 gap-3">
            <Field label="Data início"><input required type="date" className={inputCls} style={inputStyle} value={form.fromDate} onChange={set("fromDate")} /></Field>
            <Field label="Data fim"><input required type="date" className={inputCls} style={inputStyle} value={form.toDate} onChange={set("toDate")} /></Field>
          </div>
          <div className="grid sm:grid-cols-2 gap-3">
            <Field label="Nº de acolhimentos individuais"><input type="number" min="0" className={inputCls} style={inputStyle} value={form.acolhimentos} onChange={set("acolhimentos")} /></Field>
            <Field label="Casos apurados/resolvidos (externo)"><input type="number" min="0" className={inputCls} style={inputStyle} value={form.resolvidos} onChange={set("resolvidos")} /></Field>
          </div>
          <Field label="Afastamentos médicos CID-10 Grupo F"><input type="number" min="0" className={inputCls} style={inputStyle} value={form.afastamentos} onChange={set("afastamentos")} /></Field>
          <div className="grid sm:grid-cols-2 gap-3">
            <Field label="Desligamentos voluntários"><input type="number" min="0" className={inputCls} style={inputStyle} value={form.desligamentos} onChange={set("desligamentos")} /></Field>
            <Field label="Total de colaboradores (headcount)"><input type="number" min="1" className={inputCls} style={inputStyle} value={form.headcount} onChange={set("headcount")} /></Field>
          </div>
          <Field label="Plano de ação / status do clima"><textarea className={inputCls} style={{ ...inputStyle, minHeight: 80 }} placeholder="Ex: Rodada de acolhimento realizada em 15/05..." value={form.clima} onChange={set("clima")} /></Field>
          <Btn type="submit" variant="accent">Salvar registro</Btn>
        </form>
      </SectionCard>
      <SectionCard>
        <div className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Registros manuais salvos</div>
        {submissions.wellbeingManual.length === 0 ? <p className="text-sm italic" style={{ color: T.inkSoft }}>Nenhum registro ainda.</p> : (
          <div className="space-y-1.5">{submissions.wellbeingManual.slice().reverse().map((m) => (
            <div key={m.id} className="flex items-start justify-between gap-2 text-xs px-3 py-2 rounded-md" style={{ border: `1px solid ${T.line}` }}>
              <div><b>{m.fromDate} a {m.toDate}</b> · Acolh: {m.acolhimentos || 0} · Resolv: {m.resolvidos || 0} · Afast: {m.afastamentos || 0} · Deslig: {m.desligamentos || 0}/{m.headcount || "—"}{m.clima && <div style={{ color: T.inkSoft }}>{m.clima}</div>}</div>
              <button onClick={() => onDelete(m.id)} style={{ color: T.danger }}><Trash2 size={14} /></button>
            </div>
          ))}</div>
        )}
      </SectionCard>
    </div>
  );
}

function WellbeingRHPage({ pd, submissions, onSaveRelato, onDeleteRelato, onAddManual, onDeleteManual, setClima }) {
  const [tab, setTab] = useState("dashboard");
  const tabs = [["dashboard", "📊 Dashboard"], ["relatos", "📋 Relatos"], ["inserir", "✍️ Inserir dados"]];
  return (
    <div>
      <div className="mb-4"><div className="text-xs f-mono uppercase tracking-wide mb-1" style={{ color: T.cyan }}>Confidencial · Acesso restrito ao RH</div><h1 className="f-display text-2xl font-semibold" style={{ color: T.ink }}>Painel de Gestão · Saúde e Bem-Estar</h1></div>
      <div className="flex gap-2 mb-4">{tabs.map(([id, label]) => <button key={id} onClick={() => setTab(id)} className="px-3 py-1.5 rounded-md text-sm" style={{ background: tab === id ? T.ink : "transparent", color: tab === id ? "#fff" : T.inkSoft, border: `1px solid ${T.line}` }}>{label}</button>)}</div>
      {tab === "dashboard" && <WellbeingDashboardTab submissions={submissions} pd={pd} setClima={setClima} />}
      {tab === "relatos" && <WellbeingRelatosTab submissions={submissions} onSave={onSaveRelato} onDelete={onDeleteRelato} />}
      {tab === "inserir" && <WellbeingManualTab submissions={submissions} onAdd={onAddManual} onDelete={onDeleteManual} />}
    </div>

  );
}

function RoleSelect({ pd, onSelect, onSeedDemo, onOpenWellbeing }) {
  const roles = [
    { id: "rh", label: "Gestor de RH", desc: "Acesso completo às 6 fases, dados e relatórios.", icon: ClipboardList },
    { id: "dp", label: "Departamento Pessoal", desc: "Acompanha admissão, integração e desligamentos.", icon: Briefcase },
    { id: "cliente", label: "Direção", desc: "Acesso completo: acompanha e gerencia tudo, como o RH.", icon: Building2 },
    { id: "lideranca", label: "Liderança", desc: "Registra avaliações de desempenho da equipe.", icon: HeartHandshake },
    { id: "colaborador", label: "Colaborador", desc: "Responde formulários e pesquisas.", icon: Users },
    { id: "bemestar", label: "Canal de Saúde e Bem-Estar", desc: "Relato anônimo, sem necessidade de login.", icon: HeartPulse },
  ];
  const [picked, setPicked] = useState(null);
  const [seeded, setSeeded] = useState(false);
  return (
    <div className="min-h-screen flex items-center justify-center px-4 grid-paper" style={{ background: T.paper }}>
      <Frame className="rounded-2xl p-8 max-w-md w-full" style={{ background: T.paperRaised, border: `1px solid ${T.line}` }}>
        <div className="text-center mb-6"><span className="stamp text-xs font-semibold inline-block mb-3" style={{ color: T.cyan }}>DIU CONECTA</span><h1 className="f-display text-xl font-semibold" style={{ color: T.ink }}>Diu Conecta</h1><p className="text-sm mt-1" style={{ color: T.inkSoft }}>Selecione seu perfil de acesso</p></div>
        {picked !== "colaborador" ? (
          <div className="space-y-2">
            {roles.map((r) => (
              <button key={r.id} type="button" onClick={() => { if (r.id === "colaborador") { setPicked("colaborador"); } else if (r.id === "bemestar") { onOpenWellbeing(); } else { onSelect(r.id, "", null); } }} className="w-full flex items-center gap-3 text-left px-3 py-3 rounded-lg transition-colors hover:opacity-90" style={{ border: `1px solid ${T.line}`, background: "transparent" }}>
                <r.icon size={18} style={{ color: T.cyan }} /><div><div className="text-sm font-medium" style={{ color: T.ink }}>{r.label}</div><div className="text-xs" style={{ color: T.inkSoft }}>{r.desc}</div></div>
              </button>
            ))}
          </div>
        ) : (
          <div>
            <button type="button" onClick={() => setPicked(null)} className="text-xs f-mono mb-3" style={{ color: T.inkSoft }}>&larr; Voltar</button>
            <p className="text-xs f-mono uppercase tracking-wide mb-2" style={{ color: T.cyan }}>Selecione seu nome</p>
            <div className="space-y-1.5 max-h-72 overflow-y-auto scrollbar-thin">
              {pd.colaboradores.filter((c) => (c.status || "Ativo") === "Ativo").map((c) => (
                <button key={c.id} type="button" onClick={() => onSelect("colaborador", c.nome, c.id)} className="w-full text-left px-3 py-2.5 rounded-lg" style={{ border: `1px solid ${T.line}` }}>
                  <div className="text-sm font-medium" style={{ color: T.ink }}>{c.nome}</div><div className="text-xs" style={{ color: T.inkSoft }}>{c.cargo}</div>
                </button>
              ))}
              {pd.colaboradores.filter((c) => (c.status || "Ativo") === "Ativo").length === 0 && (
                <div>
                  <p className="text-sm italic mb-3" style={{ color: T.inkSoft }}>Nenhum colaborador ativo cadastrado.</p>
                  <Btn variant="accent" className="w-full justify-center" onClick={() => onSelect("colaborador", "Colaborador", null)}>Entrar mesmo assim <ChevronRight size={16} /></Btn>
                </div>
              )}
            </div>
          </div>
        )}
        <div className="mt-6 pt-4 text-center" style={{ borderTop: `1px solid ${T.line}` }}>
          {seeded ? <p className="text-xs" style={{ color: T.success }}>Dados de teste carregados — explore os perfis à vontade.</p> : (
            <button type="button" onClick={() => { onSeedDemo(); setSeeded(true); }} className="text-xs f-mono underline" style={{ color: T.inkSoft }}>Carregar dados de teste (versão piloto)</button>
          )}
        </div>
        <div className="mt-5 flex flex-col items-center gap-1 opacity-70">
          <img src={VIALE_LOGO} alt="Viale Soluções Empresariais" style={{ height: 34, width: "auto" }} />
          <span className="text-[10px] f-mono" style={{ color: T.inkSoft }}>desenvolvido por Viale Soluções Empresariais</span>
        </div>
      </Frame>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* APP SHELL                                                            */
/* ------------------------------------------------------------------ */
export default function App() {
  const [role, setRole] = useState(null);
  const [publicPage, setPublicPage] = useState(null);
  const [certificateView, setCertificateView] = useState(null);
  const [historicoColaboradorId, setHistoricoColaboradorId] = useState(null);
  const [userName, setUserName] = useState("");
  const [myColaboradorId, setMyColaboradorId] = useState(null);
  const [view, setView] = useState("dashboard");

  const [programData, updateProgram] = useShared("program-data", DEFAULT_PROGRAM_DATA, normalizeProgramData);
  const [submissions, updateSubmissions] = useShared("submissions", DEFAULT_SUBMISSIONS, normalizeSubmissions);
  const [turnover, updateTurnover] = useShared("turnover-data", DEFAULT_TURNOVER, normalizeTurnover);
  const [atestados, updateAtestados] = useShared("atestados-list", [], (v) => (Array.isArray(v) ? v : []));
  const [adiantamentos, updateAdiantamentos] = useShared("adiantamentos-list", [], (v) => (Array.isArray(v) ? v : []));
  const [solicitacoes, updateSolicitacoes] = useShared("solicitacoes-list", [], (v) => (Array.isArray(v) ? v : []));
  const [justificativas, updateJustificativas] = useShared("justificativas-list", [], (v) => (Array.isArray(v) ? v : []));
  const [odonto, updateOdonto] = useShared("odonto-list", [], (v) => (Array.isArray(v) ? v : []));
  const [notasRH, updateNotasRH] = useShared("notas-rh", [], (v) => (Array.isArray(v) ? v : []));
  const addAdiantamento = (item) => updateAdiantamentos((a) => [...a, item]);
  const addSolicitacao = (item) => updateSolicitacoes((s) => [...s, item]);
  const updateSolicitacao = (id, patch) => updateSolicitacoes((s) => s.map((x) => (x.id === id ? { ...x, ...patch } : x)));
  const deleteSolicitacao = (id) => updateSolicitacoes((s) => s.filter((x) => x.id !== id));
  const addEvento = (item) => updateProgram((p) => ({ ...p, eventosEducacao: [...p.eventosEducacao, item] }));
  const toggleParticipanteEvento = (eventoId, empId) => updateProgram((p) => ({ ...p, eventosEducacao: p.eventosEducacao.map((ev) => ev.id === eventoId ? { ...ev, participantes: { ...ev.participantes, [empId]: !ev.participantes[empId] } } : ev) }));
  const deleteEvento = (id) => updateProgram((p) => ({ ...p, eventosEducacao: p.eventosEducacao.filter((ev) => ev.id !== id) }));
  const saveFechamentoPrestadores = (entry) => updateProgram((p) => {
    const exists = p.fechamentosPrestadores.some((f) => f.id === entry.id);
    return { ...p, fechamentosPrestadores: exists ? p.fechamentosPrestadores.map((f) => (f.id === entry.id ? entry : f)) : [...p.fechamentosPrestadores, entry] };
  });
  const addDiuVintemLancamento = (item) => updateProgram((p) => ({ ...p, diuVintemLancamentos: [...p.diuVintemLancamentos, item] }));
  const deleteDiuVintemLancamento = (id) => updateProgram((p) => ({ ...p, diuVintemLancamentos: p.diuVintemLancamentos.filter((x) => x.id !== id) }));
  const addDiuVintemResgate = (item) => updateProgram((p) => ({ ...p, diuVintemResgates: [...p.diuVintemResgates, item] }));
  const addJustificativa = (item) => updateJustificativas((j) => [...j, item]);
  const addOdonto = (item) => updateOdonto((o) => [...o, item]);
  const addNotaRH = (item) => updateNotasRH((n) => [...n, item]);
  const deleteNotaRH = (id) => updateNotasRH((n) => n.filter((x) => x.id !== id));
  const markOdonto = (id, status) => updateOdonto((o) => o.map((x) => (x.id === id ? { ...x, status } : x)));
  const deleteOdonto = (id) => updateOdonto((o) => o.filter((x) => x.id !== id));
  const setOdontoCorretor = (v) => updateProgram((p) => ({ ...p, odontoCorretorWhatsapp: v }));
  const updateJustificativa = (id, patch) => updateJustificativas((j) => j.map((x) => (x.id === id ? { ...x, ...patch } : x)));
  const deleteJustificativa = (id) => updateJustificativas((j) => j.filter((x) => x.id !== id));
  const updateAdiantamento = (id, patch) => updateAdiantamentos((a) => a.map((x) => (x.id === id ? { ...x, ...patch } : x)));
  const deleteAdiantamento = (id) => updateAdiantamentos((a) => a.filter((x) => x.id !== id));
  const markAtestadoVisto = (id) => updateAtestados((a) => a.map((x) => (x.id === id ? { ...x, status: "visto" } : x)));
  const deleteAtestado = (id) => { updateAtestados((a) => a.filter((x) => x.id !== id)); window.storage.delete(`atestado-file:${id}`, true).catch(() => {}); };

  const loading = !programData || !submissions || !turnover || !atestados || !adiantamentos || !solicitacoes || !justificativas || !odonto || !notasRH;

  const mk = currentMonthKey();
  const toggleChecklist = (id) => updateProgram((p) => ({ ...p, checklistHistory: { ...p.checklistHistory, [mk]: { ...(p.checklistHistory[mk] || {}), [id]: { done: !p.checklistHistory[mk]?.[id]?.done } } } }));
  const setClientName = (clientName) => updateProgram((p) => ({ ...p, clientName }));
  const setEthicsText = (ethicsText) => updateProgram((p) => ({ ...p, ethicsText }));
  const setAuth = (auth) => updateProgram((p) => ({ ...p, auth }));
  const setConvencaoColetiva = (doc) => updateProgram((p) => ({ ...p, convencaoColetiva: doc }));
  const removeConvencaoColetiva = () => updateProgram((p) => ({ ...p, convencaoColetiva: null }));
  const setCultureField = (field, value) => updateProgram((p) => ({ ...p, culture: { ...p.culture, [field]: value } }));
  const addValor = (v) => updateProgram((p) => ({ ...p, culture: { ...p.culture, valores: [...p.culture.valores, v] } }));
  const removeValor = (idx) => updateProgram((p) => ({ ...p, culture: { ...p.culture, valores: p.culture.valores.filter((_, i) => i !== idx) } }));

  const addTo = (field) => (item) => updateProgram((p) => ({ ...p, [field]: [...p[field], item] }));
  const delFrom = (field) => (id) => updateProgram((p) => ({ ...p, [field]: p[field].filter((x) => x.id !== id) }));

  const updateProcess = (id, next) => updateProgram((p) => ({ ...p, processes: p.processes.map((pr) => (pr.id === id ? next : pr)) }));
  const addProcess = (nome) => updateProgram((p) => ({ ...p, processes: [...p.processes, { id: Date.now() + "", nome, etapas: [], riscos: [] }] }));
  const deleteProcess = (id) => updateProgram((p) => ({ ...p, processes: p.processes.filter((pr) => pr.id !== id) }));

  const generateAlignment = (valor) => updateProgram((p) => ({ ...p, alignmentActions: { ...p.alignmentActions, [valor]: suggestFor(valor).map((t, i) => ({ id: `${Date.now()}-${i}`, text: t, done: false })) } }));
  const toggleAlignmentAction = (valor, id) => updateProgram((p) => ({ ...p, alignmentActions: { ...p.alignmentActions, [valor]: (p.alignmentActions[valor] || []).map((a) => (a.id === id ? { ...a, done: !a.done } : a)) } }));
  const addAlignmentAction = (valor, text) => updateProgram((p) => ({ ...p, alignmentActions: { ...p.alignmentActions, [valor]: [...(p.alignmentActions[valor] || []), { id: Date.now() + "", text, done: false }] } }));
  const removeAlignmentAction = (valor, id) => updateProgram((p) => ({ ...p, alignmentActions: { ...p.alignmentActions, [valor]: (p.alignmentActions[valor] || []).filter((a) => a.id !== id) } }));

  const generateOnboarding = (cargo) => updateProgram((p) => ({ ...p, onboardingTemplates: [...p.onboardingTemplates, { id: Date.now() + "", cargo, tasks: buildOnboardingTemplate(cargo) }] }));
  const deleteOnboardingTemplate = (id) => updateProgram((p) => ({ ...p, onboardingTemplates: p.onboardingTemplates.filter((t) => t.id !== id) }));
  const addOnboardingTask = (templateId, period, text) => updateProgram((p) => ({ ...p, onboardingTemplates: p.onboardingTemplates.map((t) => (t.id === templateId ? { ...t, tasks: { ...t.tasks, [period]: [...t.tasks[period], { id: Date.now() + "", text }] } } : t)) }));
  const removeOnboardingTask = (templateId, period, taskId) => updateProgram((p) => ({ ...p, onboardingTemplates: p.onboardingTemplates.map((t) => (t.id === templateId ? { ...t, tasks: { ...t.tasks, [period]: t.tasks[period].filter((tk) => tk.id !== taskId) } } : t)) }));

  const setFeedbackObjetivo = (v) => updateProgram((p) => ({ ...p, feedbackPolicy: { ...p.feedbackPolicy, objetivo: v } }));
  const setFeedbackNotas = (v) => updateProgram((p) => ({ ...p, feedbackPolicy: { ...p.feedbackPolicy, notasAtual: v } }));
  const addFeedbackTipo = (item) => updateProgram((p) => ({ ...p, feedbackPolicy: { ...p.feedbackPolicy, tipos: [...p.feedbackPolicy.tipos, item] } }));
  const removeFeedbackTipo = (id) => updateProgram((p) => ({ ...p, feedbackPolicy: { ...p.feedbackPolicy, tipos: p.feedbackPolicy.tipos.filter((t) => t.id !== id) } }));

  const addColaborador = (c) => updateProgram((p) => ({ ...p, colaboradores: [...p.colaboradores, c] }));
  const removeColaborador = (id) => updateProgram((p) => ({ ...p, colaboradores: p.colaboradores.filter((c) => c.id !== id) }));
  const assignOnboarding = (empId, templateId) => updateProgram((p) => ({ ...p, onboardingAssignments: { ...p.onboardingAssignments, [empId]: { templateId, progress: {} } } }));
  const toggleOnboardingTask = (empId, taskId) => updateProgram((p) => { const a = p.onboardingAssignments[empId]; if (!a) return p; return { ...p, onboardingAssignments: { ...p.onboardingAssignments, [empId]: { ...a, progress: { ...a.progress, [taskId]: !a.progress[taskId] } } } }; });
  const toggleTraining = (empId, trainingId) => updateProgram((p) => { const cur = p.trainingCompletions[empId] || {}; const rec = cur[trainingId]; const prevDone = rec && typeof rec === "object" ? rec.done : !!rec; const prevScore = rec && typeof rec === "object" ? rec.score : null; const nowDone = !prevDone; return { ...p, trainingCompletions: { ...p.trainingCompletions, [empId]: { ...cur, [trainingId]: { done: nowDone, score: prevScore, date: nowDone ? new Date().toLocaleDateString("pt-BR") : (rec && rec.date) } } } }; });
  const setTrainingScore = (empId, trainingId, score) => updateProgram((p) => { const cur = p.trainingCompletions[empId] || {}; const rec = cur[trainingId]; const prevDone = rec && typeof rec === "object" ? rec.done : !!rec; const prevDate = rec && typeof rec === "object" ? rec.date : null; return { ...p, trainingCompletions: { ...p.trainingCompletions, [empId]: { ...cur, [trainingId]: { done: prevDone, score, date: prevDate } } } }; });
  const toggleIntegrationItem = (empId, idx) => updateProgram((p) => { const cur = p.integrationChecklist[empId] || {}; return { ...p, integrationChecklist: { ...p.integrationChecklist, [empId]: { ...cur, [idx]: !cur[idx] } } }; });
  const setColaboradorStatus = (empId, status) => updateProgram((p) => ({ ...p, colaboradores: p.colaboradores.map((c) => (c.id === empId ? { ...c, status } : c)) }));
  const toggleAdmissaoStep = (empId, stepId) => updateProgram((p) => { const cur = p.admissaoChecklist[empId] || {}; return { ...p, admissaoChecklist: { ...p.admissaoChecklist, [empId]: { ...cur, [stepId]: !cur[stepId] } } }; });
  const toggleDesligamentoStep = (empId, stepId) => updateProgram((p) => { const cur = p.desligamentoChecklist[empId] || {}; return { ...p, desligamentoChecklist: { ...p.desligamentoChecklist, [empId]: { ...cur, [stepId]: !cur[stepId] } } }; });
  const completeTrainingWithScore = (empId, trainingId, score) => updateProgram((p) => { const cur = p.trainingCompletions[empId] || {}; return { ...p, trainingCompletions: { ...p.trainingCompletions, [empId]: { ...cur, [trainingId]: { done: true, score, date: new Date().toLocaleDateString("pt-BR") } } } }; });

  const addDiagnostico = (item) => updateSubmissions((s) => ({ ...s, diagnostico: [...s.diagnostico, item] }));
  const addFeedback = (item) => updateSubmissions((s) => ({ ...s, feedback: [...s.feedback, item] }));
  const ackEthics = (item) => updateSubmissions((s) => ({ ...s, ethicsAck: [...s.ethicsAck, item] }));
  const ackMuv = (item) => updateSubmissions((s) => ({ ...s, muvAck: [...s.muvAck, item] }));
  const addLeaderEvaluation = (item) => updateSubmissions((s) => ({ ...s, leaderEvaluations: [...s.leaderEvaluations, item] }));
  const addCandidateEvaluation = (item) => updateSubmissions((s) => ({ ...s, candidateEvaluations: [...s.candidateEvaluations, item] }));
  const addWellbeingReport = (item) => updateSubmissions((s) => ({ ...s, wellbeing: [...s.wellbeing, item] }));
  const saveWellbeingRelato = (id, patch) => updateSubmissions((s) => ({ ...s, wellbeing: s.wellbeing.map((r) => (r.id === id ? { ...r, ...patch } : r)) }));
  const deleteWellbeingRelato = (id) => updateSubmissions((s) => ({ ...s, wellbeing: s.wellbeing.filter((r) => r.id !== id) }));
  const addWellbeingManual = (item) => updateSubmissions((s) => ({ ...s, wellbeingManual: [...s.wellbeingManual, item] }));
  const deleteWellbeingManual = (id) => updateSubmissions((s) => ({ ...s, wellbeingManual: s.wellbeingManual.filter((m) => m.id !== id) }));
  const setWellbeingClima = (text) => updateProgram((p) => ({ ...p, wellbeingClima: text }));
  const addTurnoverEntry = (item) => updateTurnover((t) => ({ ...t, entries: [...t.entries, item] }));
  const delTurnoverEntry = (id) => updateTurnover((t) => ({ ...t, entries: t.entries.filter((x) => x.id !== id) }));
  const seedDemoData = () => {
    const { pd, empId } = buildDemoSeed(programData);
    updateProgram(() => pd);
    updateSubmissions((s) => buildDemoSubmissions(s, empId));
    updateTurnover((t) => buildDemoTurnover(t));
  };

  if (loading) return <div className="min-h-screen flex items-center justify-center f-body" style={{ background: T.paper }}><style>{FONT_CSS}</style><div className="flex flex-col items-center gap-2" style={{ color: T.inkSoft }}><Loader2 className="animate-spin" /><span className="text-sm f-mono">Carregando dados do programa…</span></div></div>;

  if (publicPage === "bemestar") return <div className="f-body"><style>{FONT_CSS}</style><WellbeingChannel onSubmit={addWellbeingReport} onBack={() => setPublicPage(null)} /></div>;

  if (!role) return <div className="f-body"><style>{FONT_CSS}</style><RoleSelect pd={programData} onSelect={(r, n, cid) => { setRole(r); setUserName(n); setMyColaboradorId(cid); setView(r === "dp" ? "dp" : "dashboard"); }} onSeedDemo={seedDemoData} onOpenWellbeing={() => setPublicPage("bemestar")} /></div>;

  if (role === "colaborador") {
    return (
      <div className="min-h-screen f-body grid-paper" style={{ background: T.paper }}><style>{FONT_CSS}</style>
        <div className="flex justify-end px-4 pt-4 no-print"><button onClick={() => setRole(null)} className="text-xs f-mono flex items-center gap-1" style={{ color: T.inkSoft }}><LogOut size={13} /> Trocar perfil</button></div>
        <div className="px-4 pb-16 pt-2"><EmployeePortal pd={programData} submissions={submissions} myColaboradorId={myColaboradorId} addDiagnostico={addDiagnostico} addFeedback={addFeedback} ackEthics={ackEthics} ackMuv={ackMuv} onCompleteTraining={completeTrainingWithScore} addAtestado={(item) => updateAtestados((a) => [...a, item])} adiantamentos={adiantamentos} addAdiantamento={addAdiantamento} solicitacoes={solicitacoes} addSolicitacao={addSolicitacao} justificativas={justificativas} addJustificativa={addJustificativa} odonto={odonto} addOdonto={addOdonto} /></div>
      </div>
    );
  }

  const colabProps = { pd: programData, submissions, role, addColaborador, removeColaborador, assignOnboarding, toggleOnboardingTask, toggleTraining, setTrainingScore, toggleIntegrationItem, addLeaderEvaluation, setColaboradorStatus };

  if (role === "lideranca") {
    return (
      <div className="min-h-screen f-body grid-paper" style={{ background: T.paper }}><style>{FONT_CSS}</style>
        <div className="flex justify-between items-center px-4 pt-4 no-print">
          <div className="flex gap-2">
            <button onClick={() => setView("colaboradores")} className="text-xs f-mono px-3 py-1.5 rounded-md" style={{ background: view === "colaboradores" ? T.cyan : "transparent", color: view === "colaboradores" ? "#fff" : T.inkSoft, border: `1px solid ${T.line}` }}>Equipe</button>
            <button onClick={() => setView("seletivo")} className="text-xs f-mono px-3 py-1.5 rounded-md" style={{ background: view === "seletivo" ? T.cyan : "transparent", color: view === "seletivo" ? "#fff" : T.inkSoft, border: `1px solid ${T.line}` }}>Processo Seletivo</button>
          </div>
          <button onClick={() => setRole(null)} className="text-xs f-mono flex items-center gap-1" style={{ color: T.inkSoft }}><LogOut size={13} /> Trocar perfil</button>
        </div>
        <div className="max-w-4xl mx-auto px-4 pb-16 pt-2">
          {view === "seletivo" ? <SeletivoPage submissions={submissions} role={role} addCandidateEvaluation={addCandidateEvaluation} /> : <ColaboradoresPage {...colabProps} />}
        </div>
      </div>
    );
  }

  if (role === "dp") {
    return (
      <div className="min-h-screen f-body grid-paper" style={{ background: T.paper }}><style>{FONT_CSS}</style>
        <div className="flex justify-between items-center px-4 pt-4 no-print">
          <div className="flex gap-2">
            <button onClick={() => setView("dp")} className="text-xs f-mono px-3 py-1.5 rounded-md" style={{ background: !["atestados", "adiantamentos", "solicitacoes", "justificativas", "prestadores", "diuvintem", "odonto", "relatorios", "historico"].includes(view) ? T.cyan : "transparent", color: !["atestados", "adiantamentos", "solicitacoes", "justificativas", "prestadores", "diuvintem", "odonto", "relatorios", "historico"].includes(view) ? "#fff" : T.inkSoft, border: `1px solid ${T.line}` }}>Painel DP</button>
            <button onClick={() => setView("atestados")} className="text-xs f-mono px-3 py-1.5 rounded-md" style={{ background: view === "atestados" ? T.cyan : "transparent", color: view === "atestados" ? "#fff" : T.inkSoft, border: `1px solid ${T.line}` }}>Atestados</button>
            <button onClick={() => setView("adiantamentos")} className="text-xs f-mono px-3 py-1.5 rounded-md" style={{ background: view === "adiantamentos" ? T.cyan : "transparent", color: view === "adiantamentos" ? "#fff" : T.inkSoft, border: `1px solid ${T.line}` }}>Adiantamentos</button>
            <button onClick={() => setView("solicitacoes")} className="text-xs f-mono px-3 py-1.5 rounded-md" style={{ background: view === "solicitacoes" ? T.cyan : "transparent", color: view === "solicitacoes" ? "#fff" : T.inkSoft, border: `1px solid ${T.line}` }}>Solicitações</button>
            <button onClick={() => setView("justificativas")} className="text-xs f-mono px-3 py-1.5 rounded-md" style={{ background: view === "justificativas" ? T.cyan : "transparent", color: view === "justificativas" ? "#fff" : T.inkSoft, border: `1px solid ${T.line}` }}>Ponto</button>
            <button onClick={() => setView("prestadores")} className="text-xs f-mono px-3 py-1.5 rounded-md" style={{ background: view === "prestadores" ? T.cyan : "transparent", color: view === "prestadores" ? "#fff" : T.inkSoft, border: `1px solid ${T.line}` }}>Prestadores</button>
            <button onClick={() => setView("diuvintem")} className="text-xs f-mono px-3 py-1.5 rounded-md" style={{ background: view === "diuvintem" ? T.cyan : "transparent", color: view === "diuvintem" ? "#fff" : T.inkSoft, border: `1px solid ${T.line}` }}>Diu Vintém</button>
            <button onClick={() => setView("odonto")} className="text-xs f-mono px-3 py-1.5 rounded-md" style={{ background: view === "odonto" ? T.cyan : "transparent", color: view === "odonto" ? "#fff" : T.inkSoft, border: `1px solid ${T.line}` }}>Odonto</button>
            <button onClick={() => setView("relatorios")} className="text-xs f-mono px-3 py-1.5 rounded-md" style={{ background: view === "relatorios" ? T.cyan : "transparent", color: view === "relatorios" ? "#fff" : T.inkSoft, border: `1px solid ${T.line}` }}>Relatórios</button>
            <button onClick={() => setView("historico")} className="text-xs f-mono px-3 py-1.5 rounded-md" style={{ background: view === "historico" ? T.cyan : "transparent", color: view === "historico" ? "#fff" : T.inkSoft, border: `1px solid ${T.line}` }}>Desempenho</button>
          </div>
          <button onClick={() => setRole(null)} className="text-xs f-mono flex items-center gap-1" style={{ color: T.inkSoft }}><LogOut size={13} /> Trocar perfil</button>
        </div>
        <div className="max-w-4xl mx-auto px-4 pb-16 pt-2">
          {view === "atestados" ? <AtestadosRHPage list={atestados} onMarkVisto={markAtestadoVisto} onDelete={deleteAtestado} />
            : view === "adiantamentos" ? <AdiantamentosPage list={adiantamentos} role="dp" onUpdate={updateAdiantamento} onDelete={deleteAdiantamento} />
            : view === "solicitacoes" ? <SolicitacoesPage list={solicitacoes} onUpdate={updateSolicitacao} onDelete={deleteSolicitacao} />
            : view === "justificativas" ? <JustificativasPage list={justificativas} onUpdate={updateJustificativa} onDelete={deleteJustificativa} />
            : view === "prestadores" ? <FechamentoPrestadoresForm pd={programData} onSave={saveFechamentoPrestadores} />
            : view === "diuvintem" ? <DiuVintemRHPage pd={programData} lancamentos={programData.diuVintemLancamentos} resgates={programData.diuVintemResgates} onAddLancamento={addDiuVintemLancamento} onAddResgate={addDiuVintemResgate} onDeleteLancamento={deleteDiuVintemLancamento} />
            : view === "odonto" ? <OdontoRHPage pd={programData} list={odonto} onMark={markOdonto} onDelete={deleteOdonto} onSetCorretor={setOdontoCorretor} />
            : view === "relatorios" ? <MonthlyReport pd={programData} submissions={submissions} turnover={turnover} atestados={atestados} justificativas={justificativas} onSelectColaborador={(id) => { setHistoricoColaboradorId(id); setView("historico"); }} />
            : view === "historico" ? <EmployeeMonthlyHistory pd={programData} submissions={submissions} atestados={atestados} justificativas={justificativas} role={role} selectedId={historicoColaboradorId} onSelectId={setHistoricoColaboradorId} notasRH={notasRH} onAddNota={addNotaRH} onDeleteNota={deleteNotaRH} />
            : <DPPanel pd={programData} atestados={atestados} adiantamentos={adiantamentos} solicitacoes={solicitacoes} justificativas={justificativas} onNavigate={setView} toggleAdmissaoStep={toggleAdmissaoStep} toggleDesligamentoStep={toggleDesligamentoStep} toggleIntegrationItem={toggleIntegrationItem} />}
        </div>
      </div>
    );
  }

  if (certificateView) return <div className="f-body"><style>{FONT_CSS}</style><CertificadoFullPage evento={certificateView.evento} colaborador={certificateView.colaborador} clientName={programData.clientName} onClose={() => setCertificateView(null)} /></div>;

  const readOnly = false; // Direção (cliente) agora tem acesso completo, igual ao RH
  const phaseProps = {
    pd: programData, mk, toggle: toggleChecklist, submissions, turnover, readOnly,
    addPartnership: addTo("partnerships"), delPartnership: delFrom("partnerships"),
    addWorkshop: addTo("workshops"), delWorkshop: delFrom("workshops"),
    addChannel: addTo("channels"), delChannel: delFrom("channels"),
    addEvent: addTo("calendarEvents"), delEvent: delFrom("calendarEvents"),
    addTraining: addTo("trainings"), delTraining: delFrom("trainings"),
    setCultureField, addValor, removeValor,
    generateAlignment, toggleAlignmentAction, addAlignmentAction, removeAlignmentAction,
    setEthicsText,
    generateOnboarding, deleteOnboardingTemplate, addOnboardingTask, removeOnboardingTask,
    setFeedbackObjetivo, setFeedbackNotas, addFeedbackTipo, removeFeedbackTipo,
    updateProcess, addProcess, deleteProcess,
    addEntry: addTurnoverEntry, delEntry: delTurnoverEntry,
  };

  const pages = {
    dashboard: <Dashboard role={role} programData={programData} submissions={submissions} onNavigate={setView} onClientName={setClientName} onSaveAuth={setAuth} onSaveConvencao={setConvencaoColetiva} onRemoveConvencao={removeConvencaoColetiva} />,
    colaboradores: <ColaboradoresPage {...colabProps} />,
    seletivo: <SeletivoPage submissions={submissions} role={role} addCandidateEvaluation={addCandidateEvaluation} />,
    dp: <DPPanel pd={programData} atestados={atestados} adiantamentos={adiantamentos} solicitacoes={solicitacoes} justificativas={justificativas} onNavigate={setView} toggleAdmissaoStep={toggleAdmissaoStep} toggleDesligamentoStep={toggleDesligamentoStep} toggleIntegrationItem={toggleIntegrationItem} />,
    bemestar: <WellbeingRHPage pd={programData} submissions={submissions} onSaveRelato={saveWellbeingRelato} onDeleteRelato={deleteWellbeingRelato} onAddManual={addWellbeingManual} onDeleteManual={deleteWellbeingManual} setClima={setWellbeingClima} />,
    atestados: <AtestadosRHPage list={atestados} onMarkVisto={markAtestadoVisto} onDelete={deleteAtestado} />,
    adiantamentos: <AdiantamentosPage list={adiantamentos} role={role} onUpdate={updateAdiantamento} onDelete={deleteAdiantamento} />,
    solicitacoes: <SolicitacoesPage list={solicitacoes} onUpdate={updateSolicitacao} onDelete={deleteSolicitacao} />,
    justificativas: <JustificativasPage list={justificativas} onUpdate={updateJustificativa} onDelete={deleteJustificativa} />,
    odonto: <OdontoRHPage pd={programData} list={odonto} onMark={markOdonto} onDelete={deleteOdonto} onSetCorretor={setOdontoCorretor} />,
    treinamentos: <TreinamentosResultsPage pd={programData} />,
    educacao: <EducacaoContinuadaPage pd={programData} onAddEvento={addEvento} onToggleParticipante={toggleParticipanteEvento} onDeleteEvento={deleteEvento} onOpenCertificado={(evento, colaborador) => setCertificateView({ evento, colaborador })} />,
    prestadores: <FechamentoPrestadoresRHPage pd={programData} />,
    diuvintem: <DiuVintemRHPage pd={programData} lancamentos={programData.diuVintemLancamentos} resgates={programData.diuVintemResgates} onAddLancamento={addDiuVintemLancamento} onAddResgate={addDiuVintemResgate} onDeleteLancamento={deleteDiuVintemLancamento} />,
    relatorios: <MonthlyReport pd={programData} submissions={submissions} turnover={turnover} atestados={atestados} justificativas={justificativas} onSelectColaborador={(id) => { setHistoricoColaboradorId(id); setView("historico"); }} />,
    historico: <EmployeeMonthlyHistory pd={programData} submissions={submissions} atestados={atestados} justificativas={justificativas} role={role} selectedId={historicoColaboradorId} onSelectId={setHistoricoColaboradorId} notasRH={notasRH} onAddNota={addNotaRH} onDeleteNota={deleteNotaRH} />,
    fase1: <Phase1 {...phaseProps} />, fase2: <Phase2 {...phaseProps} />, fase3: <Phase3 {...phaseProps} />,
    fase4: <Phase4 {...phaseProps} />, fase5: <Phase5 {...phaseProps} />, fase6: <Phase6 {...phaseProps} />,
  };

  return (
    <div className="min-h-screen f-body flex" style={{ background: T.paper }}><style>{FONT_CSS}</style>
      <aside className="w-64 shrink-0 hidden sm:flex flex-col no-print" style={{ background: T.ink }}>
        <div className="p-5 border-b" style={{ borderColor: "#ffffff22" }}><span className="stamp text-[10px] font-semibold inline-block" style={{ color: T.cyan }}>DIU CONECTA</span><h1 className="f-display text-base font-semibold text-white mt-2 leading-snug">{programData.clientName || "Diu Conecta"}</h1></div>
        <nav className="flex-1 p-3 space-y-1 overflow-y-auto scrollbar-thin">
          {[
            { label: "Visão Geral", items: [
              { id: "dashboard", label: "Painel Geral", icon: TrendingUp },
              { id: "relatorios", label: "Relatórios Mensais", icon: CalendarClock },
              { id: "historico", label: "Desempenho por Colaborador", icon: TrendingUp },
            ] },
            { label: "Pessoas", items: [
              { id: "colaboradores", label: "Colaboradores", icon: Users },
              { id: "seletivo", label: "Processo Seletivo", icon: UserPlus },
              { id: "dp", label: "Painel DP", icon: ShieldCheck },
            ] },
            { label: "Solicitações do Colaborador", items: [
              { id: "atestados", label: "Atestados", icon: Paperclip },
              { id: "adiantamentos", label: "Adiantamentos", icon: Wallet },
              { id: "solicitacoes", label: "Férias e Dúvidas", icon: HelpCircle },
              { id: "justificativas", label: "Ponto", icon: Clock },
              { id: "odonto", label: "Plano Odontológico", icon: HeartPulse },
            ] },
            { label: "Desenvolvimento", items: [
              { id: "treinamentos", label: "Treinamentos", icon: GraduationCap },
              { id: "educacao", label: "Educação Continuada", icon: Award },
              { id: "diuvintem", label: "Diu Vintém", icon: Coins },
            ] },
            { label: "Operações", items: [
              { id: "prestadores", label: "Fechamento Prestadores", icon: Briefcase },
            ] },
            { label: "Confidencial", items: [
              { id: "bemestar", label: "Saúde e Bem-Estar", icon: HeartHandshake },
            ] },
          ].map((group) => (
            <div key={group.label}>
              <div className="text-[10px] f-mono uppercase tracking-wide px-3 pt-3 pb-1" style={{ color: "#ffffff66" }}>{group.label}</div>
              {group.items.map((it) => (
                <button key={it.id} onClick={() => setView(it.id)} className="w-full text-left px-3 py-2 rounded-md text-sm flex items-center gap-2" style={{ background: view === it.id ? T.cyan : "transparent", color: "#fff" }}><it.icon size={15} /> {it.label}</button>
              ))}
            </div>
          ))}
          <div>
            <div className="text-[10px] f-mono uppercase tracking-wide px-3 pt-3 pb-1" style={{ color: "#ffffff66" }}>Programa · 6 Fases</div>
            {PHASES.map((p) => { const Icon = p.icon; const active = view === p.id; return (
              <button key={p.id} onClick={() => setView(p.id)} className="w-full text-left px-3 py-2 rounded-md text-sm flex items-start gap-2" style={{ background: active ? T.cyan : "transparent", color: "#fff" }}><Icon size={15} className="mt-0.5 shrink-0" /><span><span className="f-mono text-[10px] block opacity-70">0{p.n}</span>{p.title}</span></button>
            ); })}
          </div>
        </nav>
        <div className="p-3 border-t text-xs flex items-center justify-between" style={{ borderColor: "#ffffff22", color: "#ffffffaa" }}><span>{role === "rh" ? "Gestor de RH" : "Direção"} {userName && `· ${userName}`}</span><button onClick={() => setRole(null)} title="Trocar perfil"><LogOut size={14} /></button></div>
        <div className="px-3 pb-3 flex justify-center opacity-60"><img src={VIALE_LOGO} alt="Viale Soluções Empresariais" style={{ height: 22, width: "auto" }} /></div>
      </aside>
      <div className="sm:hidden fixed bottom-0 left-0 right-0 z-10 flex overflow-x-auto no-print" style={{ background: T.ink }}>
        {[
          ["dashboard", "Painel"], ["relatorios", "Relatórios"], ["historico", "Desempenho"], ["colaboradores", "Equipe"], ["seletivo", "Seletivo"], ["dp", "DP"],
          ["atestados", "Atestados"], ["adiantamentos", "Adiant."], ["solicitacoes", "Solicit."], ["justificativas", "Ponto"], ["odonto", "Odonto"],
          ["treinamentos", "Treinos"], ["educacao", "Educação"], ["diuvintem", "Vintém"], ["prestadores", "Prestad."], ["bemestar", "Bem-Estar"],
        ].map(([id, label]) => (
          <button key={id} onClick={() => setView(id)} className="px-3 py-2 text-xs shrink-0" style={{ color: view === id ? T.cyan : "#fff" }}>{label}</button>
        ))}
        {PHASES.map((p) => <button key={p.id} onClick={() => setView(p.id)} className="px-3 py-2 text-xs shrink-0" style={{ color: view === p.id ? T.cyan : "#fff" }}>F{p.n}</button>)}
      </div>
      <main className="flex-1 grid-paper"><div className="max-w-4xl mx-auto px-5 py-6 pb-20 sm:pb-10">{pages[view]}</div></main>
    </div>
  );
}
